INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('04ffb7fa-1879-4a70-baca-bfe5908d705c', 'fact-check-underwater-metro-in-sabarmati-river-edited-photo', 236, 'Fact Check: Viral Image of Underwater Metro Tunnel under Sabarmati River is Computer Generated', 'ફેક્ટ ચેક: અમદાવાદમાં સાબરમતી નદી નીચે અંડરવોટર મેટ્રો ટનલ શરૂ થયાનું વાયરલ ચિત્ર AI એડિટેડ છે', 'फैक्ट चेक: साबरमती नदी के नीचे अंडरवाटर मेट्रो सुरंग शुरू होने की वायरल तस्वीर एआई एडिटेड है', 'Viral photographs claiming Ahmedabad Metro started underwater glass-tunnel services under Sabarmati river are digital artwork and not real.', 'સાબરમતી નદીના કાચની અંડરવોટર ટનલમાંથી પસાર થતી મેટ્રો ટ્રેનનું દ્રશ્ય વાસ્તવિક નથી પરંતુ ડિજિટલ આર્ટવર્ક છે.', 'साबरमती नदी के कांच की टनल से गुजरती मेट्रो की तस्वीर वास्तविक नहीं बल्कि डिजिटल आर्टवर्क है।', '<p><strong>Claim:</strong> Social media posts share high-definition photos claiming Ahmedabad Metro opened India\'s underwater glass tunnel line under the Sabarmati Riverfront.</p>\n<h2>Fact Check Analysis</h2>\n<p>Ahmedabad Metro Rail Project Phase 1 & Phase 2 operate via elevated viaducts and underground sections across the city. None of the lines pass through a glass underwater tunnel beneath the river.</p>\n<ul>\n<li>Digital forensic inspection confirms the image was generated using Midjourney AI software.</li>\n<li>India\'s actual underwater metro tunnel passes under the Hooghly River in Kolkata, which is a standard concrete tunnel, not transparent glass.</li>\n</ul>\n<blockquote>"Verdict: 🖼️ EDITED AI ARTWORK. Not an actual photograph of Ahmedabad Metro."</blockquote>', '<p><strong>દાવો:</strong> અમદાવાદમાં સાબરમતી રિવરફ્રન્ટ નીચે કાચની અંડરવોટર મેટ્રો ટનલમાંથી પસાર થતી મેટ્રો ટ્રેનનો ફોટો સોશિયલ મીડિયા પર ભારે વાયરલ થઈ રહ્યો છે.</p>\n<h2>તપાસ અને તથ્ય</h2>\n<p>ગુજરાત પોસ્ટ ફેક્ટ ચેક ટીમે ગુજરાત મેટ્રો રેલ કોર્પોરેશન (GMRC) નો સંપર્ક કર્યો હતો. અધિકારીઓએ બતાવ્યું કે સાબરમતી નદી નીચે આવી કોઈ કાચની ટનલ બનાવવામાં આવી નથી.</p>\n<ul>\n<li>ઇમેજ ફોરેન્સિક એનાલિસિસ દ્વારા સાબિત થયું છે કે આ ચિત્ર AI ઇમેજ જનરેટર સૉફ્ટવેર દ્વારા બનાવવામાં આવ્યું છે.</li>\n<li>દેશમાં અંડરવોટર મેટ્રો કોલકાતામાં હુગલી નદી નીચે છે, જે કોંક્રીટ ટનલ છે કાચની નહીં.</li>\n</ul>\n<blockquote>"ચુકાદો: 🖼️ ડીજીટલ રીતે એડિટ કરેલું AI ચિત્ર."</blockquote>', '<p><strong>दावा:</strong> साबरमती नदी के नीचे कांच की सुरंग में मेट्रो चलने की तस्वीर वायरल हो रही है।</p>\n<h2>सच्चाई</h2>\n<p>मेट्रो रेल कॉर्पोरेशन ने स्पष्ट किया है कि ऐसी कोई कांच की सुरंग नहीं बनाई गई है, यह तस्वीर एआई द्वारा तैयार की गई है।</p>\n<blockquote>"फैसला: 🖼️ एआई निर्मित फर्जी फोटो।"</blockquote>', 'https://images.unsplash.com/photo-1517649763962-0c623266010b?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'b6423e89-dda8-489c-bd82-78e0fe179d65', NULL, 3, 80, 0, 0, 1, 3, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:51:42', '2026-08-19 04:52:05');
