INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('062b1e73-60b7-400d-ba52-a742e7d1cb02', 'jamnagar-brass-parts-export-record-high-growth-2026', 250, 'Jamnagar Brass Parts Export touches record high growth in 2026', 'જામનગર બ્રાસપાર્ટ્સ ઉદ્યોગ: નિકાસમાં 28%નો મોટો ઉછાળો નોંઘાયો', 'जामनगर पीतल पार्ट्स उद्योग: निर्यात में 28% की बड़ी बढ़त दर्ज', 'Jamnagar Brass City manufacturing hubs report historic order surge from European markets.', 'જામનગર બ્રાસ સિટી ઉત્પાદન એકમોને યુરોપિયન અને એશિયન બજારોમાંથી રેકોર્ડબ્રેક ઓર્ડર મળ્યા.', 'जामनगर ब्रास सिटी निर्माण इकाइयों को यूरोपीय और एशियाई बाजारों से रिकॉर्ड ऑर्डर मिले।', 'જામનગરના પ્રખ્યાત બ્રાસપાર્ટ્સ ઉદ્યોગે વૈશ્વિક બજારમાં સ્થાન વધુ મજબૂત કર્યું છે. ગુણવત્તાસભર ઉત્પાદન અને આધુનિક ઈલેક્ટ્રોપ્લેટિંગ ટેક્નોલોજીના ઉપયોગથી નિકાસમાં ગત વર્ષ સરખામણીએ 28 ટકાનો મોટો વધારો થયો છે, જેનાથી હજારો કારીગરોને રોજગારી મળી છે.', 'જામનગરના પ્રખ્યાત બ્રાસપાર્ટ્સ ઉદ્યોગે વૈશ્વિક બજારમાં સ્થાન વધુ મજબૂત કર્યું છે.', 'जामनगर के प्रसिद्ध ब्रास पार्ट्स उद्योग ने वैश्विक बाजार में अपनी स्थिति और मजबूत की है।', 'https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1200&q=90', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '968c7b79-e486-4a36-8720-99f33c015339', 'Jamnagar', 0, 0, 1, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-12 05:31:37', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('070e1fd2-5976-4553-9a73-0add29294608', 'anand-milk-capital-farmers-convention-white-revolution', 257, 'Anand Milk Capital Farmers Convention: White Revolution digital initiatives', 'આણંદ શ્વેત ક્રાંતિ ભૂમિ ખાતે રાજ્યકક્ષાનું પશુપાલક સંમેલન યોજાયું', 'आणंद श्वेत क्रांति भूमि पर राज्य स्तरीय पशुपालक सम्मेलन आयोजित', 'Anand hosts mega dairy tech convention empowering milk producers with smart IoT tools.', 'આણંદ ખાતે આયોજિત મહા સંમેલનમાં પશુપાલકોને સ્માર્ટ ડિજિટલ મિલ્ક ટેસ્ટિંગ કિટ્સ એનાયત કરાઈ.', 'आणंद में आयोजित महा सम्मेलन में पशुपालकों को स्मार्ट डिजिटल मिल्क टेस्टिंग किट वितरित की गईं।', 'શ્વેત ક્રાંતિના મથક આણંદ ખાતે દૂધ ઉત્પાદકો અને ખેડૂતોનું વિરાટ સંમેલન યોજાયું હતું. સંમેલનમાં નવીનતમ પશુપાલન ટેક્નોલોજી, ગુણવત્તા ચકાસણી સાધનો અને ડેરી ક્ષેત્રે સહકારી મોડેલને વધુ મજબૂત કરવાના પગલાં અંગે વિસ્તૃત ચર્ચા થઈ હતી.', 'શ્વેત ક્રાંતિના મથક આણંદ ખાતે દૂધ ઉત્પાદકો અને ખેડૂતોનું વિરાટ સંમેલન યોજાયું હતું.', 'श्वेत क्रांति के केंद्र आणंद में दूध उत्पादकों और किसानों का विशाल सम्मेलन आयोजित किया गया।', 'https://images.unsplash.com/photo-1500595046743-cd271d694d30?auto=format&fit=crop&w=1200&q=90', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '968c7b79-e486-4a36-8720-99f33c015339', 'Anand', 0, 0, 1, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-12 05:32:08', '2026-08-14 11:11:58');
