INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('080e3507-40fe-4a0a-aef8-99252612ec46', 'bhavnagar-athletes-win-big-at-national-championship-event-1786108916049-88', 13, '#13 - Bhavnagar Athletes Win Big at National Championship Event', '#13 - રાષ્ટ્રીય ચેમ્પિયનશિપ ઇવેન્ટમાં Bhavnagar ના ખેલાડીઓની ભવ્ય જીત', '#13 - राष्ट्रीय चैंपियनशिप प्रतियोगिता में Bhavnagar के एथलीटों ने बड़ी जीत हासिल की', 'Latest updates on sports excellence and youth empowerment in Bhavnagar. Read complete report inside.', 'Bhavnagar માં Sports Excellence and Youth Empowerment અંગેના વાયરલ અને તાજા સમાચાર.', 'Bhavnagar में Sports Excellence and Youth Empowerment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Athletes from <strong>Bhavnagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>13,450 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹40,800 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Bhavnagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>13,450 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹40,800 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Bhavnagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>13,450 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹40,800 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', 'https://images.unsplash.com/photo-1465146344425-f00d5f5c8f07?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '2eba9c99-c05d-4f46-97ef-3944abd73d7d', 'Bhavnagar, Gujarat', 6, 63, 0, 0, 0, 0, 'Bhavnagar Athletes Win Big at National Championship Event | Gujarat Post', 'Latest updates on sports excellence and youth empowerment in Bhavnagar. Read complete report inside.', 'Bhavnagar, Gujarat news, Sports, latest updates', NULL, NULL, '2026-07-31 05:21:56', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('08a06b9f-1268-4695-beda-b08fefc9f534', 'major-smart-city-infrastructure-development-unveiled-in-ahmedabad-1786108916334-90', 11, '#11 - Major Smart City Infrastructure Development Unveiled in Ahmedabad', '#11 - Ahmedabad માં મુખ્ય સ્માર્ટ સિટી ઈન્ફ્રાસ્ટ્રક્ચર વિકાસનું અનાવરણ', '#11 - Ahmedabad में प्रमुख स्मार्ट सिटी इंफ्रास्ट्रक्चर विकास का अनावरण', 'Latest updates on smart infrastructure and city development in Ahmedabad. Read complete report inside.', 'Ahmedabad માં Smart Infrastructure and City Development અંગેના વાયરલ અને તાજા સમાચાર.', 'Ahmedabad में Smart Infrastructure and City Development से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>The state government has announced a massive <strong>₹13,750 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Ahmedabad</strong>.</p><p>Officials confirmed that <strong>over 41,700 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Ahmedabad have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹13,750 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Ahmedabad</strong>.</p><p>Officials confirmed that <strong>over 41,700 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Ahmedabad have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹13,750 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Ahmedabad</strong>.</p><p>Officials confirmed that <strong>over 41,700 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Ahmedabad have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', 'https://images.unsplash.com/photo-1470225620780-dba8ba36b745?w=800&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '35257ba4-b50e-4557-a1d4-8d631725b5b1', 'Ahmedabad, Gujarat', 6, 86, 1, 0, 0, 0, 'Major Smart City Infrastructure Development Unveiled in Ahmedabad | Gujarat Post', 'Latest updates on smart infrastructure and city development in Ahmedabad. Read complete report inside.', 'Ahmedabad, Gujarat news, Health, latest updates', NULL, NULL, '2026-07-31 01:21:56', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('094b831e-3a4a-49eb-9393-2c30c610edb3', 'state-of-the-art-multi-specialty-hospital-inaugurated-in-rajkot-1786108917410-93', 8, '#8 - State-of-the-Art Multi-Specialty Hospital Inaugurated in Rajkot', '#8 - Rajkot માં અત્યાધુનિક મલ્ટી-સ્પેશિયાલિટી હોસ્પિટલનું ઉદ્ઘાટન', '#8 - Rajkot में अत्याधुनिक मल्टी-स्पेशलिटी अस्पताल का उद्घाटन', 'Latest updates on healthcare and medical breakthroughs in Rajkot. Read complete report inside.', 'Rajkot માં Healthcare and Medical Breakthroughs અંગેના વાયરલ અને તાજા સમાચાર.', 'Rajkot में Healthcare and Medical Breakthroughs से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A new <strong>14,200-bed advanced hospital facility</strong> was officially opened to the public in <strong>Rajkot</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 43,050 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>14,200-bed advanced hospital facility</strong> was officially opened to the public in <strong>Rajkot</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 43,050 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>14,200-bed advanced hospital facility</strong> was officially opened to the public in <strong>Rajkot</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 43,050 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', 'https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?w=800&q=80', 'PUBLISHED', NULL, '6e329fea-cd2d-4295-a98e-64bddfe20da6', '66cc1ef6-a0d8-4f6b-8d37-2de024e24d6a', 'Rajkot, Gujarat', 5, 67, 1, 0, 0, 0, 'State-of-the-Art Multi-Specialty Hospital Inaugurated in Rajkot | Gujarat Post', 'Latest updates on healthcare and medical breakthroughs in Rajkot. Read complete report inside.', 'Rajkot, Gujarat news, Crime, latest updates', NULL, NULL, '2026-07-30 19:21:57', '2026-08-14 11:11:58');
