INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('10867bd0-50bf-4ff7-903a-ac1de1e1bb5d', 'green-energy-initiative-set-to-power-100-of-gandhinagar-public-grid-1786108909863-49', 52, '#52 - Green Energy Initiative Set to Power 100% of Gandhinagar Public Grid', '#52 - હરિત ઊર્જા પહેલ Gandhinagar પબ્લિક ગ્રીડના 100% ને પાવર આપવા માટે તૈયાર', '#52 - हरित ऊर्जा पहल Gandhinagar पब्लिक ग्रिड को 100% बिजली देने के लिए तैयार', 'Latest updates on renewable energy and environment in Gandhinagar. Read complete report inside.', 'Gandhinagar માં Renewable Energy and Environment અંગેના વાયરલ અને તાજા સમાચાર.', 'Gandhinagar में Renewable Energy and Environment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A breakthrough solar and wind hybrid power project in <strong>Gandhinagar</strong> has reached its target capacity of <strong>7,600 Megawatts</strong> this week.</p><p>With this achievement, <strong>Gandhinagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Gandhinagar</strong> has reached its target capacity of <strong>7,600 Megawatts</strong> this week.</p><p>With this achievement, <strong>Gandhinagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Gandhinagar</strong> has reached its target capacity of <strong>7,600 Megawatts</strong> this week.</p><p>With this achievement, <strong>Gandhinagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', 'https://images.unsplash.com/photo-1592210454359-9043f067919b?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', 'b7016886-3e6a-4452-a198-afcfa9e5663d', 'Gandhinagar, Gujarat', 6, 63, 0, 1, 0, 0, 'Green Energy Initiative Set to Power 100% of Gandhinagar Public Grid | Gujarat Post', 'Latest updates on renewable energy and environment in Gandhinagar. Read complete report inside.', 'Gandhinagar, Gujarat news, Gandhinagar, latest updates', NULL, NULL, '2026-08-03 11:21:49', '2026-08-14 11:11:58');
