INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('1111e580-225c-4ef6-9ec5-e719841ec4a7', 'fact-check-lpg-cylinder-price-reduced-to-300-exaggerated-claim', 240, 'Fact Check: Claim that Government Cut LPG Cylinder Rates to Rs 300 for Everyone is Misleading', 'ફેક્ટ ચેક: સરકારે તમામ ગેસ કનેક્શનધારકો માટે ગેસ સિલિન્ડરનો ભાવ ₹૩૦૦ કર્યો હોવાનો વાયરલ દાવો ભ્રામક', 'फैक्ट चेक: सरकार ने सभी के लिए एलपीजी सिलेंडर के दाम ₹300 कर दिए, यह दावा भ्रामक है', 'Social media posts claiming LPG cylinder prices reduced to Rs 300 across India misinterpret targeted PM Ujjwala Scheme subsidies.', 'એલપીજી ગેસ સિલિન્ડરના ભાવ ₹૩૦૦ થઈ ગયા હોવાના સોશિયલ મીડિયા દાવા માત્ર પીએમ ઉજ્જવલા યોજનાના લક્ષિત સબસીડી લાભો પર આધારિત છે.', 'गैस सिलेंडर के दाम ₹300 होने की खबरें केवल पीएम उज्ज्वला योजना की सब्सिडी से संबंधित हैं, सभी के लिए नहीं।', '<p><strong>Claim:</strong> Viral videos claim the Central Government slashed domestic LPG gas cylinder prices to Rs 300 for all households starting this week.</p>\n<h2>Fact Check Analysis</h2>\n<p>Press Information Bureau (PIB) Fact Check confirmed that commercial and standard domestic LPG cylinder prices remain unchanged. The price benefit refers to effective costs calculated after PM Ujjwala Yojana subsidies for specific eligible beneficiaries.</p>\n<ul>\n<li>General consumer domestic LPG rates continue as per monthly oil marketing company revisions.</li>\n<li>The video misleads viewers by omitting eligibility conditions of Ujjwala beneficiaries.</li>\n</ul>\n<blockquote>"Verdict: ⚠️ MISLEADING & EXAGGERATED. Subsidy applies only to PM Ujjwala beneficiaries."</blockquote>', '<p><strong>દાવો:</strong> સોશિયલ મીડિયા વીડિયોમાં દાવો કરાઈ રહ્યો છે કે કેન્દ્ર સરકારે તમામ ગૃહિણીઓ માટે રાંધણ ગેસ સિલિન્ડરનો ભાવ ઘટાડીને ₹૩૦૦ કરી દીધો છે.</p>\n<h2>તપાસ અને તથ્ય</h2>\n<p>પીઆઈબી ફેક્ટ ચેક ટીમે સ્પષ્ટ કર્યું છે કે સામાન્ય ઘરેલું ગેસ સિલિન્ડરના ભાવમાં આવો કોઈ સીધો ઘટાડો કરાયો નથી. આ વાત માત્ર પીએમ ઉજ્જવલા યોજનાના લાભાર્થીઓને મળતી બેંક ટ્રાન્સફર સબસીડી ગણતરી પર આધારિત છે.</p>\n<ul>\n<li>સામાન્ય ગ્રાહકો માટે ગેસ કંપનીઓના નિયમિત દરો જ લાગુ રહેશે.</li>\n<li>વાયરલ વીડિયોમાં જરૂરી શરતો છુપાવીને ભ્રામક દાવો કરવામાં આવ્યો છે.</li>\n</ul>\n<blockquote>"ચુકાદો: ⚠️ અતિશયોક્તિભર્યો અને ગેરમાર્ગે દોરનારો દાવો."</blockquote>', '<p><strong>दावा:</strong> रसोई गैस सिलेंडर की कीमत सभी के लिए ₹300 कर दी गई है।</p>\n<h2>सच्चाई</h2>\n<p>पीआईबी ने स्पष्ट किया कि यह राहत केवल पीएम उज्ज्वला योजना के लाभार्थियों के लिए ही प्रभावी है।</p>\n<blockquote>"फैसला: ⚠️ भ्रामक दावा।"</blockquote>', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'b6423e89-dda8-489c-bd82-78e0fe179d65', NULL, 3, 84, 1, 0, 1, 2, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:51:45', '2026-08-17 10:13:35');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('114d89f2-5982-4059-a73e-1680afa49df1', 'cyber-cell-busts-fake-investment-app-network-in-ahmedabad-29', 129, '#129 - Cyber cell busts fake investment app network in Ahmedabad - Full Ground Coverage', '#129 - અમદાવાદમાં ફેક ઇન્વેસ્ટમેન્ટ એપ નેટવર્કનો પર્દાફાશ', '#129 - अहमदाबाद में फेक निवेश ऐप नेटवर्क का खुलासा', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1599930113854-d6d7fd521f10?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '66cc1ef6-a0d8-4f6b-8d37-2de024e24d6a', NULL, 6, 92, 1, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:16', '2026-08-14 11:11:58');
