INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('1a1595a3-1114-4352-a3bb-85774b1cab0c', 'new-ai-tech-hub-opens-in-jamnagar-to-foster-startup-ecosystem-1786108915158-80', 21, '#21 - New AI & Tech Hub Opens in Jamnagar to Foster Startup Ecosystem', '#21 - Jamnagar માં સ્ટાર્ટઅપ ઇકોસિસ્ટમને વેગ આપવા નવું AI અને ટેક હબ ખુલ્યું', '#21 - Jamnagar में स्टार्टअप इकोसिस्टम को बढ़ावा देने के लिए नया AI और टेक हब खुला', 'Latest updates on tech & artificial intelligence revolution in Jamnagar. Read complete report inside.', 'Jamnagar માં Tech & Artificial Intelligence Revolution અંગેના વાયરલ અને તાજા સમાચાર.', 'Jamnagar में Tech & Artificial Intelligence Revolution से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>In a major boost for the digital economy, a new <strong>₹12,250 crore AI Innovation Center</strong> was inaugurated in <strong>Jamnagar</strong> today.</p><p>The hub features <strong>supercomputing facilities, cloud credits, and mentorship</strong> from global tech leaders. It is projected to incubate <strong>more than 37,200 tech startups</strong> by the end of 2027.</p><p>Industry experts stated that <strong>Gujarat\'s commitment to artificial intelligence and deep-tech innovation</strong> will position the state as a premier global technology destination.</p>', '<p>In a major boost for the digital economy, a new <strong>₹12,250 crore AI Innovation Center</strong> was inaugurated in <strong>Jamnagar</strong> today.</p><p>The hub features <strong>supercomputing facilities, cloud credits, and mentorship</strong> from global tech leaders. It is projected to incubate <strong>more than 37,200 tech startups</strong> by the end of 2027.</p><p>Industry experts stated that <strong>Gujarat\'s commitment to artificial intelligence and deep-tech innovation</strong> will position the state as a premier global technology destination.</p>', '<p>In a major boost for the digital economy, a new <strong>₹12,250 crore AI Innovation Center</strong> was inaugurated in <strong>Jamnagar</strong> today.</p><p>The hub features <strong>supercomputing facilities, cloud credits, and mentorship</strong> from global tech leaders. It is projected to incubate <strong>more than 37,200 tech startups</strong> by the end of 2027.</p><p>Industry experts stated that <strong>Gujarat\'s commitment to artificial intelligence and deep-tech innovation</strong> will position the state as a premier global technology destination.</p>', 'https://images.unsplash.com/photo-1553729459-efe14ef6055d?w=800&q=80', 'PUBLISHED', NULL, '56a17220-190a-4e17-b56e-7c06101f37f8', 'e4f6985f-03b9-48b6-9ec1-8283410a92c4', 'Jamnagar, Gujarat', 6, 65, 0, 0, 1, 6, 'New AI & Tech Hub Opens in Jamnagar to Foster Startup Ecosystem | Gujarat Post', 'Latest updates on tech & artificial intelligence revolution in Jamnagar. Read complete report inside.', 'Jamnagar, Gujarat news, Instagram, latest updates', NULL, NULL, '2026-07-31 21:21:55', '2026-08-18 06:07:36');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('1b168f07-1b87-48cb-82c8-18b6170d2163', 'fact-check-boiled-lemon-water-cancer-cure-health-myth', 238, 'Fact Check: Viral Claim that Drinking Boiled Lemon Water Cures Cancer is Unproven Myth', 'ફેક્ટ ચેક: ઉકાળેલું લીંબુ પાણી પીવાથી કેન્સર મટી જાય છે તેવો વોટ્સએપ દાવો તબીબી રીતે ખોટો અને જોખમી', 'फैक्ट चेक: उबला नींबू पानी पीने से कैंसर ठीक होता है, यह दावा चिकित्सीय रूप से गलत और खतरनाक है', 'Medical experts and WHO debunk widely circulated social media claims that hot lemon water is 10,000 times stronger than chemotherapy.', 'ગરમ લીંબુ પાણી કીમોથેરાપી કરતાં ૧૦,૦૦૦ ગણું વધુ અસરકારક હોવાના દાવાને તબીબોએ તદ્દન ભ્રામક અને અજ્ઞાનતાપૂર્ણ ગણાવ્યો છે.', 'गर्म नींबू पानी कीमोथेरेपी से 10,000 गुना अधिक प्रभावी होने का दावा डॉक्टरों द्वारा पूरी तरह खारिज कर दिया गया है।', '<p><strong>Claim:</strong> A forwarded WhatsApp text claims boiling lemon slices in hot water destroys all cancer cells and is 10,000 times more powerful than medical chemotherapy.</p>\n<h2>Fact Check Analysis</h2>\n<p>Oncologists and World Health Organization (WHO) medical panels emphasize that while lemons contain Vitamin C and antioxidants supporting immunity, there is zero scientific evidence that lemon water cures cancer.</p>\n<ul>\n<li>Delaying evidence-based medical treatment like chemotherapy or surgery for home remedies can prove fatal.</li>\n<li>Prominent health agencies have repeatedly classified this claim as a dangerous medical myth.</li>\n</ul>\n<blockquote>"Verdict: 🚫 DANGEROUS HEALTH MYTH. Always consult certified oncologists for medical advice."</blockquote>', '<p><strong>દાવો:</strong> વોટ્સએપ પર એક મેસેજ વાયરલ થઈ રહ્યો છે જેમાં દાવો કરાયો છે કે ગરમ પાણીમાં લીંબુ ઉકાળીને પીવાથી કેન્સરના તમામ કોષો નાશ પામે છે અને તે કીમોથેરાપી કરતા ૧૦,૦૦૦ ગણું વધુ શક્તિશાળી છે.</p>\n<h2>તપાસ અને તબીબી તથ્ય</h2>\n<p>કેન્સર નિષ્ણાત તબીબો અને વિશ્વ આરોગ્ય સંસ્થા (WHO) ના રિપોર્ટ અનુસાર, લીંબુમાં વિટામિન સી અને એન્ટીઓક્સીડન્ટ્સ હોય છે જે રોગપ્રતિકારક શક્તિ વધારે છે, પરંતુ તે કેન્સર મટાડવાનો ઇલાજ નથી.</p>\n<ul>\n<li>કીમોથેરાપી કે સર્જરી જેવા વૈજ્ઞાનિક ઉપચારો છોડીને ઘરેલુ નુસખા પર નિર્ભર રહેવું જીવલેણ સાબિત થઈ શકે છે.</li>\n<li>તબીબી જગતે આ દાવાને તદ્દન પાયાવિહોણો અને જોખમી જાહેર કર્યો છે.</li>\n</ul>\n<blockquote>"ચુકાદો: 🚫 જોખમી આરોગ્ય અફવા. ગંભીર બીમારીમાં સર્ટિફાઇડ તબીબની જ સલાહ લો."</blockquote>', '<p><strong>दावा:</strong> उबला हुआ नींबू पानी कैंसर को 10,000 गुना तेजी से ठीक कर सकता है।</p>\n<h2>सच्चाई</h2>\n<p>कैंसर विशेषज्ञों ने इसे खतरनाक अफवाह करार दिया है। नींबू पानी प्रतिरक्षा बढ़ा सकता है लेकिन कैंसर का इलाज नहीं है।</p>\n<blockquote>"फैसला: 🚫 खतरनाक स्वास्थ्य भ्रम।"</blockquote>', 'https://images.unsplash.com/photo-1534531141161-e49d1182749e?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'b6423e89-dda8-489c-bd82-78e0fe179d65', NULL, 3, 89, 0, 0, 1, 1, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:51:43', '2026-08-17 10:01:11');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('1b710981-3ce7-4fc7-bff7-a93b629b1acf', 'market-boom-business-investments-in-gujarat-reach-record-high-1786108903354-5', 96, '#96 - Market Boom: Business Investments in Gujarat Reach Record High', '#96 - માર્કેટ બૂમ: Gujarat માં વ્યાપારી રોકાણ રેકોર્ડ સપાટીએ પહોંચ્યું', '#96 - मार्केट बूम: Gujarat में व्यावसायिक निवेश रिकॉर्ड स्तर पर पहुंचा', 'Latest updates on business, finance and market trends in Gujarat. Read complete report inside.', 'Gujarat માં Business, Finance and Market Trends અંગેના વાયરલ અને તાજા સમાચાર.', 'Gujarat में Business, Finance and Market Trends से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Foreign and domestic investments in <strong>Gujarat</strong> surged to an all-time high of <strong>₹1,000 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 3,450 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Gujarat</strong> surged to an all-time high of <strong>₹1,000 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 3,450 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Gujarat</strong> surged to an all-time high of <strong>₹1,000 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 3,450 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', 'https://images.unsplash.com/photo-1461896836934-ffe607ba8211?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', '33c842e2-4efa-4b25-a12d-ac1a1fe1f561', 'Gujarat, Gujarat', 3, 76, 0, 0, 0, 0, 'Market Boom: Business Investments in Gujarat Reach Record High | Gujarat Post', 'Latest updates on business, finance and market trends in Gujarat. Read complete report inside.', 'Gujarat, Gujarat news, Politics, latest updates', NULL, NULL, '2026-08-07 03:21:43', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('1c1a2532-d18e-43f1-a9b8-72328a4284cb', 'land-fraud-case-senior-official-arrested-in-vadodara-69', 169, '#169 - Land fraud case: Senior official arrested in Vadodara - Full Ground Coverage', '#169 - જમીન ફ્રોડ કેસ: વડોદરામાં વરિષ્ઠ અધિકારી ધરપકડ', '#169 - भूमि धोखाधड़ी मामला: वडोदरा में वरिष्ठ अधिकारी गिरफ्तार', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '66cc1ef6-a0d8-4f6b-8d37-2de024e24d6a', NULL, 6, 52, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:29', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('1cf4a28a-8537-4f96-9393-69b141e61fd0', 'morbi-ceramic-industry-exports-record-15000-crore', 258, 'Morbi Ceramic Industry exports touch record 15000 crore mark globally', 'મોરબી સિરામિક ઉદ્યોગ: ગ્લોબલ માર્કેટમાં ૧૫,૦૦૦ કરોડની નિકાસ સાથે નવો વિક્રમ', 'मोरबी सिरामिक उद्योग: वैश्विक बाजार में 15,000 करोड़ का रिकॉर्ड निर्यात', 'Morbi Ceramic City exports porcelain and vitrified tiles to over 80 countries with green energy initiatives.', 'વિશ્વના બીજા ક્રમના સૌથી મોટા સિરામિક ક્લસ્ટર મોરબીએ વિશ્વના ૮૦થી વધુ દેશોમાં ગુણવત્તાસભર ટાઇલ્સની નિકાસ કરી.', 'विश्व के दूसरे सबसे बड़े सिरामिक क्लस्टर मोरबी ने 80 से अधिक देशों में टाइल्स का निर्यात किया।', '<p>મોરબી સિરામિક સિટીએ વૈશ્વિક ઔદ્યોગિક નકશા પર ભારતની સાખ વધુ મજબૂત કરી છે. ગ્રીન ફ્યુઅલ નેચરલ ગેસ અને સુધારેલી મેન્યુફેક્ચરિંગ ટેકનોલોજીના બળે મોરબીના ટાઇલ્સ અને સેનિટરી વેર ઉત્પાદકોએ 15,000 કરોડ રૂપિયાથી વધુની વાર્ષિક નિકાસ નોંધાવી છે.</p>\n<h2>યુરોપ અને અમેરિકન માર્કેટમાં મોરબીની બોલબાલા</h2>\n<p>મોરબીમાં બનેલી લાર્જ સ્લેબ વિટ્રિફાઇડ ટાઇલ્સ અને ઈકો-ફ્રેન્ડલી સિરામિક પેનલ્સની યુરોપ, મિડલ ઈસ્ટ અને ઉત્તર અમેરિકામાં ભારે માંગ રહી છે.</p>', '<p>મોરબી સિરામિક સિટીએ વૈશ્વિક ઔદ્યોગિક નકશા પર ભારતની સાખ વધુ મજબૂત કરી છે. ગ્રીન ફ્યુઅલ નેચરલ ગેસ અને સુધારેલી મેન્યુફેક્ચરિંગ ટેકનોલોજીના બળે મોરબીના ટાઇલ્સ અને સેનિટરી વેર ઉત્પાદકોએ 15,000 કરોડ રૂપિયાથી વધુની વાર્ષિક નિકાસ નોંધાવી છે.</p>', '<p>मोरबी सिरामिक सिटी ने वैश्विक औद्योगिक मानचित्र पर भारत की साख को और मजबूत किया है।</p>', 'https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=1200&q=90', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '968c7b79-e486-4a36-8720-99f33c015339', 'Morbi', 0, 0, 1, 0, 1, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-12 06:12:32', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('1d5da8c7-3a6d-4b94-9e01-fa0a02d17991', 'warning-heavy-rain-alert-in-gujarat-for-next-three-days-84', 184, '#184 - Warning! Heavy rain alert in Gujarat for next three days - Full Ground Coverage', '#184 - સાવધાન! ગુજરાતમાં આગામી ત્રણ દિવસ ધોધમાર વરસાદની આગાહી', '#184 - सावधान! गुजरात में अगले तीन दिनों तक भारी बारिश की चेतावनी', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1605649487212-47bdab064df7?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '9162cf30-4fba-40d8-a384-3583cdff56cf', NULL, 6, 37, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:35', '2026-08-14 11:11:58');
