INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('1f7e8e85-eba5-42e6-9184-0a822643b756', 'major-smart-city-infrastructure-development-unveiled-in-kutch-1786108909080-42', 59, '#59 - Major Smart City Infrastructure Development Unveiled in Kutch', '#59 - Kutch માં મુખ્ય સ્માર્ટ સિટી ઈન્ફ્રાસ્ટ્રક્ચર વિકાસનું અનાવરણ', '#59 - Kutch में प्रमुख स्मार्ट सिटी इंफ्रास्ट्रक्चर विकास का अनावरण', 'Latest updates on smart infrastructure and city development in Kutch. Read complete report inside.', 'Kutch માં Smart Infrastructure and City Development અંગેના વાયરલ અને તાજા સમાચાર.', 'Kutch में Smart Infrastructure and City Development से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>The state government has announced a massive <strong>₹6,550 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Kutch</strong>.</p><p>Officials confirmed that <strong>over 20,100 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Kutch have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹6,550 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Kutch</strong>.</p><p>Officials confirmed that <strong>over 20,100 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Kutch have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹6,550 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Kutch</strong>.</p><p>Officials confirmed that <strong>over 20,100 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Kutch have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', 'https://images.unsplash.com/photo-1498579150354-977475b7ea0b?w=800&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '702b6b81-2ab8-45e3-b2fe-50d3ec0c2d53', 'Kutch, Gujarat', 3, 89, 1, 1, 0, 1, 'Major Smart City Infrastructure Development Unveiled in Kutch | Gujarat Post', 'Latest updates on smart infrastructure and city development in Kutch. Read complete report inside.', 'Kutch, Gujarat news, Trending, latest updates', NULL, NULL, '2026-08-04 01:21:49', '2026-08-17 10:00:37');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('21a77ea3-78ba-4709-a72a-e1e54ab936f6', 'state-of-the-art-multi-specialty-hospital-inaugurated-in-ahmedabad-1786108903805-9', 92, '#92 - State-of-the-Art Multi-Specialty Hospital Inaugurated in Ahmedabad', '#92 - Ahmedabad માં અત્યાધુનિક મલ્ટી-સ્પેશિયાલિટી હોસ્પિટલનું ઉદ્ઘાટન', '#92 - Ahmedabad में अत्याधुनिक मल्टी-स्पेशलिटी अस्पताल का उद्घाटन', 'Latest updates on healthcare and medical breakthroughs in Ahmedabad. Read complete report inside.', 'Ahmedabad માં Healthcare and Medical Breakthroughs અંગેના વાયરલ અને તાજા સમાચાર.', 'Ahmedabad में Healthcare and Medical Breakthroughs से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A new <strong>1,600-bed advanced hospital facility</strong> was officially opened to the public in <strong>Ahmedabad</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 5,250 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>1,600-bed advanced hospital facility</strong> was officially opened to the public in <strong>Ahmedabad</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 5,250 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>1,600-bed advanced hospital facility</strong> was officially opened to the public in <strong>Ahmedabad</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 5,250 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', 'https://images.unsplash.com/photo-1579952363873-27f3bade9f55?w=800&q=80', 'PUBLISHED', NULL, '6e329fea-cd2d-4295-a98e-64bddfe20da6', '66cc1ef6-a0d8-4f6b-8d37-2de024e24d6a', 'Ahmedabad, Gujarat', 5, 99, 1, 0, 0, 1, 'State-of-the-Art Multi-Specialty Hospital Inaugurated in Ahmedabad | Gujarat Post', 'Latest updates on healthcare and medical breakthroughs in Ahmedabad. Read complete report inside.', 'Ahmedabad, Gujarat news, Crime, latest updates', NULL, NULL, '2026-08-06 19:21:43', '2026-08-17 10:00:29');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('2257c6f7-d1fb-4e9e-bfd1-d3174ef51b84', 'surat-athletes-win-big-at-national-championship-event-1786108903922-10', 91, '#91 - Surat Athletes Win Big at National Championship Event', '#91 - રાષ્ટ્રીય ચેમ્પિયનશિપ ઇવેન્ટમાં Surat ના ખેલાડીઓની ભવ્ય જીત', '#91 - राष्ट्रीय चैंपियनशिप प्रतियोगिता में Surat के एथलीटों ने बड़ी जीत हासिल की', 'Latest updates on sports excellence and youth empowerment in Surat. Read complete report inside.', 'Surat માં Sports Excellence and Youth Empowerment અંગેના વાયરલ અને તાજા સમાચાર.', 'Surat में Sports Excellence and Youth Empowerment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Athletes from <strong>Surat</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>1,750 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹5,700 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Surat</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>1,750 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹5,700 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Surat</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>1,750 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹5,700 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', 'https://images.unsplash.com/photo-1607326957431-29d25d2b386f?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '66d1efc9-15ca-49af-b951-cff8c138d92b', 'Surat, Gujarat', 4, 73, 0, 0, 0, 0, 'Surat Athletes Win Big at National Championship Event | Gujarat Post', 'Latest updates on sports excellence and youth empowerment in Surat. Read complete report inside.', 'Surat, Gujarat news, Weather, latest updates', NULL, NULL, '2026-08-06 17:21:43', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('2374bd88-7254-49bd-af89-8a8445164c44', 'land-fraud-case-senior-official-arrested-in-vadodara-33', 133, '#133 - Land fraud case: Senior official arrested in Vadodara - Full Ground Coverage', '#133 - જમીન ફ્રોડ કેસ: વડોદરામાં વરિષ્ઠ અધિકારી ધરપકડ', '#133 - भूमि धोखाधड़ी मामला: वडोदरा में वरिष्ठ अधिकारी गिरफ्तार', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=800&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '66cc1ef6-a0d8-4f6b-8d37-2de024e24d6a', NULL, 5, 88, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:17', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('23b5a945-f6ba-4d6d-90b7-06fa20b821fb', 'bhavnagar-alang-ship-recycling-green-safety-upgrade', 248, 'Bhavnagar Ship Recycling Yard gets major green safety upgrade', 'ભાવનગર શિપ રિસાયક્લિંગ યાર્ડ અલંગને મળ્યું ગ્રીન સેફ્ટી પ્રમાણપત્ર', 'भावनगर शिप रिसाइकलिंग यार्ड अलंग को मिला ग्रीन सेफ्टी सर्टिफिकेट', 'Alang Ship Recycling Yard achieves 100% compliance with international green shipping standards.', 'અલંગ શિપ બ્રેકિંગ યાર્ડે આંતરરાષ્ટ્રીય પર્યાવરણ અને ગ્રીન શિપિંગ ધોરણોનું 100% પાલન હાંસલ કર્યું.', 'अलंग शिप ब्रेकिंग यार्ड ने अंतरराष्ट्रीय पर्यावरण और ग्रीन शिपिंग मानकों का अनुपालन हासिल किया।', 'ભાવનગર જિલ્લામાં આવેલું આંતરરાષ્ટ્રીય ખ્યાતિપ્રાપ્ત અલંગ શિપ રિસાયક્લિંગ યાર્ડ હવે પર્યાવરણ પરિરૂપ ગ્રીન યાર્ડ તરીકે ઉભરી આવ્યું છે. શિપ રિસાયક્લિંગ ઈન્ડસ્ટ્રીમાં સેફ્ટી કમ્પ્લાયન્સ અને વેસ્ટ મેનેજમેન્ટ માટે ગ્લોબલ સ્ટાન્ડર્ડ સર્ટિફિકેશન મળતાં વૈશ્વિક સ્તરે ભારતની શિપિંગ ક્ષમતા વધુ મજબૂત બની છે.', 'ભાવનગર જિલ્લામાં આવેલું આંતરરાષ્ટ્રીય ખ્યાતિપ્રાપ્ત અલંગ શિપ રિસાયક્લિંગ યાર્ડ હવે પર્યાવરણ પરિરૂપ ગ્રીન યાર્ડ તરીકે ઉભરી આવ્યું છે.', 'भावनगर जिले में स्थित विश्व प्रसिद्ध अलंग शिप रिसाइकलिंग यार्ड अब पर्यावरण अनुकूल ग्रीन यार्ड के रूप में उभरा है।', 'https://images.unsplash.com/photo-1544717305-2782549b5136?auto=format&fit=crop&w=1200&q=90', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '968c7b79-e486-4a36-8720-99f33c015339', 'Bhavnagar', 0, 0, 0, 0, 1, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-12 05:31:37', '2026-08-14 11:11:58');
