INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('2f87d465-ff7f-472e-ad89-13be7e84e021', 'state-of-the-art-multi-specialty-hospital-inaugurated-in-kutch-1786108910571-51', 50, '#50 - State-of-the-Art Multi-Specialty Hospital Inaugurated in Kutch', '#50 - Kutch માં અત્યાધુનિક મલ્ટી-સ્પેશિયાલિટી હોસ્પિટલનું ઉદ્ઘાટન', '#50 - Kutch में अत्याधुनिक मल्टी-स्पेशलिटी अस्पताल का उद्घाटन', 'Latest updates on healthcare and medical breakthroughs in Kutch. Read complete report inside.', 'Kutch માં Healthcare and Medical Breakthroughs અંગેના વાયરલ અને તાજા સમાચાર.', 'Kutch में Healthcare and Medical Breakthroughs से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A new <strong>7,900-bed advanced hospital facility</strong> was officially opened to the public in <strong>Kutch</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 24,150 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>7,900-bed advanced hospital facility</strong> was officially opened to the public in <strong>Kutch</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 24,150 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>7,900-bed advanced hospital facility</strong> was officially opened to the public in <strong>Kutch</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 24,150 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', 'https://images.unsplash.com/photo-1558618047-3c8c76ca7d13?w=800&q=80', 'PUBLISHED', NULL, '6e329fea-cd2d-4295-a98e-64bddfe20da6', 'dd4e83fd-25c8-47fe-ae69-dc6f7123f6be', 'Kutch, Gujarat', 6, 89, 1, 0, 0, 1, 'State-of-the-Art Multi-Specialty Hospital Inaugurated in Kutch | Gujarat Post', 'Latest updates on healthcare and medical breakthroughs in Kutch. Read complete report inside.', 'Kutch, Gujarat news, Gujarat Election 2027, latest updates', NULL, NULL, '2026-08-03 07:21:50', '2026-08-17 10:00:50');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('2ffbbae4-4e6f-4dc2-a534-81bfb05b2f28', 'gujarat-titans-begin-pre-season-camp-in-ahmedabad-71', 171, '#171 - Gujarat Titans begin pre-season camp in Ahmedabad - Full Ground Coverage', '#171 - ગુજરાત ટાઇટન્સે અમદાવાદમાં પ્રી-સીઝન કેમ્પ શરૂ કર્યો', '#171 - गुजरात टाइटन्स ने अहमदाबाद में प्री-સીજન કેમ્પ શરૂ કરાયો', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1599930113854-d6d7fd521f10?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', '2eba9c99-c05d-4f46-97ef-3944abd73d7d', NULL, 3, 50, 1, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:29', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('301ab65c-4ad9-4145-8a5d-d9a00a16856b', 'green-energy-initiative-set-to-power-100-of-surat-public-grid-1786108913832-73', 28, '#28 - Green Energy Initiative Set to Power 100% of Surat Public Grid', '#28 - હરિત ઊર્જા પહેલ Surat પબ્લિક ગ્રીડના 100% ને પાવર આપવા માટે તૈયાર', '#28 - हरित ऊर्जा पहल Surat पब्लिक ग्रिड को 100% बिजली देने के लिए तैयार', 'Latest updates on renewable energy and environment in Surat. Read complete report inside.', 'Surat માં Renewable Energy and Environment અંગેના વાયરલ અને તાજા સમાચાર.', 'Surat में Renewable Energy and Environment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A breakthrough solar and wind hybrid power project in <strong>Surat</strong> has reached its target capacity of <strong>11,200 Megawatts</strong> this week.</p><p>With this achievement, <strong>Surat becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Surat</strong> has reached its target capacity of <strong>11,200 Megawatts</strong> this week.</p><p>With this achievement, <strong>Surat becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Surat</strong> has reached its target capacity of <strong>11,200 Megawatts</strong> this week.</p><p>With this achievement, <strong>Surat becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', 'https://images.unsplash.com/photo-1601997288547-e09e0b16b8f1?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', '9162cf30-4fba-40d8-a384-3583cdff56cf', 'Surat, Gujarat', 6, 88, 0, 0, 0, 0, 'Green Energy Initiative Set to Power 100% of Surat Public Grid | Gujarat Post', 'Latest updates on renewable energy and environment in Surat. Read complete report inside.', 'Surat, Gujarat news, Gujarat, latest updates', NULL, NULL, '2026-08-01 11:21:53', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('30877f5a-ae5d-4843-b24c-1712962bc18c', 'junagadh-girnar-lili-parikrama-completed-devotees', 249, 'Junagadh Girnar Lili Parikrama completed with lakhs of devotees', 'જૂનાગઢ ગિરનાર લીલી પરિક્રમા: ભક્તિ અને આસ્થાના મહાસાગર સાથે સંપન્ન', 'जूनागढ़ गिरनार लीली परिक्रमा: भक्ति और आस्था के सागर के साथ संपन्न', 'Over 8 lakh pilgrims completed the sacred 36 km Girnar Parikrama in Junagadh.', 'જૂનાગઢ ગિરનારની પવિત્ર 36 કિમીની લીલી પરિક્રમામાં 8 લાખથી વધુ શ્રદ્ધાળુઓએ ઉત્સાહભેર ભાગ લીધો.', 'जूनागढ़ गिरनार की पवित्र 36 किमी लीली परिक्रमा में 8 लाख से अधिक श्रद्धालुओं ने भाग लिया।', 'જૂનાગઢ ગિરનાર અભયારણ્યમાં યોજાયેલી વાર્ષિક 36 કિલોમીટરની લીલી પરિક્રમા સંપન્ન થઈ છે. સમગ્ર દેશમાંથી પધારેલા સાધુ-સંતો અને આબાલવૃદ્ધ શ્રદ્ધાળુઓએ ગિરનારી બાપાના જયઘોષ સાથે ભક્તિમય વાતાવરણ સર્જ્યું હતું. તંત્ર દ્વારા અન્નક્ષેત્રો અને મેડિકલ કેમ્પની શ્રેષ્ઠ સુવિધા પૂરી પાડવામાં આવી હતી.', 'જૂનાગઢ ગિરનાર અભયારણ્યમાં યોજાયેલી વાર્ષિક 36 કિલોમીટરની લીલી પરિક્રમા સંપન્ન થઈ છે.', 'जूनागढ़ गिरनार अभयारण्य में आयोजित वार्षिक 36 किलोमीटर की लीली परिक्रमा संपन्न हो गई है।', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=90', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '968c7b79-e486-4a36-8720-99f33c015339', 'Junagadh', 0, 0, 1, 0, 1, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-12 05:31:37', '2026-08-14 11:11:58');
