INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('3d7e6ee5-aa6c-42ba-91dc-36c03de02f42', 'green-energy-initiative-set-to-power-100-of-surat-public-grid-1786108911080-55', 46, '#46 - Green Energy Initiative Set to Power 100% of Surat Public Grid', '#46 - હરિત ઊર્જા પહેલ Surat પબ્લિક ગ્રીડના 100% ને પાવર આપવા માટે તૈયાર', '#46 - हरित ऊर्जा पहल Surat पब्लिक ग्रिड को 100% बिजली देने के लिए तैयार', 'Latest updates on renewable energy and environment in Surat. Read complete report inside.', 'Surat માં Renewable Energy and Environment અંગેના વાયરલ અને તાજા સમાચાર.', 'Surat में Renewable Energy and Environment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A breakthrough solar and wind hybrid power project in <strong>Surat</strong> has reached its target capacity of <strong>8,500 Megawatts</strong> this week.</p><p>With this achievement, <strong>Surat becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Surat</strong> has reached its target capacity of <strong>8,500 Megawatts</strong> this week.</p><p>With this achievement, <strong>Surat becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Surat</strong> has reached its target capacity of <strong>8,500 Megawatts</strong> this week.</p><p>With this achievement, <strong>Surat becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', 'https://images.unsplash.com/photo-1567157577867-05ccb1388e66?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', 'f8cde491-4b92-40b5-a8ec-9171b5fc3252', 'Surat, Gujarat', 3, 92, 0, 0, 0, 0, 'Green Energy Initiative Set to Power 100% of Surat Public Grid | Gujarat Post', 'Latest updates on renewable energy and environment in Surat. Read complete report inside.', 'Surat, Gujarat news, Videos, latest updates', NULL, NULL, '2026-08-02 23:21:51', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('3dc6de5c-e816-403d-8dee-ec7dab6637c5', 'new-health-guidelines-released-how-to-stay-fit-in-summer-110', 210, '#210 - New health guidelines released: how to stay fit in summer - Full Ground Coverage', '#210 - આરોગ્ય માટે નવી માર્ગદર્શિકા: ઉનાળામાં ફિટ રહેવા માટે શું કરવું', '#210 - स्वास्थ्य के लिए नए दिशा-निर्देश: गर्मियों में फिट रहने के लिए क्या करें', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', '35257ba4-b50e-4557-a1d4-8d631725b5b1', NULL, 7, 11, 0, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:44', '2026-08-17 10:00:46');
