INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('3e961c6f-4be2-4a8f-9e69-28b98db67717', 'fact-check-pm-surya-ghar-100-percent-free-solar-rooftop-claim', 242, 'Fact Check: Video Claiming PM Surya Ghar Scheme Gives 100% Free Solar Setup is Misleading', 'ફેક્ટ ચેક: પીએમ સૂર્ય ઘર યોજના હેઠળ ૧૦૦% મફત સોલર રૂફટોપ ફિટિંગના વાયરલ દાવા ભ્રામક', 'फैक्ट चेक: पीएम सूर्य घर योजना के तहत 100% मुफ्त सोलर रूफटॉप लगने का दावा भ्रामक है', 'PM Surya Ghar Muft Bijli Yojana provides Central subsidies up to Rs 78,000, not completely free installations without consumer investment.', 'પીએમ સૂર્ય ઘર યોજનામાં સરકાર ₹૭૮,૦૦૦ સુધીની સબસીડી આપે છે, પરંતુ કોઈ પણ પ્રકારના ખર્ચ વગર ૧૦૦% મફતમાં રૂફટોપ નથી લાગતું.', 'पीएम सूर्य घर योजना में सरकार ₹78,000 तक की सब्सिडी देती है, बिना किसी लागत के 100% मुफ्त इंस्टॉलेशन नहीं होता।', '<p><strong>Claim:</strong> Social media posts claim the Central Government is installing 3kW rooftop solar systems completely free of charge without any application or hardware cost under PM Surya Ghar Yojana.</p>\n<h2>Fact Check Analysis</h2>\n<p>Energy Department guidelines specify that PM Surya Ghar Muft Bijli Yojana offers up to Rs 78,000 direct financial subsidy for 3kW capacity systems. The balance investment is borne by the beneficiary or via low-interest bank loans.</p>\n<ul>\n<li>Up to 300 units of free solar electricity is generated monthly, offsetting grid power bills.</li>\n<li>Viral claims calling it "zero investment 100% free setup" misrepresent the financial subsidy structure.</li>\n</ul>\n<blockquote>"Verdict: ⚠️ MISLEADING. Capital subsidy provided, but total setup is not zero cost."</blockquote>', '<p><strong>દાવો:</strong> સોશિયલ મીડિયા પર વાયરલ મેસેજમાં કહેવાયું છે કે પીએમ સૂર્ય ઘર યોજના હેઠળ સરકાર એક પણ રૂપિયો લીધા વગર ઘરની છત પર ૩ કેડબલ્યુનો સોલર પ્લાન્ટ ૧૦૦% ફ્રીમાં લગાવી આપે છે.</p>\n<h2>તપાસ અને સાચું તથ્ય</h2>\n<p>ઉર્જા વિભાગના સત્તાવાર નિયમો અનુસાર પીએમ સૂર્ય ઘર મુફ્ત બીજલી યોજનામાં ૩ કેડબલ્યુ સિસ્ટમ માટે સરકાર ₹૭૮,૦૦૦ સુધીની સીધી સબસીડી આપે છે. બાકીની રકમ લાભાર્થીએ કે બેંક લોન દ્વારા ભરવાની રહે છે.</p>\n<ul>\n<li>પ્લાન્ટમાંથી દર મહિને ૩૦૦ યુનિટ સુધી મફત વીજળી મળે છે.</li>\n<li>"એક પણ રૂપિયો આપ્યા વગર તદ્દન ફ્રી" વાળો વાયરલ દાવો ભ્રામક છે.</li>\n</ul>\n<blockquote>"ચુકાદો: ⚠️ ભ્રામક દાવો. સરકાર સબસીડી આપે છે, પૂરો પ્લાન્ટ ફ્રી નથી."</blockquote>', '<p><strong>दावा:</strong> पीएम सूर्य घर योजना के तहत बिना किसी पैसे के 100% मुफ्त सोलर पैनल लग रहे हैं।</p>\n<h2>सच्चाई</h2>\n<p>सरकार ₹78,000 तक सब्सिडी देती है, बाकी लागत उपभोक्ता को देनी होती है।</p>\n<blockquote>"फैसला: ⚠️ भ्रामक जानकारी।"</blockquote>', 'https://images.unsplash.com/photo-1509391365360-2e959784a276?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'b6423e89-dda8-489c-bd82-78e0fe179d65', NULL, 3, 83, 0, 0, 1, 2, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:51:46', '2026-08-17 10:00:42');
