INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('4b4b67d2-675a-4705-beb0-f4bac3174b8c', 'state-of-the-art-multi-specialty-hospital-inaugurated-in-ahmedabad-1786108909406-45', 56, '#56 - State-of-the-Art Multi-Specialty Hospital Inaugurated in Ahmedabad', '#56 - Ahmedabad માં અત્યાધુનિક મલ્ટી-સ્પેશિયાલિટી હોસ્પિટલનું ઉદ્ઘાટન', '#56 - Ahmedabad में अत्याधुनिक मल्टी-स्पेशलिटी अस्पताल का उद्घाटन', 'Latest updates on healthcare and medical breakthroughs in Ahmedabad. Read complete report inside.', 'Ahmedabad માં Healthcare and Medical Breakthroughs અંગેના વાયરલ અને તાજા સમાચાર.', 'Ahmedabad में Healthcare and Medical Breakthroughs से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A new <strong>7,000-bed advanced hospital facility</strong> was officially opened to the public in <strong>Ahmedabad</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 21,450 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>7,000-bed advanced hospital facility</strong> was officially opened to the public in <strong>Ahmedabad</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 21,450 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>7,000-bed advanced hospital facility</strong> was officially opened to the public in <strong>Ahmedabad</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 21,450 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', 'https://images.unsplash.com/photo-1504439468489-c8920d796a29?w=800&q=80', 'PUBLISHED', NULL, '6e329fea-cd2d-4295-a98e-64bddfe20da6', '9162cf30-4fba-40d8-a384-3583cdff56cf', 'Ahmedabad, Gujarat', 5, 51, 1, 0, 0, 0, 'State-of-the-Art Multi-Specialty Hospital Inaugurated in Ahmedabad | Gujarat Post', 'Latest updates on healthcare and medical breakthroughs in Ahmedabad. Read complete report inside.', 'Ahmedabad, Gujarat news, Gujarat, latest updates', NULL, NULL, '2026-08-03 19:21:49', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('4bf2ac6a-f6c6-42b0-b008-4fa79ae79723', 'fact-check-senior-citizen-highway-toll-fee-waiver-fake-notice', 239, 'Fact Check: NHAI Clarifies Notice Claiming Toll Plaza Exemption for Senior Citizens is Fake', 'ફેક્ટ ચેક: સીનિયર સીટીઝન્સ માટે નેશનલ હાઇવે ટોલ ટેક્સ માફી અંગેનો વાયરલ પરિપત્ર નકલી', 'फैक्ट चेक: वरिष्ठ नागरिकों के लिए हाईवे टोल टैक्स छूट का वायरल नोटिस पूरी तरह फर्जी है', 'National Highways Authority of India (NHAI) denies viral messages stating Aadhaar-holding senior citizens exempt from paying toll tax.', 'ભારતીય રાષ્ટ્રીય રાજમાર્ગ પ્રાધિકરણે (NHAI) સ્પષ્ટતા કરી છે કે આધાર કાર્ડ ધરાવતા વરિષ્ઠ નાગરિકો માટે ટોલ માફીનો વાયરલ મેસેજ ખોટો છે.', 'भारतीय राष्ट्रीय राजमार्ग प्राधिकरण (NHAI) ने स्पष्ट किया है कि वरिष्ठ नागरिकों के लिए टोल टैक्स छूट का मैसेज फर्जी है।', '<p><strong>Claim:</strong> Posts on Facebook and WhatsApp claim that NHAI has exempted all senior citizens above 60 years from paying highway toll tax upon showing Aadhaar cards.</p>\n<h2>Fact Check Analysis</h2>\n<p>NHAI officials issued a statement confirming no such blanket toll exemption policy exists for senior citizens under National Highways Fee Rules.</p>\n<ul>\n<li>Exemptions apply exclusively to designated emergency vehicles, defense personnel, and specified dignitaries as per government rules.</li>\n<li>FASTag charges apply normally across all vehicle categories.</li>\n</ul>\n<blockquote>"Verdict: ❌ FAKE NOTICE. No toll fee waiver has been issued for senior citizens."</blockquote>', '<p><strong>દાવો:</strong> ફેસબુક અને વોટ્સએપ પર વાયરલ થઈ રહેલા મેસેજમાં દાવો કરાયો છે કે NHAI એ ૬૦ વર્ષથી વધુ ઉંમરના વરિષ્ઠ નાગરિકોને આધાર કાર્ડ બતાવવા પર ટોલ પ્લાઝા પર 100% ટેક્સ માફી આપી છે.</p>\n<h2>તપાસ અને તથ્ય</h2>\n<p>નેશનલ હાઇવે ઓથોરિટી ઓફ ઇન્ડિયા (NHAI) ના સત્તાવાર સૂત્રોએ સ્પષ્ટ કર્યું છે કે વરિષ્ઠ નાગરિકો માટે ટોલ ટેક્સ માફ કરવાની કોઈ યોજના કે નિયમ બહાર પાડવામાં આવ્યો નથી.</p>\n<ul>\n<li>ટોલ નિયમો મુજબ માત્ર ઇમરજન્સી વાહનો અને નિર્ધારિત સરકારી વાહનોને જ છૂટછાટ મળે છે.</li>\n<li>તમામ વાહનો માટે સામાન્ય FASTag નિયમો લાગુ રહે છે.</li>\n</ul>\n<blockquote>"ચુકાદો: ❌ તદ્દન નકલી સૂચના."</blockquote>', '<p><strong>दावा:</strong> 60 साल से अधिक उम्र के बुजुर्गों को हाईवे टोल टैक्स में पूरी छूट दी गई है।</p>\n<h2>सच्चाई</h2>\n<p>NHAI ने इस खबर को खारिज करते हुए कहा है कि वरिष्ठ नागरिकों के लिए टोल छूट का कोई नियम नहीं है।</p>\n<blockquote>"फैसला: ❌ फर्जी खबर।"</blockquote>', 'https://images.unsplash.com/photo-1568605117036-5fe5e7bab0b7?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'b6423e89-dda8-489c-bd82-78e0fe179d65', NULL, 3, 81, 0, 0, 1, 1, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:51:44', '2026-08-17 10:01:11');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('4c5e8537-72d2-4a53-8562-9c32a2dfa03c', 'patan-unesco-rani-ki-vav-patola-museum-renovation', 260, 'Patan UNESCO Heritage Rani Ki Vav and Silk Patola Museum renovation', 'પાટણ યુનેસ્કો વર્લ્ડ હેરિટેજ રાણી કી વાવ અને પવિત્ર પટોળા કળા કેન્દ્રનો ગ્લોબલ કાયાકલ્પ', 'पाटन यूनेस्को वर्ल्ड हेरिटेज रानी की वाव और पटोला कला केंद्र का कायाकल्प', 'Patan heritage city welcomes record tourists showcasing double ikkat Patola weaving mastery.', 'પાટણની ઐતિહાસિક રાણી કી વાવ અને હસ્તકલા પટોળા વણાટકેન્દ્ર ખાતે વિશ્વભરમાંથી પ્રવાસીઓનો ધસારો.', 'पाटन की ऐतिहासिक रानी की वाव और पटोला बुनाई केंद्र में विश्व भर से पर्यटकों का तांता।', '<p>ઉત્તર ગુજરાતના ઐતિહાસિક નગર પાટણની યુનેસ્કો વર્લ્ડ હેરિટેજ સાઇટ \'રાણી કી વાવ\' અને જગપ્રસિદ્ધ \'પાટણના પટોળા\' વણાટ કળા પ્રવાસીઓ માટે મુખ્ય આકર્ષણનું કેન્દ્ર બની છે. પ્રવાસન વિભાગ દ્વારા આધુનિક હેરિટેજ લાઈટિંગ અને ઓડિયો ગાઈડ સુવિધા શરૂ કરવામાં આવી છે.</p>', '<p>ઉત્તર ગુજરાતના ઐતિહાસિક નગર પાટણની યુનેસ્કો વર્લ્ડ હેરિટેજ સાઇટ \'રાણી કી વાવ\' અને જગપ્રસિદ્ધ \'પાટણના પટોળા\' વણાટ કળા આકર્ષણ બન્યા છે.</p>', '<p>उत्तरी गुजरात के ऐतिहासिक शहर पाटन की यूनेस्को विश्व धरोहर रानी की वाव पर्यटकों के लिए मुख्य आकर्षण बनी हुई है।</p>', 'https://images.unsplash.com/photo-1609946782779-8b4e8e1465d4?w=1200&q=90', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '968c7b79-e486-4a36-8720-99f33c015339', 'Patan', 0, 0, 1, 0, 1, 1, NULL, NULL, NULL, NULL, NULL, '2026-08-12 06:12:34', '2026-08-15 07:59:31');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('4d12a64b-b4c3-4311-bb29-4dad513a619f', 'fact-check-electricity-disconnection-sms-phishing-scam-alert', 241, 'Fact Check: SMS Warning Power Cut Tonight Due to Unpaid Bill is Dangerous Banking Fraud', 'ફેક્ટ ચેક: "આજે રાત્રે ૯:૩૦ વાગ્યે વીજળી કાપી નાખવામાં આવશે" તેવો મેસેજ ફ્રોડ સાયબર કૌભાંડ છે', 'फैक्ट चेक: "आज रात बिजली काट दी जाएगी" वाला मैसेज खतरनाक साइबर ठगी का प्रयास है', 'Power discoms DGVCL, UGVCL & Torrent Power issue warning against fake SMS demanding bill payment via personal numbers.', 'વીજ કંપનીઓએ સ્પષ્ટતા કરી છે કે અજાણ્યા વ્યક્તિગત નંબરો પરથી આવતા લાઈટ બિલ બાકી હોવાના મેસેજ સાયબર ઠગાઈ માટે મોકલવામાં આવે છે.', 'बिजली कंपनियों ने चेतावनी दी है कि अज्ञात नंबरों से आने वाले बिजली कटने के मैसेज ठगी के लिए भेजे जाते हैं।', '<p><strong>Claim:</strong> Citizens receive SMS stating: <em>"Dear consumer, your electricity will be disconnected tonight at 9:30 PM because your previous month bill was not updated. Immediately contact Electricity Officer on 98XXXXXXXX."</em></p>\n<h2>Fact Check Analysis</h2>\n<p>Gujarat State Electricity Distribution Companies (UGVCL, DGVCL, PGVCL, MGVCL) and Torrent Power have confirmed they NEVER send SMS from personal 10-digit mobile numbers or demand APK downloads.</p>\n<ul>\n<li>Cyber criminals ask victims to install remote access apps (like AnyDesk/TeamViewer) to wipe out bank balances.</li>\n<li>Official discom messages bear official sender IDs such as <strong>UGVCLP</strong> or <strong>TORRNT</strong>.</li>\n</ul>\n<blockquote>"Verdict: ⚠️ CYBER PHISHING FRAUD. Do NOT call the number or install any app."</blockquote>', '<p><strong>દાવો:</strong> મોબાઈલ પર મેસેજ આવે છે: <em>"પ્રિય ગ્રાહક, તમારું ગયા મહિનાનું લાઈટ બિલ અપડેટ થયું નથી તેથી આજે રાત્રે ૯:૩૦ કલાકે વીજ જોડાણ કાપી નાખવામાં આવશે. તાત્કાલિક અમારા અધિકારીના નંબર 98XXXXXXXX પર સંપર્ક કરો."</em></p>\n<h2>તપાસ અને સાચું તથ્ય</h2>\n<p>ગુજરાતની સરકારી વીજ કંપનીઓ (UGVCL, DGVCL, PGVCL, MGVCL) અને ટોર્ચર પાવરે જાહેરાત કરી છે કે કંપની ક્યારેય વ્યક્તિગત ૧૦ અંકના મોબાઈલ નંબર પરથી કનેક્શન કાપવાનો મેસેજ મોકલતી નથી.</p>\n<ul>\n<li>આ સાયબર ઠગો છે જે ફોનમાં રિમોટ એકસેસ એપ ડાઉનલોડ કરાવી બેંક ખાતામાંથી પૈસા ઉપાડી લે છે.</li>\n<li>સત્તાવાર મેસેજ માત્ર હેડર આઈડી જેમ કે <strong>UGVCLP</strong> કે <strong>DGVCLP</strong> પરથી જ આવે છે.</li>\n</ul>\n<blockquote>"ચુકાદો: ⚠️ સાયબર ફ્રોડ અને ઠગાઈની જાળ. આ નંબર પર ક્યારેય કોલ ન કરવો."</blockquote>', '<p><strong>दावा:</strong> बिजली बिल न भरने पर आज रात बिजली कटने का मैसेज आ रहा है।</p>\n<h2>सच्चाई</h2>\n<p>बिजली कंपनियों ने इसे साइबर ठगी करार दिया है और ऐसे नंबरों पर फोन न करने की सख्त सलाह दी है।</p>\n<blockquote>"फैसला: ⚠️ साइबर फ्रॉड।"</blockquote>', 'https://images.unsplash.com/photo-1473341304170-971dccb5ac1e?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'b6423e89-dda8-489c-bd82-78e0fe179d65', NULL, 3, 93, 1, 1, 1, 1, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:51:46', '2026-08-17 10:13:35');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('4d4ccd39-d9c5-4806-8b00-129465c1d660', 'new-traffic-rules-implemented-in-ahmedabad-from-today-details-of-penalty-and-locations-45', 145, '#145 - New traffic rules implemented in Ahmedabad from today, details of penalty and locations - Full Ground Coverage', '#145 - અમદાવાદમાં આજથી નવા ટ્રાફિક નિયમ લાગુ! ક્યાં લાગશે દંડ, જાણો પૂરી વિગત', '#145 - अहमदाबाद में आज से नए ट्रैफिक नियम लागू! कहां लगेगा जुर्माना, जानें पूरी जानकारी', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1541872703-74c5e44368f9?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', '9162cf30-4fba-40d8-a384-3583cdff56cf', NULL, 7, 76, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:20', '2026-08-14 11:11:58');
