INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('4df53c8a-3000-484a-8d82-a1b20ffd8bea', 'green-energy-initiative-set-to-power-100-of-bhavnagar-public-grid-1786108911817-61', 40, '#40 - Green Energy Initiative Set to Power 100% of Bhavnagar Public Grid', '#40 - હરિત ઊર્જા પહેલ Bhavnagar પબ્લિક ગ્રીડના 100% ને પાવર આપવા માટે તૈયાર', '#40 - हरित ऊर्जा पहल Bhavnagar पब्लिक ग्रिड को 100% बिजली देने के लिए तैयार', 'Latest updates on renewable energy and environment in Bhavnagar. Read complete report inside.', 'Bhavnagar માં Renewable Energy and Environment અંગેના વાયરલ અને તાજા સમાચાર.', 'Bhavnagar में Renewable Energy and Environment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>9,400 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>9,400 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>9,400 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', 'https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', '33c842e2-4efa-4b25-a12d-ac1a1fe1f561', 'Bhavnagar, Gujarat', 4, 81, 0, 0, 0, 0, 'Green Energy Initiative Set to Power 100% of Bhavnagar Public Grid | Gujarat Post', 'Latest updates on renewable energy and environment in Bhavnagar. Read complete report inside.', 'Bhavnagar, Gujarat news, Politics, latest updates', NULL, NULL, '2026-08-02 11:21:51', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('4eab0530-51d7-47c2-9913-64f8ed939ce3', 'bhavnagar-athletes-win-big-at-national-championship-event-1786108907637-34', 67, '#67 - Bhavnagar Athletes Win Big at National Championship Event', '#67 - રાષ્ટ્રીય ચેમ્પિયનશિપ ઇવેન્ટમાં Bhavnagar ના ખેલાડીઓની ભવ્ય જીત', '#67 - राष्ट्रीय चैंपियनशिप प्रतियोगिता में Bhavnagar के एथलीटों ने बड़ी जीत हासिल की', 'Latest updates on sports excellence and youth empowerment in Bhavnagar. Read complete report inside.', 'Bhavnagar માં Sports Excellence and Youth Empowerment અંગેના વાયરલ અને તાજા સમાચાર.', 'Bhavnagar में Sports Excellence and Youth Empowerment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Athletes from <strong>Bhavnagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>5,350 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹16,500 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Bhavnagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>5,350 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹16,500 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Bhavnagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>5,350 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹16,500 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', 'https://images.unsplash.com/photo-1427504494785-3a9ca7044f45?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '35257ba4-b50e-4557-a1d4-8d631725b5b1', 'Bhavnagar, Gujarat', 3, 55, 0, 0, 0, 0, 'Bhavnagar Athletes Win Big at National Championship Event | Gujarat Post', 'Latest updates on sports excellence and youth empowerment in Bhavnagar. Read complete report inside.', 'Bhavnagar, Gujarat news, Health, latest updates', NULL, NULL, '2026-08-04 17:21:47', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('4f0dd9ea-0128-424b-acdf-ecf00512eed4', 'dhorn-11-12na-vid-yar-thio-mate-gujarat-srkarno-moto-nir-ny-hve-vocational-subjects-pn-psnd-kri-shkashe', 225, 'ધોરણ 11-12ના વિદ્યાર્થીઓ માટે ગુજરાત સરકારનો મોટો નિર્ણય: હવે Vocational Subjects પણ પસંદ કરી શકાશે', 'ધોરણ 11-12ના વિદ્યાર્થીઓ માટે ગુજરાત સરકારનો મોટો નિર્ણય: હવે Vocational Subjects પણ પસંદ કરી શકાશે', 'ધોરણ 11-12ના વિદ્યાર્થીઓ માટે ગુજરાત સરકારનો મોટો નિર્ણય: હવે Vocational Subjects પણ પસંદ કરી શકાશે', '<div style="text-align: center;"><b><font color="#bb3e3e" style="background-color: rgb(0, 255, 136);">ગુજરાત શિક્ષણ વિભાગે</font> </b><u>ધોરણ 11 અને 12 General Streamના અભ્યાસક્રમમાં</u> Vocational અને Skill-Based Subjectsને સ્થાન આપવાનો નિર્ણય કર્યો છે. નવા વૈકલ્પિક વિષયો વિદ્યાર્થીઓને તેમની રુચિ અને ભવિષ્યની કારકિર્દી અનુસાર પસંદગી<strike> કરવાની તક આપશે.</strike></div>', '<div style="text-align: center;"><b><font color="#bb3e3e" style="background-color: rgb(0, 255, 136);">ગુજરાત શિક્ષણ વિભાગે</font> </b><u>ધોરણ 11 અને 12 General Streamના અભ્યાસક્રમમાં</u> Vocational અને Skill-Based Subjectsને સ્થાન આપવાનો નિર્ણય કર્યો છે. નવા વૈકલ્પિક વિષયો વિદ્યાર્થીઓને તેમની રુચિ અને ભવિષ્યની કારકિર્દી અનુસાર પસંદગી<strike> કરવાની તક આપશે.</strike></div>', '<div style="text-align: center;"><b><font color="#bb3e3e" style="background-color: rgb(0, 255, 136);">ગુજરાત શિક્ષણ વિભાગે</font> </b><u>ધોરણ 11 અને 12 General Streamના અભ્યાસક્રમમાં</u> Vocational અને Skill-Based Subjectsને સ્થાન આપવાનો નિર્ણય કર્યો છે. નવા વૈકલ્પિક વિષયો વિદ્યાર્થીઓને તેમની રુચિ અને ભવિષ્યની કારકિર્દી અનુસાર પસંદગી<strike> કરવાની તક આપશે.</strike></div>', '## 📌 AT A GLANCE (KEY HIGHLIGHTS)\n--------------------------------------------------\nધોરણ 11માં નવા વૈકલ્પિક વિષયો 2026-27થી શરૂ થશે.\nધોરણ 12માં આ વ્યવસ્થા 2027-28થી લાગુ થશે.\nYoga, Health & Physical Education, Fine Arts, Music અને Computer Studies જેવા વિષયોનો સમાવેશ કરવામાં આવ્યો છે.\nવિદ્યાર્થીઓને તેમની રુચિ અને ભવિષ્યની કારકિર્દી પ્રમાણે વિષય પસંદ કરવાની તક મળશે.\nAcademic Learning સાથે Practical અને Skill-Based Learning પર પણ ભાર મૂકવામાં આવશે.\n--------------------------------------------------\n\n<div>ગાંધીનગર: ગુજરાતના વિદ્યાર્થીઓ માટે શિક્ષણ ક્ષેત્રે મહત્વપૂર્ણ ફેરફાર કરવામાં આવ્યો છે. ગુજરાત શિક્ષણ વિભાગે ધોરણ 11 અને 12 General Streamના અભ્યાસક્રમમાં Vocational અને Skill-Based Subjectsનો સમાવેશ કરવાની મંજૂરી આપી છે.</div><div><br></div><div>આ નિર્ણયનો અમલ તબક્કાવાર કરવામાં આવશે. શૈક્ષણિક વર્ષ 2026-27થી ધોરણ 11ના વિદ્યાર્થીઓને નવા વૈકલ્પિક વિષયો પસંદ કરવાની તક મળશે, જ્યારે ધોરણ 12માં આ વ્યવસ્થા 2027-28થી લાગુ થશે.</div><div><br></div><div>નવા અભ્યાસક્રમનો હેતુ વિદ્યાર્થીઓને માત્ર પરંપરાગત શૈક્ષણિક વિષયો સુધી મર્યાદિત રાખવાને બદલે તેમની રુચિ, પ્રતિભા અને ભવિષ્યની કારકિર્દી સાથે જોડાયેલા વિષયો પસંદ કરવાની વધુ તક આપવાનો છે.</div>\n\n![Gallery Image 2](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786354762/gujarat-post/qga3v2jvhvvistn08oar.jpg)\n\n> "વિદ્યાર્થીઓને પરંપરાગત શિક્ષણ સાથે તેમની રુચિ અને ભવિષ્યની કારકિર્દી અનુસાર Skill-Based Subjects પસંદ કરવાની તક મળવી એ શિક્ષણને વધુ વ્યવહારુ બનાવવાની દિશામાં મહત્વનું પગલું છે."\n> — Gujarat Education Sector\n\n<div class="my-4 rounded-2xl border border-sky-200 bg-sky-50/60 p-4 dark:border-sky-950/40 dark:bg-sky-950/20 font-sans"><a href="https://x.com/Bhupendrapbjp" target="_blank" rel="noopener noreferrer" class="flex items-center gap-2 text-sm font-extrabold text-sky-600 dark:text-sky-400 hover:underline">🐦 View Tweet / Post on X (Twitter)</a></div>\n\n<div class="my-4 rounded-2xl border border-red-200 bg-red-50/60 p-4 dark:border-red-950/40 dark:bg-red-950/20 flex items-center justify-between font-sans"><div class="flex items-center gap-2 text-sm font-bold text-red-700 dark:text-red-400">📄 <span>Attached PDF Document</span></div><a href="https://res.cloudinary.com/dvcffkyjz/raw/upload/v1786354808/gujarat-post/wbhmo7zajmnpnm2d9ezw.pdf" target="_blank" download class="rounded-xl bg-red-600 px-4 py-2 text-xs font-black text-white hover:bg-red-700 transition-all shadow-xs">Download PDF</a></div>', '## 📌 એક નજરમાં (KEY HIGHLIGHTS)\n--------------------------------------------------\nધોરણ 11માં નવા વૈકલ્પિક વિષયો 2026-27થી શરૂ થશે.\nધોરણ 12માં આ વ્યવસ્થા 2027-28થી લાગુ થશે.\nYoga, Health & Physical Education, Fine Arts, Music અને Computer Studies જેવા વિષયોનો સમાવેશ કરવામાં આવ્યો છે.\nવિદ્યાર્થીઓને તેમની રુચિ અને ભવિષ્યની કારકિર્દી પ્રમાણે વિષય પસંદ કરવાની તક મળશે.\nAcademic Learning સાથે Practical અને Skill-Based Learning પર પણ ભાર મૂકવામાં આવશે.\n--------------------------------------------------\n\n<div>ગાંધીનગર: ગુજરાતના વિદ્યાર્થીઓ માટે શિક્ષણ ક્ષેત્રે મહત્વપૂર્ણ ફેરફાર કરવામાં આવ્યો છે. ગુજરાત શિક્ષણ વિભાગે ધોરણ 11 અને 12 General Streamના અભ્યાસક્રમમાં Vocational અને Skill-Based Subjectsનો સમાવેશ કરવાની મંજૂરી આપી છે.</div><div><br></div><div>આ નિર્ણયનો અમલ તબક્કાવાર કરવામાં આવશે. શૈક્ષણિક વર્ષ 2026-27થી ધોરણ 11ના વિદ્યાર્થીઓને નવા વૈકલ્પિક વિષયો પસંદ કરવાની તક મળશે, જ્યારે ધોરણ 12માં આ વ્યવસ્થા 2027-28થી લાગુ થશે.</div><div><br></div><div>નવા અભ્યાસક્રમનો હેતુ વિદ્યાર્થીઓને માત્ર પરંપરાગત શૈક્ષણિક વિષયો સુધી મર્યાદિત રાખવાને બદલે તેમની રુચિ, પ્રતિભા અને ભવિષ્યની કારકિર્દી સાથે જોડાયેલા વિષયો પસંદ કરવાની વધુ તક આપવાનો છે.</div>\n\n![Gallery Image 2](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786354762/gujarat-post/qga3v2jvhvvistn08oar.jpg)\n\n> "વિદ્યાર્થીઓને પરંપરાગત શિક્ષણ સાથે તેમની રુચિ અને ભવિષ્યની કારકિર્દી અનુસાર Skill-Based Subjects પસંદ કરવાની તક મળવી એ શિક્ષણને વધુ વ્યવહારુ બનાવવાની દિશામાં મહત્વનું પગલું છે."\n> — Gujarat Education Sector\n\n<div>નવા વિષય માળખામાં Yoga, Health and Physical Education, Fine Arts, Music, Computer Studies તથા અન્ય Vocational Subjectsને સ્થાન આપવામાં આવ્યું છે. આ વિષયો Group-4માં વૈકલ્પિક વિકલ્પ તરીકે આપવામાં આવશે.</div><div><br></div><div>વિદ્યાર્થીઓ પોતાની રુચિ અને ભવિષ્યની કારકિર્દીને ધ્યાનમાં રાખીને આમાંથી યોગ્ય વિષય પસંદ કરી શકશે. ઉદાહરણ તરીકે, ટેક્નોલોજીમાં રસ ધરાવતા વિદ્યાર્થીઓ Computer Studies તરફ જઈ શકે છે, જ્યારે કલા અને સર્જનાત્મક ક્ષેત્રમાં રસ ધરાવતા વિદ્યાર્થીઓ Fine Arts અથવા Music પસંદ કરી શકે છે.</div><div><br></div><div>આ પ્રકારની પસંદગીથી વિદ્યાર્થીઓને શાળાના સ્તરથી જ પોતાની રુચિના ક્ષેત્રમાં વધુ પ્રેક્ટિકલ જ્ઞાન મેળવવાની તક મળી શકે છે.</div>\n\n<div>ગુજરાતમાં શિક્ષણને વધુ Skill-Based અને Career-Oriented બનાવવાના પ્રયાસો અગાઉથી પણ જોવા મળ્યા છે. Knowledge Consortium of Gujaratની Finishing School Projectમાં વિદ્યાર્થીઓ માટે Life Skills, Employability Skills અને Functional English જેવી તાલીમ આપવામાં આવે છે.</div><div><br></div><div>સરકારી માહિતી અનુસાર Finishing School Project વર્ષ 2016-17થી ચાલી રહ્યું છે અને તેનો હેતુ વિદ્યાર્થીઓની employability તથા skill enhancement વધારવાનો છે. આ પ્રોજેક્ટ હેઠળ 80 કલાકની skill-enhancement training આપવામાં આવે છે. :contentReference[oaicite:5]{index=5}</div><div><br></div><div>આ ઉપરાંત ગુજરાત સરકારની શિક્ષણ પહેલોમાં UDISHA, Placement Cell, Student Startup and Innovation Policy અને Council of Industry Academia Collaboration જેવી પહેલોનો પણ સમાવેશ થાય છે. :contentReference[oaicite:6]{index=6}</div>\n\n<figure class="my-4 text-center"><img src="https://images.openai.com/static-rsc-4/r2eM834z4X0NwWEj4bxtXVZ0lBRulohSB4C-Y0JRlvmEIGShyUp4nYaMNwrx6au-eKeC7MesqAHNUP1qDjApyksfxRF6TlAdW9vZro6CMUxzavBUR64lbTpT3iBLxVZBFzJlNjs0kE2ervN7d8mpk0a2x1GcRH41P1pETzUuXdk?purpose=inline" alt="Article Image" class="max-w-full h-auto rounded-xl mx-auto border border-zinc-200 dark:border-zinc-800 shadow-sm"></figure><p></p><div>શિક્ષણ ક્ષેત્રમાં Vocational Subjectsનો સમાવેશ વિદ્યાર્થીઓને પરંપરાગત અભ્યાસ સાથે પોતાની વધારાની કુશળતા વિકસાવવાની તક આપી શકે છે. આજના સમયમાં Digital Skills, Communication, Creativity, Physical Fitness અને Practical Knowledge જેવી કુશળતાઓ પણ કારકિર્દી માટે મહત્વપૂર્ણ બની રહી છે.</div><div><br></div><div>ધોરણ 11 અને 12માં આવી પસંદગી મળવાથી વિદ્યાર્થીઓને ઉચ્ચ શિક્ષણમાં પ્રવેશ લેતા પહેલાં પોતાની રુચિના ક્ષેત્રને ઓળખવામાં મદદ મળી શકે છે.</div><div><br></div><div>જોકે, નવા વિષયોનો વાસ્તવિક લાભ શાળાઓમાં તેની અમલવારી, શિક્ષકોની ઉપલબ્ધતા, Infrastructure અને Practical Trainingની ગુણવત્તા પર આધારિત રહેશે.</div>\n\n<div class="my-4 rounded-2xl border border-sky-200 bg-sky-50/60 p-4 dark:border-sky-950/40 dark:bg-sky-950/20 font-sans"><a href="https://x.com/Bhupendrapbjp" target="_blank" rel="noopener noreferrer" class="flex items-center gap-2 text-sm font-extrabold text-sky-600 dark:text-sky-400 hover:underline">🐦 View Tweet / Post on X (Twitter)</a></div>\n\n<div class="my-4 rounded-2xl border border-red-200 bg-red-50/60 p-4 dark:border-red-950/40 dark:bg-red-950/20 flex items-center justify-between font-sans"><div class="flex items-center gap-2 text-sm font-bold text-red-700 dark:text-red-400">📄 <span>Attached PDF Document</span></div><a href="https://res.cloudinary.com/dvcffkyjz/raw/upload/v1786354808/gujarat-post/wbhmo7zajmnpnm2d9ezw.pdf" target="_blank" download class="rounded-xl bg-red-600 px-4 py-2 text-xs font-black text-white hover:bg-red-700 transition-all shadow-xs">Download PDF</a></div>', '## 📌 एक नजर में (KEY HIGHLIGHTS)\n--------------------------------------------------\nધોરણ 11માં નવા વૈકલ્પિક વિષયો 2026-27થી શરૂ થશે.\nધોરણ 12માં આ વ્યવસ્થા 2027-28થી લાગુ થશે.\nYoga, Health & Physical Education, Fine Arts, Music અને Computer Studies જેવા વિષયોનો સમાવેશ કરવામાં આવ્યો છે.\nવિદ્યાર્થીઓને તેમની રુચિ અને ભવિષ્યની કારકિર્દી પ્રમાણે વિષય પસંદ કરવાની તક મળશે.\nAcademic Learning સાથે Practical અને Skill-Based Learning પર પણ ભાર મૂકવામાં આવશે.\n--------------------------------------------------\n\n<div>ગાંધીનગર: ગુજરાતના વિદ્યાર્થીઓ માટે શિક્ષણ ક્ષેત્રે મહત્વપૂર્ણ ફેરફાર કરવામાં આવ્યો છે. ગુજરાત શિક્ષણ વિભાગે ધોરણ 11 અને 12 General Streamના અભ્યાસક્રમમાં Vocational અને Skill-Based Subjectsનો સમાવેશ કરવાની મંજૂરી આપી છે.</div><div><br></div><div>આ નિર્ણયનો અમલ તબક્કાવાર કરવામાં આવશે. શૈક્ષણિક વર્ષ 2026-27થી ધોરણ 11ના વિદ્યાર્થીઓને નવા વૈકલ્પિક વિષયો પસંદ કરવાની તક મળશે, જ્યારે ધોરણ 12માં આ વ્યવસ્થા 2027-28થી લાગુ થશે.</div><div><br></div><div>નવા અભ્યાસક્રમનો હેતુ વિદ્યાર્થીઓને માત્ર પરંપરાગત શૈક્ષણિક વિષયો સુધી મર્યાદિત રાખવાને બદલે તેમની રુચિ, પ્રતિભા અને ભવિષ્યની કારકિર્દી સાથે જોડાયેલા વિષયો પસંદ કરવાની વધુ તક આપવાનો છે.</div>\n\n![Gallery Image 2](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786354762/gujarat-post/qga3v2jvhvvistn08oar.jpg)\n\n> "વિદ્યાર્થીઓને પરંપરાગત શિક્ષણ સાથે તેમની રુચિ અને ભવિષ્યની કારકિર્દી અનુસાર Skill-Based Subjects પસંદ કરવાની તક મળવી એ શિક્ષણને વધુ વ્યવહારુ બનાવવાની દિશામાં મહત્વનું પગલું છે."\n> — Gujarat Education Sector\n\n<div class="my-4 rounded-2xl border border-sky-200 bg-sky-50/60 p-4 dark:border-sky-950/40 dark:bg-sky-950/20 font-sans"><a href="https://x.com/Bhupendrapbjp" target="_blank" rel="noopener noreferrer" class="flex items-center gap-2 text-sm font-extrabold text-sky-600 dark:text-sky-400 hover:underline">🐦 View Tweet / Post on X (Twitter)</a></div>\n\n<div class="my-4 rounded-2xl border border-red-200 bg-red-50/60 p-4 dark:border-red-950/40 dark:bg-red-950/20 flex items-center justify-between font-sans"><div class="flex items-center gap-2 text-sm font-bold text-red-700 dark:text-red-400">📄 <span>Attached PDF Document</span></div><a href="https://res.cloudinary.com/dvcffkyjz/raw/upload/v1786354808/gujarat-post/wbhmo7zajmnpnm2d9ezw.pdf" target="_blank" download class="rounded-xl bg-red-600 px-4 py-2 text-xs font-black text-white hover:bg-red-700 transition-all shadow-xs">Download PDF</a></div>', 'https://res.cloudinary.com/dvcffkyjz/image/upload/v1786354758/gujarat-post/xfldhq41vncfuktjrp71.jpg', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', 'ced0c9a6-760d-4c4a-86ea-ba95385dcd43', 'Gandhinagar', 3, 0, 0, 0, 1, 1, 'Gujarat Education News: Class 11-12 Students Can Choose Vocational Subjects From 2026-27', 'Gujarat approves vocational and skill-based subjects for Class 11 and 12 General Stream, including Computer Studies, Fine Arts, Music, Yoga and Health Education.', 'Gujarat Education News, Gujarat School News, Class 11 Gujarat, Class 12 Gujarat, Vocational Subjects Gujarat, Gujarat Education 2026, Computer Studies Gujarat, Fine Arts Gujarat, Music Subject Gujarat, Yoga Education Gujarat, Skill Based Education', '', 'index, follow', '2026-08-10 09:41:38', '2026-08-18 06:07:36');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('5015a844-cf04-4e11-bc55-35302b7346a1', 'new-cabinet-reshuffle-expected-in-gujarat-government-23', 123, '#123 - New cabinet reshuffle expected in Gujarat government - Full Ground Coverage', '#123 - ગુજરાત સરકારમાં નવો કેબિનેટ ફેરફાર અપેક્ષિત', '#123 - गुजरात सरकार में नया कैबिनेट फेरबदल अपेक्षित', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1540910419892-4a36d2c3266c?w=800&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '33c842e2-4efa-4b25-a12d-ac1a1fe1f561', NULL, 5, 98, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:14', '2026-08-14 11:11:58');
