INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('5207e7ef-6f28-414e-a0cd-ee0330eeb028', 'gujarat-vrsadno-kher-be-divsman-35-lokonan-mot-ahmedabad-294-6-mimi-vrsadthi-jlbnbakar', 274, 'ગુજરાતમાં વરસાદનો કહેર: બે દિવસમાં 35 લોકોનાં મોત, અમદાવાદમાં 294.6 મિમી વરસાદથી જળબંબાકાર', 'ગુજરાતમાં વરસાદનો કહેર: બે દિવસમાં 35 લોકોનાં મોત, અમદાવાદમાં 294.6 મિમી વરસાદથી જળબંબાકાર', 'ગુજરાતમાં વરસાદનો કહેર: બે દિવસમાં 35 લોકોનાં મોત, અમદાવાદમાં 294.6 મિમી વરસાદથી જળબંબાકાર', '<p style="text-align: center;"><font size="5"><b>ગુજરાતમાં </b>ભારે વરસાદ અને પૂરની સ્થિતિ વચ્ચે બે દિવસમાં 35 લોકોનાં મોત થયા છે. અમદાવાદમાં 24 કલાકમાં 294.6 મિમી વરસાદ નોંધાતા અનેક વિસ્તારોમાં પાણી ભરાઈ ગયું અને <strike>જનજીવન </strike><u>ખોરવાયું.</u></font></p>', '<p style="text-align: center;"><font size="5"><b>ગુજરાતમાં </b>ભારે વરસાદ અને પૂરની સ્થિતિ વચ્ચે બે દિવસમાં 35 લોકોનાં મોત થયા છે. અમદાવાદમાં 24 કલાકમાં 294.6 મિમી વરસાદ નોંધાતા અનેક વિસ્તારોમાં પાણી ભરાઈ ગયું અને <strike>જનજીવન </strike><u>ખોરવાયું.</u></font></p>', '<p style="text-align: center;"><font size="5"><b>ગુજરાતમાં </b>ભારે વરસાદ અને પૂરની સ્થિતિ વચ્ચે બે દિવસમાં 35 લોકોનાં મોત થયા છે. અમદાવાદમાં 24 કલાકમાં 294.6 મિમી વરસાદ નોંધાતા અનેક વિસ્તારોમાં પાણી ભરાઈ ગયું અને <strike>જનજીવન </strike><u>ખોરવાયું.</u></font></p>', '## 📌 AT A GLANCE (KEY HIGHLIGHTS)\n--------------------------------------------------\nગુજરાતમાં ભારે વરસાદ અને પૂરથી બે દિવસમાં 35 લોકોનાં મોત નોંધાયા.\nઅમદાવાદમાં 24 કલાકમાં 294.6 મિમી વરસાદ નોંધાયો.\nઅમદાવાદનો આ વરસાદ શહેરના ઇતિહાસમાં ચોથો સૌથી વધુ 24 કલાકનો વરસાદ રહ્યો.\n23 જુલાઈએ અમદાવાદમાં માત્ર બે કલાકમાં 177 મિમી વરસાદ નોંધાયો હતો.\nભારે વરસાદને કારણે અનેક રસ્તાઓ અને અંડરપાસમાં પાણી ભરાયા.\nદક્ષિણ ગુજરાતમાં પૂરગ્રસ્ત વિસ્તારોમાંથી હજારો લોકોને સલામત સ્થળે ખસેડવામાં આવ્યા.\nNDRF, SDRF, સ્થાનિક તંત્ર અને સશસ્ત્ર દળોએ રાહત અને બચાવ કામગીરી હાથ ધરી.\n--------------------------------------------------\n\n<p class="isSelectedEnd"><b>ગુજરાતમાં ચોમાસાએ ફરી એકવાર ભારે તબાહી મચાવી છે. રાજ્યના અનેક વિસ્તારોમાં ભારે વરસાદને કારણે પૂર જેવી સ્થિતિ સર્જાઈ છે. સતત વરસાદથી નદી-નાળાઓમાં પાણીનું સ્તર વધ્યું છે અને અનેક વિસ્તારોમાં પાણી ભરાઈ જતાં સામાન્ય જનજીવનને ભારે અસર પહોંચી છે.</b></p><p><u>25 જુલાઈ 2026ના અહેવાલો અનુસાર, ગુજરાતમાં ભારે વરસાદ અને પૂરની પરિસ્થિતિને કારણે બે દિવસમાં મૃત્યુઆંક 35 સુધી પહોંચ્યો હતો. ભારે અસરગ્રસ્ત વિસ્તારોમાં બચાવ અને રાહત કામગીરી પણ તેજ કરવામાં આવી હતી</u></p>\n\n![Gallery Image 2](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786604828/gujarat-post/a9xq1h2rr5bktoomfxz6.jpg)\n\n![Gallery Image 3](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786604831/gujarat-post/mjafhgxgnfe7o01ukq84.jpg)\n\n![Gallery Image 4](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786604839/gujarat-post/ghjlcbafa07h1mds9q9c.jpg)\n\n![Gallery Image 5](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786687914/gujarat-post/sqOLXMWIq41rUH75OzCeLTn6O53Lp2qAEoLrEmQyYhN9tb9qHgPLLNU_4vfr5AKlXUGZmQOMuoA_0EuITU52Th_O4oWxwQX18p_3ynxqMmj_hgW9Rbeyv2B_MW6INh1r2Iv6_Ax_6_GuWnux6tMUoFoE821xd1bkcMhD6YuJmPY_1786687914445_557_vy8erp.jpg)\n\n> "ભારે વરસાદ અને પૂરગ્રસ્ત વિસ્તારોમાં રાહત અને બચાવ કામગીરીને પ્રાથમિકતા આપવામાં આવી રહી છે"\n> — સ્થાનિક પ્રશાસન / રાહત-બચાવ કામગીરી\n\n<div class="my-6 aspect-video w-full overflow-hidden rounded-2xl border border-zinc-200 dark:border-zinc-800 shadow-md"><iframe src="https://www.youtube.com/embed/pQSoW2aiUCY" class="h-full w-full" allowfullscreen frameborder="0"></iframe></div>\n\n<div class="gp-x-card"><div style="display:flex;align-items:center;gap:14px;min-width:0;position:relative;z-index:1"><span class="gp-x-icon">𝕏</span><div style="min-width:0"><span class="gp-x-title">View Official Post on X (Twitter)</span><span class="gp-x-sub">સત્તાવાર ટ્વીટ જોવા માટે અહી ક્લિક કરો</span></div></div><a href="https://x.com/DeshGujarat/status/2080286146630938948" target="_blank" rel="noopener noreferrer" class="gp-x-btn" style="position:relative;z-index:1"><span>ટ્વીટ જુઓ ↗</span></a></div>\n\n<div class="gp-pdf-card"><div class="gp-pdf-inner"><div class="gp-pdf-icon-wrap"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/><polyline points="10 9 9 9 8 9"/></svg></div><div class="gp-pdf-text"><span class="gp-pdf-title">Attached Official Document (PDF)</span><span class="gp-pdf-sub">Verified Official Document</span></div></div><a href="/uploads/Attendance_Syllabus_API_Documentation_1786690605969_8124.pdf" target="_blank" rel="noopener noreferrer" download class="gp-pdf-btn"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg><span>Download PDF</span></a></div>', '## 📌 એક નજરમાં (KEY HIGHLIGHTS)\n--------------------------------------------------\nગુજરાતમાં ભારે વરસાદ અને પૂરથી બે દિવસમાં 35 લોકોનાં મોત નોંધાયા.\nઅમદાવાદમાં 24 કલાકમાં 294.6 મિમી વરસાદ નોંધાયો.\nઅમદાવાદનો આ વરસાદ શહેરના ઇતિહાસમાં ચોથો સૌથી વધુ 24 કલાકનો વરસાદ રહ્યો.\n23 જુલાઈએ અમદાવાદમાં માત્ર બે કલાકમાં 177 મિમી વરસાદ નોંધાયો હતો.\nભારે વરસાદને કારણે અનેક રસ્તાઓ અને અંડરપાસમાં પાણી ભરાયા.\nદક્ષિણ ગુજરાતમાં પૂરગ્રસ્ત વિસ્તારોમાંથી હજારો લોકોને સલામત સ્થળે ખસેડવામાં આવ્યા.\nNDRF, SDRF, સ્થાનિક તંત્ર અને સશસ્ત્ર દળોએ રાહત અને બચાવ કામગીરી હાથ ધરી.\n--------------------------------------------------\n\n<p class="isSelectedEnd"><b>ગુજરાતમાં ચોમાસાએ ફરી એકવાર ભારે તબાહી મચાવી છે. રાજ્યના અનેક વિસ્તારોમાં ભારે વરસાદને કારણે પૂર જેવી સ્થિતિ સર્જાઈ છે. સતત વરસાદથી નદી-નાળાઓમાં પાણીનું સ્તર વધ્યું છે અને અનેક વિસ્તારોમાં પાણી ભરાઈ જતાં સામાન્ય જનજીવનને ભારે અસર પહોંચી છે.</b></p><p><u>25 જુલાઈ 2026ના અહેવાલો અનુસાર, ગુજરાતમાં ભારે વરસાદ અને પૂરની પરિસ્થિતિને કારણે બે દિવસમાં મૃત્યુઆંક 35 સુધી પહોંચ્યો હતો. ભારે અસરગ્રસ્ત વિસ્તારોમાં બચાવ અને રાહત કામગીરી પણ તેજ કરવામાં આવી હતી</u></p>\n\n![Gallery Image 2](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786604828/gujarat-post/a9xq1h2rr5bktoomfxz6.jpg)\n\n![Gallery Image 3](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786604831/gujarat-post/mjafhgxgnfe7o01ukq84.jpg)\n\n![Gallery Image 4](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786604839/gujarat-post/ghjlcbafa07h1mds9q9c.jpg)\n\n![Gallery Image 5](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786687914/gujarat-post/sqOLXMWIq41rUH75OzCeLTn6O53Lp2qAEoLrEmQyYhN9tb9qHgPLLNU_4vfr5AKlXUGZmQOMuoA_0EuITU52Th_O4oWxwQX18p_3ynxqMmj_hgW9Rbeyv2B_MW6INh1r2Iv6_Ax_6_GuWnux6tMUoFoE821xd1bkcMhD6YuJmPY_1786687914445_557_vy8erp.jpg)\n\n> "ભારે વરસાદ અને પૂરગ્રસ્ત વિસ્તારોમાં રાહત અને બચાવ કામગીરીને પ્રાથમિકતા આપવામાં આવી રહી છે"\n> — સ્થાનિક પ્રશાસન / રાહત-બચાવ કામગીરી\n\nઅમદાવાદમાં નોંધાયેલો 294.6 મિમી વરસાદ સામાન્ય ચોમાસાના વરસાદ કરતાં અત્યંત તીવ્ર ઘટના હતી. 24 કલાકમાં પડેલા આ વરસાદે શહેરની ટ્રાફિક વ્યવસ્થા, ડ્રેનેજ અને નીચાણવાળા વિસ્તારોમાં જનજીવનને અસર કરી<div><figure class="my-4 text-center"><img src="https://akm-img-a-in.tosshub.com/indiatoday/images/story/202607/gujarat-on-monsoon-alert-cloudburst-dumps-177-mm-rain-in-two-hours-over-ahmedabad-235612474-16x9_0.png?VersionId=FIRhWyzVYZU_kB.wi7uRFI2Gm8IRCR79&amp;size=690%3A388" alt="Article Image" class="max-w-full h-auto rounded-xl mx-auto border border-zinc-200 dark:border-zinc-800 shadow-sm"></figure><p></p><div style="text-align: right;">ગુજરાતના દક્ષિણ વિસ્તારોમાં પૂર અને ભારે વરસાદથી અસરગ્રસ્ત લોકો માટે બચાવ કામગીરી ચાલુ રાખવામાં આવી હતી. NDRF અને અન્ય રાહત ટીમોએ પાણીમાં ફસાયેલા લોકોને સુરક્ષિત સ્થળે ખસેડ્યા હતા.</div></div>\n\n<div class="my-6 aspect-video w-full overflow-hidden rounded-2xl border border-zinc-200 dark:border-zinc-800 shadow-md"><iframe src="https://www.youtube.com/embed/pQSoW2aiUCY" class="h-full w-full" allowfullscreen frameborder="0"></iframe></div>\n\n<div class="gp-x-card"><div style="display:flex;align-items:center;gap:14px;min-width:0;position:relative;z-index:1"><span class="gp-x-icon">𝕏</span><div style="min-width:0"><span class="gp-x-title">View Official Post on X (Twitter)</span><span class="gp-x-sub">સત્તાવાર ટ્વીટ જોવા માટે અહી ક્લિક કરો</span></div></div><a href="https://x.com/DeshGujarat/status/2080286146630938948" target="_blank" rel="noopener noreferrer" class="gp-x-btn" style="position:relative;z-index:1"><span>ટ્વીટ જુઓ ↗</span></a></div>\n\n<div class="gp-pdf-card"><div class="gp-pdf-inner"><div class="gp-pdf-icon-wrap"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/><polyline points="10 9 9 9 8 9"/></svg></div><div class="gp-pdf-text"><span class="gp-pdf-title">Attached Official Document (PDF)</span><span class="gp-pdf-sub">Verified Official Document</span></div></div><a href="/uploads/Attendance_Syllabus_API_Documentation_1786690605969_8124.pdf" target="_blank" rel="noopener noreferrer" download class="gp-pdf-btn"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg><span>Download PDF</span></a></div>', '## 📌 एक नजर में (KEY HIGHLIGHTS)\n--------------------------------------------------\nગુજરાતમાં ભારે વરસાદ અને પૂરથી બે દિવસમાં 35 લોકોનાં મોત નોંધાયા.\nઅમદાવાદમાં 24 કલાકમાં 294.6 મિમી વરસાદ નોંધાયો.\nઅમદાવાદનો આ વરસાદ શહેરના ઇતિહાસમાં ચોથો સૌથી વધુ 24 કલાકનો વરસાદ રહ્યો.\n23 જુલાઈએ અમદાવાદમાં માત્ર બે કલાકમાં 177 મિમી વરસાદ નોંધાયો હતો.\nભારે વરસાદને કારણે અનેક રસ્તાઓ અને અંડરપાસમાં પાણી ભરાયા.\nદક્ષિણ ગુજરાતમાં પૂરગ્રસ્ત વિસ્તારોમાંથી હજારો લોકોને સલામત સ્થળે ખસેડવામાં આવ્યા.\nNDRF, SDRF, સ્થાનિક તંત્ર અને સશસ્ત્ર દળોએ રાહત અને બચાવ કામગીરી હાથ ધરી.\n--------------------------------------------------\n\n<p class="isSelectedEnd"><b>ગુજરાતમાં ચોમાસાએ ફરી એકવાર ભારે તબાહી મચાવી છે. રાજ્યના અનેક વિસ્તારોમાં ભારે વરસાદને કારણે પૂર જેવી સ્થિતિ સર્જાઈ છે. સતત વરસાદથી નદી-નાળાઓમાં પાણીનું સ્તર વધ્યું છે અને અનેક વિસ્તારોમાં પાણી ભરાઈ જતાં સામાન્ય જનજીવનને ભારે અસર પહોંચી છે.</b></p><p><u>25 જુલાઈ 2026ના અહેવાલો અનુસાર, ગુજરાતમાં ભારે વરસાદ અને પૂરની પરિસ્થિતિને કારણે બે દિવસમાં મૃત્યુઆંક 35 સુધી પહોંચ્યો હતો. ભારે અસરગ્રસ્ત વિસ્તારોમાં બચાવ અને રાહત કામગીરી પણ તેજ કરવામાં આવી હતી</u></p>\n\n![Gallery Image 2](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786604828/gujarat-post/a9xq1h2rr5bktoomfxz6.jpg)\n\n![Gallery Image 3](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786604831/gujarat-post/mjafhgxgnfe7o01ukq84.jpg)\n\n![Gallery Image 4](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786604839/gujarat-post/ghjlcbafa07h1mds9q9c.jpg)\n\n![Gallery Image 5](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786687914/gujarat-post/sqOLXMWIq41rUH75OzCeLTn6O53Lp2qAEoLrEmQyYhN9tb9qHgPLLNU_4vfr5AKlXUGZmQOMuoA_0EuITU52Th_O4oWxwQX18p_3ynxqMmj_hgW9Rbeyv2B_MW6INh1r2Iv6_Ax_6_GuWnux6tMUoFoE821xd1bkcMhD6YuJmPY_1786687914445_557_vy8erp.jpg)\n\n> "ભારે વરસાદ અને પૂરગ્રસ્ત વિસ્તારોમાં રાહત અને બચાવ કામગીરીને પ્રાથમિકતા આપવામાં આવી રહી છે"\n> — સ્થાનિક પ્રશાસન / રાહત-બચાવ કામગીરી\n\n<div class="my-6 aspect-video w-full overflow-hidden rounded-2xl border border-zinc-200 dark:border-zinc-800 shadow-md"><iframe src="https://www.youtube.com/embed/pQSoW2aiUCY" class="h-full w-full" allowfullscreen frameborder="0"></iframe></div>\n\n<div class="gp-x-card"><div style="display:flex;align-items:center;gap:14px;min-width:0;position:relative;z-index:1"><span class="gp-x-icon">𝕏</span><div style="min-width:0"><span class="gp-x-title">View Official Post on X (Twitter)</span><span class="gp-x-sub">સત્તાવાર ટ્વીટ જોવા માટે અહી ક્લિક કરો</span></div></div><a href="https://x.com/DeshGujarat/status/2080286146630938948" target="_blank" rel="noopener noreferrer" class="gp-x-btn" style="position:relative;z-index:1"><span>ટ્વીટ જુઓ ↗</span></a></div>\n\n<div class="gp-pdf-card"><div class="gp-pdf-inner"><div class="gp-pdf-icon-wrap"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/><polyline points="10 9 9 9 8 9"/></svg></div><div class="gp-pdf-text"><span class="gp-pdf-title">Attached Official Document (PDF)</span><span class="gp-pdf-sub">Verified Official Document</span></div></div><a href="/uploads/Attendance_Syllabus_API_Documentation_1786690605969_8124.pdf" target="_blank" rel="noopener noreferrer" download class="gp-pdf-btn"><svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg><span>Download PDF</span></a></div>', 'https://res.cloudinary.com/dvcffkyjz/video/upload/v1786604707/gujarat-post/ujf3gdzfrlafqgxpi2o8.mp4', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '9162cf30-4fba-40d8-a384-3583cdff56cf', 'Gujarat', 3, 0, 0, 0, 1, 19, 'ગુજરાતમાં ભારે વરસાદ: 35 મોત, અમદાવાદમાં 294.6 મિમી વરસાદ | Gujarat Post', 'ગુજરાતમાં ભારે વરસાદ અને પૂરથી બે દિવસમાં 35 લોકોનાં મોત થયા. અમદાવાદમાં 24 કલાકમાં 294.6 મિમી વરસાદ નોંધાયો, જે શહેરના ઇતિહાસમાં ચોથો સૌથી વધુ વરસાદ છે.', 'Gujarat flood 2026, Gujarat heavy rain, Ahmedabad rain 2026, Ahmedabad flood, Gujarat flood news, Gujarat rainfall, Ahmedabad rainfall, Gujarat monsoon, Gujarat Post, Gujarat weather news', '', 'index, follow', '2026-08-13 07:09:26', '2026-08-19 04:51:21');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('52a5cb03-2077-437a-b7e1-34bb5f8132a3', 'strong-boom-in-surat-textile-market-wave-of-joy-among-traders-13', 113, '#113 - Strong boom in Surat textile market, wave of joy among traders - Full Ground Coverage', '#113 - સુરત ટેક્સટાઇલ માર્કેટમાં જોરદાર તેજી, વેપારીઓમાં ખુશીની લહેર', '#113 - सूरत कपड़ा बाजार में जोरदार तेजी, व्यापारियों में खुशी की लहर', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?w=800&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '6df0d11b-0d54-4980-b581-1e4185a04584', NULL, 5, 108, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:11', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('53406701-ad34-419d-881b-9254ed65d30e', 'major-smart-city-infrastructure-development-unveiled-in-kutch-1786108914929-78', 23, '#23 - Major Smart City Infrastructure Development Unveiled in Kutch', '#23 - Kutch માં મુખ્ય સ્માર્ટ સિટી ઈન્ફ્રાસ્ટ્રક્ચર વિકાસનું અનાવરણ', '#23 - Kutch में प्रमुख स्मार्ट सिटी इंफ्रास्ट्रक्चर विकास का अनावरण', 'Latest updates on smart infrastructure and city development in Kutch. Read complete report inside.', 'Kutch માં Smart Infrastructure and City Development અંગેના વાયરલ અને તાજા સમાચાર.', 'Kutch में Smart Infrastructure and City Development से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>The state government has announced a massive <strong>₹11,950 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Kutch</strong>.</p><p>Officials confirmed that <strong>over 36,300 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Kutch have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹11,950 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Kutch</strong>.</p><p>Officials confirmed that <strong>over 36,300 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Kutch have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹11,950 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Kutch</strong>.</p><p>Officials confirmed that <strong>over 36,300 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Kutch have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', 'https://images.unsplash.com/photo-1556742031-c6961e8560b0?w=800&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'ced0c9a6-760d-4c4a-86ea-ba95385dcd43', 'Kutch, Gujarat', 4, 64, 1, 0, 0, 2, 'Major Smart City Infrastructure Development Unveiled in Kutch | Gujarat Post', 'Latest updates on smart infrastructure and city development in Kutch. Read complete report inside.', 'Kutch, Gujarat news, Education, latest updates', NULL, NULL, '2026-08-01 01:21:54', '2026-08-17 10:00:45');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('56223c0a-1513-495a-9910-949d4f90edcf', 'green-energy-initiative-set-to-power-100-of-bhavnagar-public-grid-1786108909190-43', 58, '#58 - Green Energy Initiative Set to Power 100% of Bhavnagar Public Grid', '#58 - હરિત ઊર્જા પહેલ Bhavnagar પબ્લિક ગ્રીડના 100% ને પાવર આપવા માટે તૈયાર', '#58 - हरित ऊर्जा पहल Bhavnagar पब्लिक ग्रिड को 100% बिजली देने के लिए तैयार', 'Latest updates on renewable energy and environment in Bhavnagar. Read complete report inside.', 'Bhavnagar માં Renewable Energy and Environment અંગેના વાયરલ અને તાજા સમાચાર.', 'Bhavnagar में Renewable Energy and Environment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>6,700 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>6,700 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>6,700 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', 'https://images.unsplash.com/photo-1571019614242-c5c5dee9f50b?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', '75adf9cb-45e9-469f-9628-a563fb789283', 'Bhavnagar, Gujarat', 5, 84, 0, 0, 0, 0, 'Green Energy Initiative Set to Power 100% of Bhavnagar Public Grid | Gujarat Post', 'Latest updates on renewable energy and environment in Bhavnagar. Read complete report inside.', 'Bhavnagar, Gujarat news, Rajkot, latest updates', NULL, NULL, '2026-08-03 23:21:49', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('57636af1-8236-4bef-baae-8b138e6413ac', 'congress-announces-campaign-strategy-for-gujarat-2027-57', 157, '#157 - Congress announces campaign strategy for Gujarat 2027 - Full Ground Coverage', '#157 - કોંગ્રેસે ગુજરાત 2027 ચૂંટણી ઝુંબેશ વ્યૂહ જાહેર કર્યો', '#157 - कांग्रेस ने गुजरात 2027 चुनाव अभियान रणनीति घोषित की', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1599930113854-d6d7fd521f10?w=800&q=80', 'PUBLISHED', NULL, '6e329fea-cd2d-4295-a98e-64bddfe20da6', '33c842e2-4efa-4b25-a12d-ac1a1fe1f561', NULL, 4, 64, 1, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:24', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('584a981b-79ff-48f4-bada-b416e85923c1', 'botad-salangpur-hanuman-dham-bhojanalaya-expansion', 270, 'Botad Salangpur Hanuman Dham Tourist Facility Expansion', 'બોટાદ સાળંગપુર શ્રી કષ્ટભંજનદેવ હનુમાનજી મંદિર નવો ભોજનાલય અને યાત્રી ભવન', 'बोटाद सारंगपुर श्री कष्टभंजनदेव हनुमानजी मंदिर नया भोजनालय और यात्री भवन', 'Salangpur Dham Botad inaugurates mega automated kitchen serving 50000 devotees daily.', 'સાળંગપુરમાં કષ્ટભંજન દેવ મંદિર ખાતે વિશ્વકક્ષાના ઓટોમેટેડ રસોડા અને યાત્રિક નિવાસનું લોકાર્પણ.', 'सारंगपुर में कष्टभंजन देव मंदिर में विश्व स्तरीय स्वचालित रसोई और यात्री निवास का उद्घाटन।', '<p>બોટાદ જિલ્લાના સાળંગપુર ધામ ખાતે શ્રી કષ્ટભંજનદેવ હનુમાનજી મંદિરે દરરોજ ૫૦,૦૦૦થી વધુ ભક્તો માટે હાઇટેક મહાપ્રસાદ ભોજનાલય આશીર્વાદરૂપ બન્યું છે. સોલાર ગ્રીડ અને હાઇજીનિક કૂકિંગ ટેકનોલોજીથી સેવાકાર્ય ચાલી રહ્યું છે.</p>', '<p>બોટાદ જિલ્લાના સાળંગપુર ધામ ખાતે શ્રી કષ્ટભંજનદેવ મંદિરે હાઇટેક મહાપ્રસાદ ભોજનાલય શરૂ થયું.</p>', '<p>बोटाद जिले के सारंगपुर धाम में श्री कष्टभंजनदेव मंदिर में हाई-टेक महाप्रसाद भोजनालय शुरू हुआ।</p>', 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=1200&q=90', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '968c7b79-e486-4a36-8720-99f33c015339', 'Botad', 0, 0, 1, 0, 1, 16, NULL, NULL, NULL, NULL, NULL, '2026-08-12 06:12:35', '2026-08-19 04:51:17');
