INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('59bfdffd-a2fc-41ee-b6f1-5d573972ff53', 'state-of-the-art-multi-specialty-hospital-inaugurated-in-kutch-1786108915926-87', 14, '#14 - State-of-the-Art Multi-Specialty Hospital Inaugurated in Kutch', '#14 - Kutch માં અત્યાધુનિક મલ્ટી-સ્પેશિયાલિટી હોસ્પિટલનું ઉદ્ઘાટન', '#14 - Kutch में अत्याधुनिक मल्टी-स्पेशलिटी अस्पताल का उद्घाटन', 'Latest updates on healthcare and medical breakthroughs in Kutch. Read complete report inside.', 'Kutch માં Healthcare and Medical Breakthroughs અંગેના વાયરલ અને તાજા સમાચાર.', 'Kutch में Healthcare and Medical Breakthroughs से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A new <strong>13,300-bed advanced hospital facility</strong> was officially opened to the public in <strong>Kutch</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 40,350 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>13,300-bed advanced hospital facility</strong> was officially opened to the public in <strong>Kutch</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 40,350 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>13,300-bed advanced hospital facility</strong> was officially opened to the public in <strong>Kutch</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 40,350 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', 'https://images.unsplash.com/photo-1472214103451-9374bd1c798e?w=800&q=80', 'PUBLISHED', NULL, '6e329fea-cd2d-4295-a98e-64bddfe20da6', '0ff7c7f6-b114-4f1e-a8ce-e929b9604d31', 'Kutch, Gujarat', 4, 63, 1, 0, 0, 0, 'State-of-the-Art Multi-Specialty Hospital Inaugurated in Kutch | Gujarat Post', 'Latest updates on healthcare and medical breakthroughs in Kutch. Read complete report inside.', 'Kutch, Gujarat news, Podcasts, latest updates', NULL, NULL, '2026-07-31 07:21:55', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('5a43cf6d-4079-448d-834b-d555cff252c7', 'drug-trafficking-route-from-pakistan-via-gujarat-busted-34', 134, '#134 - Drug trafficking route from Pakistan via Gujarat busted - Full Ground Coverage', '#134 - પાકિસ્તાનથી ગુજરાત થઈ ડ્રગ ટ્રાફિકિંગ રૂટ ઝડપ્યો', '#134 - पाकिस्तान से गुजरात के रास्ते ड्रग तस्करी रूट का भंडाफोड़', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '66cc1ef6-a0d8-4f6b-8d37-2de024e24d6a', NULL, 6, 87, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:17', '2026-08-14 11:11:58');
