INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('6c651ee4-c2eb-4656-b390-d5857501006d', 'state-of-the-art-multi-specialty-hospital-inaugurated-in-kutch-1786108905010-15', 86, '#86 - State-of-the-Art Multi-Specialty Hospital Inaugurated in Kutch', '#86 - Kutch માં અત્યાધુનિક મલ્ટી-સ્પેશિયાલિટી હોસ્પિટલનું ઉદ્ઘાટન', '#86 - Kutch में अत्याधुनिक मल्टी-स्पेशलिटी अस्पताल का उद्घाटन', 'Latest updates on healthcare and medical breakthroughs in Kutch. Read complete report inside.', 'Kutch માં Healthcare and Medical Breakthroughs અંગેના વાયરલ અને તાજા સમાચાર.', 'Kutch में Healthcare and Medical Breakthroughs से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A new <strong>2,500-bed advanced hospital facility</strong> was officially opened to the public in <strong>Kutch</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 7,950 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>2,500-bed advanced hospital facility</strong> was officially opened to the public in <strong>Kutch</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 7,950 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>2,500-bed advanced hospital facility</strong> was officially opened to the public in <strong>Kutch</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 7,950 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', 'https://images.unsplash.com/photo-1509395062183-67c5ad6faff9?w=800&q=80', 'PUBLISHED', NULL, '6e329fea-cd2d-4295-a98e-64bddfe20da6', '75adf9cb-45e9-469f-9628-a563fb789283', 'Kutch, Gujarat', 6, 55, 1, 0, 0, 0, 'State-of-the-Art Multi-Specialty Hospital Inaugurated in Kutch | Gujarat Post', 'Latest updates on healthcare and medical breakthroughs in Kutch. Read complete report inside.', 'Kutch, Gujarat news, Rajkot, latest updates', NULL, NULL, '2026-08-06 07:21:45', '2026-08-14 11:11:58');
