INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('898de8ac-dd39-4efb-ac3e-9f0c884b65c1', 'gandhinagar-athletes-win-big-at-national-championship-event-1786108911415-58', 43, '#43 - Gandhinagar Athletes Win Big at National Championship Event', '#43 - રાષ્ટ્રીય ચેમ્પિયનશિપ ઇવેન્ટમાં Gandhinagar ના ખેલાડીઓની ભવ્ય જીત', '#43 - राष्ट्रीय चैंपियनशिप प्रतियोगिता में Gandhinagar के एथलीटों ने बड़ी जीत हासिल की', 'Latest updates on sports excellence and youth empowerment in Gandhinagar. Read complete report inside.', 'Gandhinagar માં Sports Excellence and Youth Empowerment અંગેના વાયરલ અને તાજા સમાચાર.', 'Gandhinagar में Sports Excellence and Youth Empowerment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Athletes from <strong>Gandhinagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>8,950 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹27,300 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Gandhinagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>8,950 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹27,300 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Gandhinagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>8,950 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹27,300 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', 'https://images.unsplash.com/photo-1523731407965-2430cd12f5e4?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '05acdc57-4700-4770-978b-c85f37e0f687', 'Gandhinagar, Gujarat', 3, 65, 0, 0, 0, 1, 'Gandhinagar Athletes Win Big at National Championship Event | Gujarat Post', 'Latest updates on sports excellence and youth empowerment in Gandhinagar. Read complete report inside.', 'Gandhinagar, Gujarat news, Entertainment, latest updates', NULL, NULL, '2026-08-02 17:21:51', '2026-08-17 10:00:55');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('899f442e-3de5-4ddc-bd4b-fdc002ef92f1', 'major-smart-city-infrastructure-development-unveiled-in-rajkot-1786108904669-12', 89, '#89 - Major Smart City Infrastructure Development Unveiled in Rajkot', '#89 - Rajkot માં મુખ્ય સ્માર્ટ સિટી ઈન્ફ્રાસ્ટ્રક્ચર વિકાસનું અનાવરણ', '#89 - Rajkot में प्रमुख स्मार्ट सिटी इंफ्रास्ट्रक्चर विकास का अनावरण', 'Latest updates on smart infrastructure and city development in Rajkot. Read complete report inside.', 'Rajkot માં Smart Infrastructure and City Development અંગેના વાયરલ અને તાજા સમાચાર.', 'Rajkot में Smart Infrastructure and City Development से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>The state government has announced a massive <strong>₹2,050 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Rajkot</strong>.</p><p>Officials confirmed that <strong>over 6,600 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Rajkot have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹2,050 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Rajkot</strong>.</p><p>Officials confirmed that <strong>over 6,600 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Rajkot have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹2,050 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Rajkot</strong>.</p><p>Officials confirmed that <strong>over 6,600 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Rajkot have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', 'https://images.unsplash.com/photo-1531297484001-80022131f5a1?w=800&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '6df0d11b-0d54-4980-b581-1e4185a04584', 'Rajkot, Gujarat', 5, 90, 1, 0, 0, 0, 'Major Smart City Infrastructure Development Unveiled in Rajkot | Gujarat Post', 'Latest updates on smart infrastructure and city development in Rajkot. Read complete report inside.', 'Rajkot, Gujarat news, Business, latest updates', NULL, NULL, '2026-08-06 13:21:44', '2026-08-14 11:11:58');
