INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('8cfe2f2a-74cc-4849-9adc-3cab9c770eb9', 'market-boom-business-investments-in-gujarat-reach-record-high-1786108914816-77', 24, '#24 - Market Boom: Business Investments in Gujarat Reach Record High', '#24 - માર્કેટ બૂમ: Gujarat માં વ્યાપારી રોકાણ રેકોર્ડ સપાટીએ પહોંચ્યું', '#24 - मार्केट बूम: Gujarat में व्यावसायिक निवेश रिकॉर्ड स्तर पर पहुंचा', 'Latest updates on business, finance and market trends in Gujarat. Read complete report inside.', 'Gujarat માં Business, Finance and Market Trends અંગેના વાયરલ અને તાજા સમાચાર.', 'Gujarat में Business, Finance and Market Trends से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Foreign and domestic investments in <strong>Gujarat</strong> surged to an all-time high of <strong>₹11,800 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 35,850 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Gujarat</strong> surged to an all-time high of <strong>₹11,800 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 35,850 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Gujarat</strong> surged to an all-time high of <strong>₹11,800 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 35,850 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', 'https://images.unsplash.com/photo-1526778548025-fa2f459cd5c1?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', 'b7016886-3e6a-4452-a198-afcfa9e5663d', 'Gujarat, Gujarat', 5, 52, 0, 1, 0, 0, 'Market Boom: Business Investments in Gujarat Reach Record High | Gujarat Post', 'Latest updates on business, finance and market trends in Gujarat. Read complete report inside.', 'Gujarat, Gujarat news, Gandhinagar, latest updates', NULL, NULL, '2026-08-01 03:21:54', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('8f44810b-dbde-434b-a45b-ae07dc6166e3', 'fact-check-gujarat-sunday-lockdown-reimposition-fake-news', 244, 'Fact Check: Gujarat Home Department Denies Viral Rumor of Sunday Curfew Reimposition', 'ફેક્ટ ચેક: ગુજરાતમાં રવિવારે સપ્તાહાંત કરફ્યુ લાગુ થવા અંગેના વાયરલ મેસેજ તદ્દન ફેક ન્યૂઝ છે', 'फैक्ट चेक: गुजरात में रविवार को वीकेंड कर्फ्यू लागू होने के वायरल मैसेज पूरी तरह से फर्जी हैं', 'Gujarat Home Department confirms no Sunday lockdown or night curfew guidelines have been issued by state authorities.', 'ગુજરાત ગૃહ વિભાગે સ્પષ્ટતા કરી છે કે રાજ્યમાં રવિવારનો કોઈ લોકડાઉન કે કરફ્યુ લાગુ કરવાનો નિર્ણય લેવાયો નથી.', 'गुजरात गृह विभाग ने स्पष्ट किया है कि राज्य में कोई रविवार लॉकडाउन या कर्फ्यू का नियम लागू नहीं किया गया है।', '<p><strong>Claim:</strong> Social media graphics claiming to represent Gujarat Government notifications state that a strict Sunday lockdown will be enforced across major cities from this weekend.</p>\n<h2>Fact Check Analysis</h2>\n<p>Gujarat State Home Department spokespersons confirmed that the graphic is a fabricated edit of old 2021 pandemic advisories. No curfews or movement restrictions are in place.</p>\n<ul>\n<li>Markets, offices, public transport, and commercial establishments will remain open as normal.</li>\n<li>Legal action has been initiated against social media handles spreading outdated lockdown circulars.</li>\n</ul>\n<blockquote>"Verdict: ❌ FAKE NEWS. No Sunday lockdown in Gujarat."</blockquote>', '<p><strong>દાવો:</strong> સોશિયલ મીડિયા પર ગુજરાત સરકારના પરિપત્ર જેવો જણાતો એક ગ્રાફિક વાયરલ થઈ રહ્યો છે જેમાં કહેવાયું છે કે આ રવિવારથી રાજ્યના તમામ મોટા શહેરોમાં સખત રવિવાર લોકડાઉન લાગુ થશે.</p>\n<h2>તપાસ અને સાચું તથ્ય</h2>\n<p>ગુજરાત રાજ્ય ગૃહ વિભાગે સ્પષ્ટ કર્યુ છે કે આ વાયરલ ગ્રાફિક ૨૦૨૧ના જૂના રોગચાળા સમયના નોટિફિકેશનનું બોગસ એડિટિંગ છે. રાજ્યમાં આવી કોઈ પાબંદી નથી.</p>\n<ul>\n<li>તમામ બજારો, સરકારી-ખાનગી ઓફિસો અને ટ્રાન્સપોર્ટ સામાન્ય રીતે ચાલુ રહેશે.</li>\n<li>અફવા ફેલાવનાર સોશિયલ મીડિયા એકાઉન્ટ્સ સામે કાર્યવાહી શરૂ કરાઈ છે.</li>\n</ul>\n<blockquote>"ચુકાદો: ❌ તદ્દન ખોટા સમાચાર અને અફવા."</blockquote>', '<p><strong>दावा:</strong> गुजरात के शहरों में फिर से संडे लॉकडाउन लागू होने जा रहा है।</p>\n<h2>सच्चाई</h2>\n<p>गृह विभाग ने इसे 2021 का पुराना एडिटेड मैसेज बताया है और किसी भी प्रकार का कर्फ्यू नहीं है।</p>\n<blockquote>"फैसला: ❌ फर्जी खबर।"</blockquote>', 'https://images.unsplash.com/photo-1584483766114-2cea6facdf57?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'b6423e89-dda8-489c-bd82-78e0fe179d65', NULL, 3, 92, 1, 1, 1, 4, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:51:51', '2026-08-17 10:13:29');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('9091a629-730d-46cd-9593-9c70067832c1', 'surat-athletes-win-big-at-national-championship-event-1786108918304-100', 1, '#1 - Surat Athletes Win Big at National Championship Event', '#1 - રાષ્ટ્રીય ચેમ્પિયનશિપ ઇવેન્ટમાં Surat ના ખેલાડીઓની ભવ્ય જીત', '#1 - राष्ट्रीय चैंपियनशिप प्रतियोगिता में Surat के एथलीटों ने बड़ी जीत हासिल की', 'Latest updates on sports excellence and youth empowerment in Surat. Read complete report inside.', 'Surat માં Sports Excellence and Youth Empowerment અંગેના વાયરલ અને તાજા સમાચાર.', 'Surat में Sports Excellence and Youth Empowerment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Athletes from <strong>Surat</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>15,250 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹46,200 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Surat</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>15,250 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹46,200 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Surat</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>15,250 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹46,200 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', 'https://images.unsplash.com/photo-1492562080023-ab3db95bfbce?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '8ab79b8f-0ccd-4354-82c7-3ad84b99807c', 'Surat, Gujarat', 3, 90, 0, 0, 0, 0, 'Surat Athletes Win Big at National Championship Event | Gujarat Post', 'Latest updates on sports excellence and youth empowerment in Surat. Read complete report inside.', 'Surat, Gujarat news, National, latest updates', NULL, NULL, '2026-07-30 05:21:58', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('90cb9f51-d8b9-4def-8d16-a0f39cfb5d28', 'cm-holds-review-meeting-for-development-projects-92', 192, '#192 - CM holds review meeting for development projects - Full Ground Coverage', '#192 - CM એ વિકાસ પ્રોજેક્ટ માટે સમીક્ષા બેઠક યોજી', '#192 - CM ने विकास परियोजनाओं के लिए समीक्षा बैठक की', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1599930113854-d6d7fd521f10?w=800&q=80', 'PUBLISHED', NULL, '6e329fea-cd2d-4295-a98e-64bddfe20da6', '33c842e2-4efa-4b25-a12d-ac1a1fe1f561', NULL, 4, 29, 1, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:37', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('94b1dc9c-ce12-4193-824a-3e75bc7e657e', 'fact-check-ai-replacing-90-percent-it-jobs-misleading-report', 237, 'Fact Check: Claim that AI will Replace 90% Software Engineers by End of Year Misquotes Report', 'ફેક્ટ ચેક: ચાલુ વર્ષે AI ૯૦% સોફ્ટવેર એન્જિનિયરોની નોકરીઓ છીનવી લેશે તેવો દાવો ભ્રામક', 'फैक्ट चेक: इस साल एआई 90% सॉफ्टवेयर इंजीनियरों की नौकरियां छीन लेगा, यह दावा भ्रामक है', 'Viral posts citing NASSCOM report claim 90% IT software engineers will lose jobs to AI; original study emphasizes skill evolution, not mass layoffs.', 'નેસ્કોમના રિપોર્ટને ટાંકીને AI થી ૯૦ ટકા નોકરીઓ ખતમ થવાના વાયરલ દાવાઓ મૂળ રિપોર્ટના ખોટા અર્થઘટન પર આધારિત છે.', 'नासकॉम रिपोर्ट का हवाला देकर 90% नौकरियां खत्म होने का दावा रिपोर्ट के गलत अर्थ पर आधारित है।', '<p><strong>Claim:</strong> Social media headlines state that NASSCOM released a report stating AI tools will replace 90% of IT developers and software programmers by the end of 2026.</p>\n<h2>Fact Check Analysis</h2>\n<p>We examined the full NASSCOM Tech Skills Report. The report states that 90% of developers will use AI coding assistants to increase productivity, not that 90% of workforce will be laid off.</p>\n<ul>\n<li>Industry experts highlight that AI automates repetitive tasks while creating new roles in AI engineering, prompt design, and system architecture.</li>\n<li>NASSCOM issued a statement clarifying their findings were misinterpreted by clickbait headlines.</li>\n</ul>\n<blockquote>"Verdict: ⚠️ MISLEADING & OUT OF CONTEXT. Report highlights AI adoption, not job destruction."</blockquote>', '<p><strong>દાવો:</strong> સોશિયલ મીડિયા હેડલાઇન્સમાં દાવો કરાઈ રહ્યો છે કે નેસ્કોમના તાજેતરના રિપોર્ટ મુજબ આર્ટિફિશિયલ ઇન્ટેલિજન્સ આ વર્ષના અંત સુધીમાં ૯૦% IT સોફ્ટવેર એન્જિનિયરોની નોકરીઓ નાબૂદ કરી દેશે.</p>\n<h2>તપાસ અને તથ્ય</h2>\n<p>અમારી ટીમે નેસ્કોમના ટેક સ્કીલ્સ રિપોર્ટનું વિશ્લેષણ કર્યું. રિપોર્ટમાં લખ્યું છે કે ૯૦% ડેવલપર્સ કોડિંગ માટે AI ટૂલ્સનો ઉપયોગ કરશે જેથી કામ ઝડપી બને, નોકરીઓ છીનવાઈ જવાની વાત નથી.</p>\n<ul>\n<li>આઇટી નિષ્ણાતો જણાવે છે કે AI ના કારણે ડેટા એન્જિનિયરિંગ અને AI સિસ્ટમ ડિઝાઇન જેવા નવા ક્ષેત્રોમાં માંગ વધી રહી છે.</li>\n<li>નેસ્કોમે સ્પષ્ટતા કરી છે કે તેમના સંશોધનને સોશિયલ મીડિયા પર ખોટી રીતે રજૂ કરવામાં આવ્યું છે.</li>\n</ul>\n<blockquote>"ચુકાદો: ⚠️ ભ્રામક અને ખોટા સંદર્ભમાં વાયરલ થયેલી માહિતી."</blockquote>', '<p><strong>दावा:</strong> एआई इस साल 90% सॉफ्टवेयर इंजीनियरों की नौकरियां खत्म कर देगा।</p>\n<h2>सच्चाई</h2>\n<p>नासकॉम की रिपोर्ट में कहा गया है कि 90% डेवलपर्स उत्पादकता बढ़ाने के लिए एआई का उपयोग करेंगे, न कि नौकरियां खोएंगे।</p>\n<blockquote>"फैसला: ⚠️ भ्रामक जानकारी।"</blockquote>', 'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'b6423e89-dda8-489c-bd82-78e0fe179d65', NULL, 4, 85, 1, 0, 1, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:51:42', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('9581b6c1-d57d-4157-a092-f576ba46e1fa', 'market-boom-business-investments-in-vadodara-reach-record-high-1786108909639-47', 54, '#54 - Market Boom: Business Investments in Vadodara Reach Record High', '#54 - માર્કેટ બૂમ: Vadodara માં વ્યાપારી રોકાણ રેકોર્ડ સપાટીએ પહોંચ્યું', '#54 - मार्केट बूम: Vadodara में व्यावसायिक निवेश रिकॉर्ड स्तर पर पहुंचा', 'Latest updates on business, finance and market trends in Vadodara. Read complete report inside.', 'Vadodara માં Business, Finance and Market Trends અંગેના વાયરલ અને તાજા સમાચાર.', 'Vadodara में Business, Finance and Market Trends से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Foreign and domestic investments in <strong>Vadodara</strong> surged to an all-time high of <strong>₹7,300 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 22,350 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Vadodara</strong> surged to an all-time high of <strong>₹7,300 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 22,350 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Vadodara</strong> surged to an all-time high of <strong>₹7,300 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 22,350 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', 'https://images.unsplash.com/photo-1504608524841-42584120d693?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', 'b507430b-2601-487f-be29-cfad6558ee30', 'Vadodara, Gujarat', 6, 63, 0, 0, 0, 0, 'Market Boom: Business Investments in Vadodara Reach Record High | Gujarat Post', 'Latest updates on business, finance and market trends in Vadodara. Read complete report inside.', 'Vadodara, Gujarat news, Shorts, latest updates', NULL, NULL, '2026-08-03 15:21:49', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('965b48fd-af83-4889-b6bd-4a4d0d445049', 'green-energy-initiative-set-to-power-100-of-bhavnagar-public-grid-1786108917917-97', 4, '#4 - Green Energy Initiative Set to Power 100% of Bhavnagar Public Grid', '#4 - હરિત ઊર્જા પહેલ Bhavnagar પબ્લિક ગ્રીડના 100% ને પાવર આપવા માટે તૈયાર', '#4 - हरित ऊर्जा पहल Bhavnagar पब्लिक ग्रिड को 100% बिजली देने के लिए तैयार', 'Latest updates on renewable energy and environment in Bhavnagar. Read complete report inside.', 'Bhavnagar માં Renewable Energy and Environment અંગેના વાયરલ અને તાજા સમાચાર.', 'Bhavnagar में Renewable Energy and Environment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>14,800 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>14,800 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>14,800 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', 'https://images.unsplash.com/photo-1524504388940-b1c1722653e1?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', '6f23d06f-50b3-4d6b-9834-42d7133b08a8', 'Bhavnagar, Gujarat', 4, 60, 0, 0, 0, 0, 'Green Energy Initiative Set to Power 100% of Bhavnagar Public Grid | Gujarat Post', 'Latest updates on renewable energy and environment in Bhavnagar. Read complete report inside.', 'Bhavnagar, Gujarat news, Vadodara, latest updates', NULL, NULL, '2026-07-30 11:21:57', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('98816a2d-2dc6-4287-80ca-5ed5ad5a2cdb', 'fact-check-rs-2000-note-reintroduction-satellite-chip-rumor', 233, 'Fact Check: RBI Re-introducing Rs 2000 Currency Notes with Nano-GPS Chip is False', 'ફેક્ટ ચેક: ₹૨૦૦૦ની ચલણી નોટો નેનો જીપીએસ ચિપ સાથે ફરી ચલણમાં આવશે તેવો દાવો તદ્દન પાયાવિહોણો', 'फैक्ट चेक: नैनो जीपीएस चिप के साथ ₹2000 के नोट फिर से चलन में आएंगे, दावा पूरी तरह गलत है', 'Social media posts claiming Reserve Bank of India is bringing back Rs 2000 notes equipped with GPS microchips are completely fabricated.', 'આરબીઆઈ ૨૦૦૦ની નોટો જીપીએસ ચિપ સાથે ફરી બહાર પાડશે તેવા સોશિયલ મીડિયા પર વાયરલ દાવાઓ તદ્દન બનાવટી અને અફવા છે.', 'आरबीआई 2000 रुपये के नोटों को जीपीएस चिप के साथ वापस ला रहा है, यह सोशल मीडिया दावा पूरी तरह से फर्जी है।', '<p><strong>Claim:</strong> Social media posts state that the Reserve Bank of India (RBI) is preparing to reissue Rs 2000 currency notes embedded with satellite tracking microchips in 2026.</p>\n<h2>Fact Check Analysis</h2>\n<p>Our fact-checking unit reviewed RBI press releases and official circulars. RBI withdrawn Rs 2000 notes from circulation under Clean Note Policy and has issued no decision to reintroduce them.</p>\n<ul>\n<li>RBI officials confirmed no currency note in the world contains satellite tracking microchips.</li>\n<li>Old viral hoaxes from 2016 are being reshared with new dates.</li>\n</ul>\n<blockquote>"Verdict: ❌ FALSE RUMOR. No Rs 2000 notes are being re-issued."</blockquote>', '<p><strong>દાવો:</strong> સોશિયલ મીડિયા પર એવો દાવો વાયરલ થયો છે કે રિઝર્વ બેંક ઓફ ઇન્ડિયા (RBI) ૨૦૨૬માં સેટેલાઇટ જીપીએસ ચિપ ધરાવતી ₹૨૦૦૦ની નોટો ફરી ચલણમાં મૂકવા જઈ રહી છે.</p>\n<h2>તપાસ અને સાચું તથ્ય</h2>\n<p>અમારી ફેક્ટ ચેક ટીમે RBIની અધિકૃત વેબસાઇટ અને પબ્લિક રિલેશન્સ વિભાગ દ્વારા જારી કરાયેલ પરિપત્રો તપાસ્યા. RBI એ ક્લીન નોટ પોલિસી હેઠળ ૨૦૦૦ની નોટો ચલણમાંથી પાછી ખેંચી લીધી હતી અને તેને ફરી શરૂ કરવાનો કોઈ નિર્ણય લેવાયો નથી.</p>\n<ul>\n<li>RBI એ સ્પષ્ટ કર્યું છે કે ચલણી નોટોમાં કોઈ જીપીએસ ચિપ મૂકવાની ટેકનોલોજી અસ્તિત્વમાં નથી.</li>\n<li>૨૦૧૬ની જૂની અફવાઓને નવા વર્ષની તારીખો સાથે સોશિયલ મીડિયા પર ફરી વાયરલ કરવામાં આવી રહી છે.</li>\n</ul>\n<blockquote>"ચુકાદો: ❌ તદ્દન ખોટો દાવો અને પાયાવિહોણી અફવા."</blockquote>', '<p><strong>दावा:</strong> सोशल मीडिया पर कहा जा रहा है कि आरबीआई जीपीएस चिप वाले ₹2000 के नोट फिर जारी करने जा रहा है।</p>\n<h2>जांच और सच्चाई</h2>\n<p>आरबीआई ने स्पष्ट किया है कि नोटों को वापस लाने का कोई प्रस्ताव नहीं है और जीपीएस चिप की बात पूरी तरह से मनगढ़ंत है।</p>\n<blockquote>"फैसला: ❌ असत्य दावा।"</blockquote>', 'https://images.unsplash.com/photo-1559526324-4b87b5e36e44?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'b6423e89-dda8-489c-bd82-78e0fe179d65', NULL, 3, 88, 0, 0, 1, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:51:39', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('9a4131b9-1bb0-45c8-8661-e664be1cd53c', 'market-boom-business-investments-in-jamnagar-reach-record-high-1786108913604-71', 30, '#30 - Market Boom: Business Investments in Jamnagar Reach Record High', '#30 - માર્કેટ બૂમ: Jamnagar માં વ્યાપારી રોકાણ રેકોર્ડ સપાટીએ પહોંચ્યું', '#30 - मार्केट बूम: Jamnagar में व्यावसायिक निवेश रिकॉर्ड स्तर पर पहुंचा', 'Latest updates on business, finance and market trends in Jamnagar. Read complete report inside.', 'Jamnagar માં Business, Finance and Market Trends અંગેના વાયરલ અને તાજા સમાચાર.', 'Jamnagar में Business, Finance and Market Trends से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Foreign and domestic investments in <strong>Jamnagar</strong> surged to an all-time high of <strong>₹10,900 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 33,150 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Jamnagar</strong> surged to an all-time high of <strong>₹10,900 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 33,150 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Jamnagar</strong> surged to an all-time high of <strong>₹10,900 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 33,150 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', 'https://images.unsplash.com/photo-1575550959106-5a7defe28b56?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', '75adf9cb-45e9-469f-9628-a563fb789283', 'Jamnagar, Gujarat', 5, 71, 0, 0, 0, 0, 'Market Boom: Business Investments in Jamnagar Reach Record High | Gujarat Post', 'Latest updates on business, finance and market trends in Jamnagar. Read complete report inside.', 'Jamnagar, Gujarat news, Rajkot, latest updates', NULL, NULL, '2026-08-01 15:21:53', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('9abeee47-a894-4d24-9abd-e1c52881c068', 'green-energy-initiative-set-to-power-100-of-gandhinagar-public-grid-1786108907305-31', 70, '#70 - Green Energy Initiative Set to Power 100% of Gandhinagar Public Grid', '#70 - હરિત ઊર્જા પહેલ Gandhinagar પબ્લિક ગ્રીડના 100% ને પાવર આપવા માટે તૈયાર', '#70 - हरित ऊर्जा पहल Gandhinagar पब्लिक ग्रिड को 100% बिजली देने के लिए तैयार', 'Latest updates on renewable energy and environment in Gandhinagar. Read complete report inside.', 'Gandhinagar માં Renewable Energy and Environment અંગેના વાયરલ અને તાજા સમાચાર.', 'Gandhinagar में Renewable Energy and Environment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A breakthrough solar and wind hybrid power project in <strong>Gandhinagar</strong> has reached its target capacity of <strong>4,900 Megawatts</strong> this week.</p><p>With this achievement, <strong>Gandhinagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Gandhinagar</strong> has reached its target capacity of <strong>4,900 Megawatts</strong> this week.</p><p>With this achievement, <strong>Gandhinagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Gandhinagar</strong> has reached its target capacity of <strong>4,900 Megawatts</strong> this week.</p><p>With this achievement, <strong>Gandhinagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', 'https://images.unsplash.com/photo-1555169062-013468b47731?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', '0ff7c7f6-b114-4f1e-a8ce-e929b9604d31', 'Gandhinagar, Gujarat', 4, 64, 0, 0, 0, 0, 'Green Energy Initiative Set to Power 100% of Gandhinagar Public Grid | Gujarat Post', 'Latest updates on renewable energy and environment in Gandhinagar. Read complete report inside.', 'Gandhinagar, Gujarat news, Podcasts, latest updates', NULL, NULL, '2026-08-04 23:21:47', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('9bbf4f03-7755-4e1e-84e6-912768e7d49b', 'gujarat-election-2027-preparations-intensify-across-districts-19', 119, '#119 - Gujarat Election 2027 preparations intensify across districts - Full Ground Coverage', '#119 - ગુજરાત ચૂંટણી 2027 માટે જિલ્લાઓમાં તૈયારીઓ તેજ', '#119 - गुजरात चुनाव 2027 की तैयारियां जिलों में तेज', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '33c842e2-4efa-4b25-a12d-ac1a1fe1f561', NULL, 6, 102, 0, 1, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:13', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('9c30d42a-d584-493a-8f9c-a6cc14b0d0f0', 'major-smart-city-infrastructure-development-unveiled-in-kutch-1786108917797-96', 5, '#5 - Major Smart City Infrastructure Development Unveiled in Kutch', '#5 - Kutch માં મુખ્ય સ્માર્ટ સિટી ઈન્ફ્રાસ્ટ્રક્ચર વિકાસનું અનાવરણ', '#5 - Kutch में प्रमुख स्मार्ट सिटी इंफ्रास्ट्रक्चर विकास का अनावरण', 'Latest updates on smart infrastructure and city development in Kutch. Read complete report inside.', 'Kutch માં Smart Infrastructure and City Development અંગેના વાયરલ અને તાજા સમાચાર.', 'Kutch में Smart Infrastructure and City Development से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>The state government has announced a massive <strong>₹14,650 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Kutch</strong>.</p><p>Officials confirmed that <strong>over 44,400 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Kutch have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹14,650 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Kutch</strong>.</p><p>Officials confirmed that <strong>over 44,400 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Kutch have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹14,650 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Kutch</strong>.</p><p>Officials confirmed that <strong>over 44,400 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Kutch have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', 'https://images.unsplash.com/photo-1539571696357-5a69c17a67c6?w=800&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '6df0d11b-0d54-4980-b581-1e4185a04584', 'Kutch, Gujarat', 3, 58, 1, 0, 0, 0, 'Major Smart City Infrastructure Development Unveiled in Kutch | Gujarat Post', 'Latest updates on smart infrastructure and city development in Kutch. Read complete report inside.', 'Kutch, Gujarat news, Business, latest updates', NULL, NULL, '2026-07-30 13:21:57', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('9cfa88d6-b725-4172-9264-6b40a882cb92', 'social-media-influencers-share-local-stories-from-gujarat-40', 140, '#140 - Social media influencers share local stories from Gujarat - Full Ground Coverage', '#140 - સોશિયલ મીડિયા ઇન્ફ્લુએન્સર્સે ગુજરાતની કથાઓ શેર કરી', '#140 - सोशल मीडिया इन्फ्लुएंसर्स ने गुजरात की कहानियां साझा की', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', 'e4f6985f-03b9-48b6-9ec1-8283410a92c4', NULL, 7, 81, 0, 0, 1, 1, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:19', '2026-08-17 10:00:39');
