INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('aef5a373-25de-4d53-afed-1221268346e7', 'green-energy-initiative-set-to-power-100-of-surat-public-grid-1786108905458-19', 82, '#82 - Green Energy Initiative Set to Power 100% of Surat Public Grid', '#82 - હરિત ઊર્જા પહેલ Surat પબ્લિક ગ્રીડના 100% ને પાવર આપવા માટે તૈયાર', '#82 - हरित ऊर्जा पहल Surat पब्लिक ग्रिड को 100% बिजली देने के लिए तैयार', 'Latest updates on renewable energy and environment in Surat. Read complete report inside.', 'Surat માં Renewable Energy and Environment અંગેના વાયરલ અને તાજા સમાચાર.', 'Surat में Renewable Energy and Environment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A breakthrough solar and wind hybrid power project in <strong>Surat</strong> has reached its target capacity of <strong>3,100 Megawatts</strong> this week.</p><p>With this achievement, <strong>Surat becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Surat</strong> has reached its target capacity of <strong>3,100 Megawatts</strong> this week.</p><p>With this achievement, <strong>Surat becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Surat</strong> has reached its target capacity of <strong>3,100 Megawatts</strong> this week.</p><p>With this achievement, <strong>Surat becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', 'https://images.unsplash.com/photo-1559757148-5c350d0d3c56?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', 'b507430b-2601-487f-be29-cfad6558ee30', 'Surat, Gujarat', 3, 87, 0, 0, 0, 0, 'Green Energy Initiative Set to Power 100% of Surat Public Grid | Gujarat Post', 'Latest updates on renewable energy and environment in Surat. Read complete report inside.', 'Surat, Gujarat news, Shorts, latest updates', NULL, NULL, '2026-08-05 23:21:45', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('afec8835-e0f8-4a69-bc50-2c6f0d7e4ae3', 'market-boom-business-investments-in-jamnagar-reach-record-high-1786108905244-17', 84, '#84 - Market Boom: Business Investments in Jamnagar Reach Record High', '#84 - માર્કેટ બૂમ: Jamnagar માં વ્યાપારી રોકાણ રેકોર્ડ સપાટીએ પહોંચ્યું', '#84 - मार्केट बूम: Jamnagar में व्यावसायिक निवेश रिकॉर्ड स्तर पर पहुंचा', 'Latest updates on business, finance and market trends in Jamnagar. Read complete report inside.', 'Jamnagar માં Business, Finance and Market Trends અંગેના વાયરલ અને તાજા સમાચાર.', 'Jamnagar में Business, Finance and Market Trends से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Foreign and domestic investments in <strong>Jamnagar</strong> surged to an all-time high of <strong>₹2,800 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 8,850 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Jamnagar</strong> surged to an all-time high of <strong>₹2,800 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 8,850 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Jamnagar</strong> surged to an all-time high of <strong>₹2,800 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 8,850 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', 'https://images.unsplash.com/photo-1505751172876-fa1923c5c528?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', '9162cf30-4fba-40d8-a384-3583cdff56cf', 'Jamnagar, Gujarat', 6, 75, 0, 0, 0, 0, 'Market Boom: Business Investments in Jamnagar Reach Record High | Gujarat Post', 'Latest updates on business, finance and market trends in Jamnagar. Read complete report inside.', 'Jamnagar, Gujarat news, Gujarat, latest updates', NULL, NULL, '2026-08-06 03:21:45', '2026-08-14 11:11:58');
