INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('b65d94bf-45f0-4f97-8dc1-55a5caf88f1f', 'green-energy-initiative-set-to-power-100-of-gandhinagar-public-grid-1786108904786-13', 88, '#88 - Green Energy Initiative Set to Power 100% of Gandhinagar Public Grid', '#88 - હરિત ઊર્જા પહેલ Gandhinagar પબ્લિક ગ્રીડના 100% ને પાવર આપવા માટે તૈયાર', '#88 - हरित ऊर्जा पहल Gandhinagar पब्लिक ग्रिड को 100% बिजली देने के लिए तैयार', 'Latest updates on renewable energy and environment in Gandhinagar. Read complete report inside.', 'Gandhinagar માં Renewable Energy and Environment અંગેના વાયરલ અને તાજા સમાચાર.', 'Gandhinagar में Renewable Energy and Environment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A breakthrough solar and wind hybrid power project in <strong>Gandhinagar</strong> has reached its target capacity of <strong>2,200 Megawatts</strong> this week.</p><p>With this achievement, <strong>Gandhinagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Gandhinagar</strong> has reached its target capacity of <strong>2,200 Megawatts</strong> this week.</p><p>With this achievement, <strong>Gandhinagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Gandhinagar</strong> has reached its target capacity of <strong>2,200 Megawatts</strong> this week.</p><p>With this achievement, <strong>Gandhinagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', 'https://images.unsplash.com/photo-1488229297570-58520851e868?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', '6f23d06f-50b3-4d6b-9834-42d7133b08a8', 'Gandhinagar, Gujarat', 3, 67, 0, 0, 0, 0, 'Green Energy Initiative Set to Power 100% of Gandhinagar Public Grid | Gujarat Post', 'Latest updates on renewable energy and environment in Gandhinagar. Read complete report inside.', 'Gandhinagar, Gujarat news, Vadodara, latest updates', NULL, NULL, '2026-08-06 11:21:44', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('b66b2240-9dff-4556-ac18-b079314d30f6', 'major-smart-city-infrastructure-development-unveiled-in-ahmedabad-1786108907900-36', 65, '#65 - Major Smart City Infrastructure Development Unveiled in Ahmedabad', '#65 - Ahmedabad માં મુખ્ય સ્માર્ટ સિટી ઈન્ફ્રાસ્ટ્રક્ચર વિકાસનું અનાવરણ', '#65 - Ahmedabad में प्रमुख स्मार्ट सिटी इंफ्रास्ट्रक्चर विकास का अनावरण', 'Latest updates on smart infrastructure and city development in Ahmedabad. Read complete report inside.', 'Ahmedabad માં Smart Infrastructure and City Development અંગેના વાયરલ અને તાજા સમાચાર.', 'Ahmedabad में Smart Infrastructure and City Development से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>The state government has announced a massive <strong>₹5,650 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Ahmedabad</strong>.</p><p>Officials confirmed that <strong>over 17,400 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Ahmedabad have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹5,650 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Ahmedabad</strong>.</p><p>Officials confirmed that <strong>over 17,400 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Ahmedabad have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹5,650 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Ahmedabad</strong>.</p><p>Officials confirmed that <strong>over 17,400 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Ahmedabad have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', 'https://images.unsplash.com/photo-1580582932707-520aed937b7b?w=800&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '65035c12-8c98-4acf-bddd-e061b2fc81dd', 'Ahmedabad, Gujarat', 4, 54, 1, 0, 0, 0, 'Major Smart City Infrastructure Development Unveiled in Ahmedabad | Gujarat Post', 'Latest updates on smart infrastructure and city development in Ahmedabad. Read complete report inside.', 'Ahmedabad, Gujarat news, Surat, latest updates', NULL, NULL, '2026-08-04 13:21:47', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('b72d59e7-5ec4-4e34-b7ef-975945017538', 'green-energy-initiative-set-to-power-100-of-bhavnagar-public-grid-1786108906625-25', 76, '#76 - Green Energy Initiative Set to Power 100% of Bhavnagar Public Grid', '#76 - હરિત ઊર્જા પહેલ Bhavnagar પબ્લિક ગ્રીડના 100% ને પાવર આપવા માટે તૈયાર', '#76 - हरित ऊर्जा पहल Bhavnagar पब्लिक ग्रिड को 100% बिजली देने के लिए तैयार', 'Latest updates on renewable energy and environment in Bhavnagar. Read complete report inside.', 'Bhavnagar માં Renewable Energy and Environment અંગેના વાયરલ અને તાજા સમાચાર.', 'Bhavnagar में Renewable Energy and Environment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>4,000 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>4,000 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>4,000 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', 'https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', 'f6650f9f-c367-4712-8ad1-18f599f12a53', 'Bhavnagar, Gujarat', 6, 89, 0, 0, 0, 1, 'Green Energy Initiative Set to Power 100% of Bhavnagar Public Grid | Gujarat Post', 'Latest updates on renewable energy and environment in Bhavnagar. Read complete report inside.', 'Bhavnagar, Gujarat news, Gold - Silver, latest updates', NULL, NULL, '2026-08-05 11:21:46', '2026-08-17 10:00:51');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('b7acc9da-20dd-4877-8450-d0346f786a55', 'panchayat-elections-dates-finalised-for-three-districts-96', 196, '#196 - Panchayat elections dates finalised for three districts - Full Ground Coverage', '#196 - ત્રણ જિલ્લાઓ માટે પંચાયત ચૂંટણીની તારીખ નક્કી', '#196 - तीन जिलों के लिए पंचायत चुनाव की तारीखें तय', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', '33c842e2-4efa-4b25-a12d-ac1a1fe1f561', NULL, 3, 25, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:39', '2026-08-14 11:11:58');
