INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('c6fa0c02-5650-4660-8a54-f9d8f7d9b54e', 'market-boom-business-investments-in-jamnagar-reach-record-high-1786108916172-89', 12, '#12 - Market Boom: Business Investments in Jamnagar Reach Record High', '#12 - માર્કેટ બૂમ: Jamnagar માં વ્યાપારી રોકાણ રેકોર્ડ સપાટીએ પહોંચ્યું', '#12 - मार्केट बूम: Jamnagar में व्यावसायिक निवेश रिकॉर्ड स्तर पर पहुंचा', 'Latest updates on business, finance and market trends in Jamnagar. Read complete report inside.', 'Jamnagar માં Business, Finance and Market Trends અંગેના વાયરલ અને તાજા સમાચાર.', 'Jamnagar में Business, Finance and Market Trends से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Foreign and domestic investments in <strong>Jamnagar</strong> surged to an all-time high of <strong>₹13,600 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 41,250 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Jamnagar</strong> surged to an all-time high of <strong>₹13,600 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 41,250 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Jamnagar</strong> surged to an all-time high of <strong>₹13,600 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 41,250 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', 'https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', '33c842e2-4efa-4b25-a12d-ac1a1fe1f561', 'Jamnagar, Gujarat', 6, 73, 0, 0, 0, 0, 'Market Boom: Business Investments in Jamnagar Reach Record High | Gujarat Post', 'Latest updates on business, finance and market trends in Jamnagar. Read complete report inside.', 'Jamnagar, Gujarat news, Politics, latest updates', NULL, NULL, '2026-07-31 03:21:56', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('c7207fc8-72c5-478a-beaa-b6a5e96d60d0', 'major-smart-city-infrastructure-development-unveiled-in-rajkot-1786108915605-84', 17, '#17 - Major Smart City Infrastructure Development Unveiled in Rajkot', '#17 - Rajkot માં મુખ્ય સ્માર્ટ સિટી ઈન્ફ્રાસ્ટ્રક્ચર વિકાસનું અનાવરણ', '#17 - Rajkot में प्रमुख स्मार्ट सिटी इंफ्रास्ट्रक्चर विकास का अनावरण', 'Latest updates on smart infrastructure and city development in Rajkot. Read complete report inside.', 'Rajkot માં Smart Infrastructure and City Development અંગેના વાયરલ અને તાજા સમાચાર.', 'Rajkot में Smart Infrastructure and City Development से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>The state government has announced a massive <strong>₹12,850 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Rajkot</strong>.</p><p>Officials confirmed that <strong>over 39,000 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Rajkot have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹12,850 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Rajkot</strong>.</p><p>Officials confirmed that <strong>over 39,000 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Rajkot have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹12,850 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Rajkot</strong>.</p><p>Officials confirmed that <strong>over 39,000 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Rajkot have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?w=800&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '04867180-ae79-4e17-a570-b6d4a944d6e3', 'Rajkot, Gujarat', 3, 81, 1, 1, 0, 1, 'Major Smart City Infrastructure Development Unveiled in Rajkot | Gujarat Post', 'Latest updates on smart infrastructure and city development in Rajkot. Read complete report inside.', 'Rajkot, Gujarat news, Photo Gallery, latest updates', NULL, NULL, '2026-07-31 13:21:55', '2026-08-17 10:00:52');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('c74fb506-a2b3-41f9-a330-41ad420147d8', 'gift-city-gandhinagar-sets-record-in-fintech-investments-111', 211, '#211 - Gift City Gandhinagar sets record in fintech investments - Full Ground Coverage', '#211 - ગિફ્ટ સિટી ગાંધીનગરે ફિનટેક રોકાણમાં રેકોર્ડ બનાવ્યો', '#211 - गिफ्ट सिटी गांधीनगर ने फिनटेक निवेश में रिकॉर्ड बनाया', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1524995997946-a1c2e315a42f?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', 'b7016886-3e6a-4452-a198-afcfa9e5663d', NULL, 3, 10, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:44', '2026-08-14 11:11:58');
