INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('cf026c36-60be-45f1-9c95-ac2465c02b11', 'fact-check-compulsory-4-day-work-week-in-india-misleading', 234, 'Fact Check: Mandatory 4-Day Work Week for All Private Companies in India is Misleading', 'ફેક્ટ ચેક: ખાનગી કંપનીઓમાં ફરજિયાત ૪ દિવસનું વર્ક વીક લાગુ થવા અંગેના સમાચાર ગેરમાર્ગે દોરનારા', 'फैक्ट चेक: निजी कंपनियों में अनिवार्य 4-दिवसीय कार्य सप्ताह लागू होने की खबर भ्रामक है', 'Reports claiming Central Labor Ministry made 4-day work week compulsory across India are misleading; Labour Codes offer flexible options, not mandates.', 'કેન્દ્ર સરકારે તમામ કંપનીઓ માટે સપ્તાહમાં ૪ દિવસ કામ ફરજિયાત બનાવ્યું હોવાના સમાચાર અડધી માહિતી અને ગેરમાર્ગે દોરનારા છે.', 'केंद्र सरकार ने सभी कंपनियों के लिए सप्ताह में 4 दिन का काम अनिवार्य कर दिया है, यह खबर भ्रामक है।', '<p><strong>Claim:</strong> News posts on social platforms state that the Union Labour Ministry has mandated a 4-day work week for all private and public sector employees starting next month.</p>\n<h2>Fact Check Analysis</h2>\n<p>Under the proposed Labour Codes framework, employers are given an option to implement flexible 48-hour working schedules over 4, 5, or 6 days, provided daily working hour limits and employee consent are met. It is not mandatory for companies to switch to 4 working days.</p>\n<ul>\n<li>The 48-hour total weekly work limit remains unchanged. A 4-day schedule requires 12 hours of work per day.</li>\n<li>Implementation depends entirely on individual company policies and state rules.</li>\n</ul>\n<blockquote>"Verdict: ⚠️ MISLEADING. Flexible option provided, but NOT mandatory for all firms."</blockquote>', '<p><strong>દાવો:</strong> આગામી મહિનાથી દેશની તમામ પ્રાઇવેટ અને સરકારી કંપનીઓમાં સપ્તાહમાં ફરજિયાત ૪ દિવસનું વર્ક વીક લાગુ થઈ રહ્યું હોવાનો દાવો વાયરલ થયો છે.</p>\n<h2>તપાસ અને તથ્ય</h2>\n<p>નવા લેબર કોડ પ્રોટોકોલ મુજબ કંપનીઓને અઠવાડિયામાં ૪૮ કલાકનું કામ ૪, ૫ કે ૬ દિવસમાં વહેંચવાની ફ્લેક્સિબલ મંજૂરી આપવામાં આવી છે. પરંતુ તમામ કંપનીઓ માટે ૪ દિવસ કામ ફરજિયાત કરવામાં આવ્યું નથી.</p>\n<ul>\n<li>અઠવાડિયાના કુલ ૪૮ કલાક કામનો નિયમ યથાવત છે, એટલે કે ૪ દિવસ વર્ક વીકમાં દૈનિક ૧૨ કલાક કામ કરવું પડે.</li>\n<li>આ ફેરફાર કંપનીઓની આંતરિક નીતિ અને કર્મચારીઓની સંમતિ પર આધારિત છે.</li>\n</ul>\n<blockquote>"ચુકાદો: ⚠️ અડધી માહિતી અને ગેરમાર્ગે દોરનારો દાવો."</blockquote>', '<p><strong>दावा:</strong> अगले महीने से सभी कंपनियों में 4 दिन का काम अनिवार्य होने वाला है।</p>\n<h2>सच्चाई</h2>\n<p>श्रम मंत्रालय ने केवल विकल्प दिया है, अनिवार्य नियम लागू नहीं किया है। कुल 48 घंटे का साप्ताहिक समय सीमा समान रहेगी।</p>\n<blockquote>"फैसला: ⚠️ भ्रामक जानकारी।"</blockquote>', 'https://images.unsplash.com/photo-1497215728101-856f4ea42174?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'b6423e89-dda8-489c-bd82-78e0fe179d65', NULL, 3, 82, 1, 0, 1, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:51:40', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('cf54c164-7c27-4ae9-8da2-6678fbf96aa6', 'sabarkantha-himatnagar-sabar-dairy-solar-milk-powder-unit', 267, 'Sabarkantha Himatnagar Sabar Dairy Solar Energy and Milk Powder Unit', 'સાબરકાંઠા હિંમતનગર સાબર ડેરી: નવો સોલાર અને મિલ્ક પાવડર પ્લાન્ટ લોન્ચ', 'साबरकांठा हिम्मतनगर साबर डेयरी: नया सौर और मिल्क पाउडर प्लांट लॉन्च', 'Sabar Dairy Himatnagar increases daily milk processing capacity to 35 lakh liters.', 'સાબરકાંઠા અને અરવલ્લી જિલ્લાના સાડા ત્રણ લાખ પશુપાલકોને સાબર ડેરીનો મોટો આર્થિક ટેકો.', 'साबरकांठा और अरावली जिलों के 3.5 लाख पशुपालकों को साबर डेयरी का बड़ा वित्तीय समर्थन।', '<p>ઉત્તર ગુજરાતની પ્રતિષ્ઠિત સાબર ડેરી હિંમતનગર ખાતે અત્યાધુનિક સોલાર એનર્જી સંચાલિત દૂધ પાવડર પ્લાન્ટનું લોકાર્પણ કરાયું છે. આ ટેકનોલોજીથી ડેરીની કામગીરી વધુ પર્યાવરણ અનુકૂળ અને કાર્યક્ષમ બની છે.</p>', '<p>ઉત્તર ગુજરાતની પ્રતિષ્ઠિત સાબર ડેરી હિંમતનગર ખાતે સોલાર સંચાલિત પ્લાન્ટનું લોકાર્પણ કરાયું છે.</p>', '<p>उत्तरी गुजरात की प्रतिष्ठित साबर डेयरी हिम्मतनगर में सौर संचालित प्लांट का उद्घाटन किया गया।</p>', 'https://images.unsplash.com/photo-1527153857715-3908f2bae5e8?w=1200&q=90', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '968c7b79-e486-4a36-8720-99f33c015339', 'Sabarkantha', 0, 0, 1, 0, 1, 15, NULL, NULL, NULL, NULL, NULL, '2026-08-12 06:12:35', '2026-08-19 04:51:12');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('cf5f7023-1dca-47bf-80ad-6df72f3ac140', 'major-smart-city-infrastructure-development-unveiled-in-ahmedabad-1786108913724-72', 29, '#29 - Major Smart City Infrastructure Development Unveiled in Ahmedabad', '#29 - Ahmedabad માં મુખ્ય સ્માર્ટ સિટી ઈન્ફ્રાસ્ટ્રક્ચર વિકાસનું અનાવરણ', '#29 - Ahmedabad में प्रमुख स्मार्ट सिटी इंफ्रास्ट्रक्चर विकास का अनावरण', 'Latest updates on smart infrastructure and city development in Ahmedabad. Read complete report inside.', 'Ahmedabad માં Smart Infrastructure and City Development અંગેના વાયરલ અને તાજા સમાચાર.', 'Ahmedabad में Smart Infrastructure and City Development से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>The state government has announced a massive <strong>₹11,050 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Ahmedabad</strong>.</p><p>Officials confirmed that <strong>over 33,600 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Ahmedabad have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹11,050 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Ahmedabad</strong>.</p><p>Officials confirmed that <strong>over 33,600 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Ahmedabad have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹11,050 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Ahmedabad</strong>.</p><p>Officials confirmed that <strong>over 33,600 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Ahmedabad have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', 'https://images.unsplash.com/photo-1567168544813-cc03465b4fa8?w=800&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '8ab79b8f-0ccd-4354-82c7-3ad84b99807c', 'Ahmedabad, Gujarat', 4, 96, 1, 0, 0, 2, 'Major Smart City Infrastructure Development Unveiled in Ahmedabad | Gujarat Post', 'Latest updates on smart infrastructure and city development in Ahmedabad. Read complete report inside.', 'Ahmedabad, Gujarat news, National, latest updates', NULL, NULL, '2026-08-01 13:21:53', '2026-08-19 01:11:48');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('cf6cdb6f-ac4d-4b40-a561-f9af395e0724', 'new-ai-tech-hub-opens-in-vadodara-to-foster-startup-ecosystem-1786108903020-2', 99, '#99 - New AI & Tech Hub Opens in Vadodara to Foster Startup Ecosystem', '#99 - Vadodara માં સ્ટાર્ટઅપ ઇકોસિસ્ટમને વેગ આપવા નવું AI અને ટેક હબ ખુલ્યું', '#99 - Vadodara में स्टार्टअप इकोसिस्टम को बढ़ावा देने के लिए नया AI और टेक हब खुला', 'Latest updates on tech & artificial intelligence revolution in Vadodara. Read complete report inside.', 'Vadodara માં Tech & Artificial Intelligence Revolution અંગેના વાયરલ અને તાજા સમાચાર.', 'Vadodara में Tech & Artificial Intelligence Revolution से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>In a major boost for the digital economy, a new <strong>₹550 crore AI Innovation Center</strong> was inaugurated in <strong>Vadodara</strong> today.</p><p>The hub features <strong>supercomputing facilities, cloud credits, and mentorship</strong> from global tech leaders. It is projected to incubate <strong>more than 2,100 tech startups</strong> by the end of 2027.</p><p>Industry experts stated that <strong>Gujarat\'s commitment to artificial intelligence and deep-tech innovation</strong> will position the state as a premier global technology destination.</p>', '<p>In a major boost for the digital economy, a new <strong>₹550 crore AI Innovation Center</strong> was inaugurated in <strong>Vadodara</strong> today.</p><p>The hub features <strong>supercomputing facilities, cloud credits, and mentorship</strong> from global tech leaders. It is projected to incubate <strong>more than 2,100 tech startups</strong> by the end of 2027.</p><p>Industry experts stated that <strong>Gujarat\'s commitment to artificial intelligence and deep-tech innovation</strong> will position the state as a premier global technology destination.</p>', '<p>In a major boost for the digital economy, a new <strong>₹550 crore AI Innovation Center</strong> was inaugurated in <strong>Vadodara</strong> today.</p><p>The hub features <strong>supercomputing facilities, cloud credits, and mentorship</strong> from global tech leaders. It is projected to incubate <strong>more than 2,100 tech startups</strong> by the end of 2027.</p><p>Industry experts stated that <strong>Gujarat\'s commitment to artificial intelligence and deep-tech innovation</strong> will position the state as a premier global technology destination.</p>', 'https://images.unsplash.com/photo-1540655037529-dec987208e23?w=800&q=80', 'PUBLISHED', NULL, '56a17220-190a-4e17-b56e-7c06101f37f8', '05acdc57-4700-4770-978b-c85f37e0f687', 'Vadodara, Gujarat', 4, 89, 0, 0, 0, 1, 'New AI & Tech Hub Opens in Vadodara to Foster Startup Ecosystem | Gujarat Post', 'Latest updates on tech & artificial intelligence revolution in Vadodara. Read complete report inside.', 'Vadodara, Gujarat news, Entertainment, latest updates', NULL, NULL, '2026-08-07 09:21:43', '2026-08-17 10:00:39');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('cfdf7ce7-ef02-440e-a668-4d9ab162ac28', 'warning-heavy-rain-alert-in-gujarat-for-next-three-days-120', 220, '#220 - Warning! Heavy rain alert in Gujarat for next three days - Full Ground Coverage', '#220 - સાવધાન! ગુજરાતમાં આગામી ત્રણ દિવસ ધોધમાર વરસાદની આગાહી', '#220 - सावधान! गुजरात में अगले तीन दिनों तक भारी बारिश की चेतावनी', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1599930113854-d6d7fd521f10?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', '9162cf30-4fba-40d8-a384-3583cdff56cf', NULL, 7, 1, 1, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:48', '2026-08-16 13:52:32');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('d04613bd-e3a4-4bd7-b846-6b077b9a747e', 'green-energy-initiative-set-to-power-100-of-bhavnagar-public-grid-1786108903587-7', 94, '#94 - Green Energy Initiative Set to Power 100% of Bhavnagar Public Grid', '#94 - હરિત ઊર્જા પહેલ Bhavnagar પબ્લિક ગ્રીડના 100% ને પાવર આપવા માટે તૈયાર', '#94 - हरित ऊर्जा पहल Bhavnagar पब्लिक ग्रिड को 100% बिजली देने के लिए तैयार', 'Latest updates on renewable energy and environment in Bhavnagar. Read complete report inside.', 'Bhavnagar માં Renewable Energy and Environment અંગેના વાયરલ અને તાજા સમાચાર.', 'Bhavnagar में Renewable Energy and Environment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>1,300 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>1,300 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Bhavnagar</strong> has reached its target capacity of <strong>1,300 Megawatts</strong> this week.</p><p>With this achievement, <strong>Bhavnagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', 'https://images.unsplash.com/photo-1587280501635-68a0e82cd5ff?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', '584e198e-0fab-4618-be66-5d120a9442a0', 'Bhavnagar, Gujarat', 5, 80, 0, 1, 0, 1, 'Green Energy Initiative Set to Power 100% of Bhavnagar Public Grid | Gujarat Post', 'Latest updates on renewable energy and environment in Bhavnagar. Read complete report inside.', 'Bhavnagar, Gujarat news, Lifestyle, latest updates', NULL, NULL, '2026-08-06 23:21:43', '2026-08-17 10:01:09');
