INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('d2140ee7-cb4f-413b-a739-f940ab282d32', 'new-health-guidelines-released-how-to-stay-fit-in-summer-2', 102, '#102 - New health guidelines released: how to stay fit in summer - Full Ground Coverage', '#102 - આરોગ્ય માટે નવી માર્ગદર્શિકા: ઉનાળામાં ફિટ રહેવા માટે શું કરવું', '#102 - स्वास्थ्य के लिए नए दिशा-निर्देश: गर्मियों में फिट रहने के लिए क्या करें', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1540910419892-4a36d2c3266c?w=800&q=80', 'PUBLISHED', NULL, '6e329fea-cd2d-4295-a98e-64bddfe20da6', '35257ba4-b50e-4557-a1d4-8d631725b5b1', NULL, 4, 119, 1, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:07', '2026-08-17 10:00:46');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('d2d5d0a2-549e-4cfa-a589-4b0b7e10303c', 'fact-check-traffic-helmet-fine-5000-direct-bank-debit-fake', 246, 'Fact Check: Claim of Rs 5000 Automatic Bank Debit for No-Helmet Traffic E-Challan is Misleading', 'ફેક્ટ ચેક: હેલ્મેટ વગર ડ્રાઇવિંગ કરવા બદલ ₹૫૦૦૦ દંડ બેંક ખાતામાંથી આપોઆપ કપાવાનો દાવો ખોટો', 'फैक्ट चेक: बिना हेलमेट गाड़ी चलाने पर ₹5000 का ऑटोमैटिक बैंक चालान कटने का दावा गलत है', 'Gujarat Traffic Police clarifies standard helmet fine remains Rs 500 and no automated direct bank account debit system exists.', 'ગુજરાત ટ્રાફિક પોલીસે સ્પષ્ટ કર્યું છે કે હેલ્મેટ વગર દંડ ₹૫૦૦ છે અને ખાતામાંથી સીધા પૈસા કાપવાનો કોઈ નિયમ નથી.', 'गुजरात ट्रैफिक पुलिस ने स्पष्ट किया कि बिना हेलमेट जुर्माना ₹500 है और बैंक से सीधे पैसे कटने का कोई नियम नहीं है।', '<p><strong>Claim:</strong> Social media posts state that new AI traffic cameras across Gujarat will automatically issue Rs 5000 e-challans directly debited from the vehicle owner\'s bank account for driving without a helmet.</p>\n<h2>Fact Check Analysis</h2>\n<p>State Traffic Police authorities clarified that while smart cameras detect traffic violations, helmet fines in Gujarat are set at Rs 500 under the Motor Vehicles Rules. Fines are never debited automatically from personal bank accounts.</p>\n<ul>\n<li>E-challans are sent via SMS or official digital traffic portals where payment is completed manually by the citizen.</li>\n<li>The viral posts exaggerate fine amounts and invent non-existent automated bank debit mechanisms.</li>\n</ul>\n<blockquote>"Verdict: ⚠️ MISLEADING. Helmet fine is Rs 500, no direct bank account debits."</blockquote>', '<p><strong>દાવો:</strong> સોશિયલ મીડિયા પર વાયરલ મેસેજમાં કહેવાયું છે કે ગુજરાતમાં નવા AI ટ્રાફિક કેમેરાથી હેલ્મેટ વગર ગાડી ચલાવવા બદલ ₹૫૦૦૦ નો દંડ સીધો બેંક એકાઉન્ટમાંથી ઓટોમેટિક કપાઈ જશે.</p>\n<h2>તપાસ અને તથ્ય</h2>\n<p>રાજ્ય ટ્રાફિક પોલીસ વિભાગે સ્પષ્ટતા કરી છે કે ગુજરાતમાં મોટર વ્હીકલ એક્ટ હેઠળ હેલ્મેટ ન પહેરવાનો નિયમિત દંડ ₹૫૦૦ જ છે. કોઈપણ બેંક ખાતામાંથી સીધો દંડ કાપવાની સિસ્ટમ અસ્તિત્વમાં નથી.</p>\n<ul>\n<li>ઈ-ચલાન એસએમએસ અથવા સત્તાવાર <strong>echallan.gujarat.gov.in</strong> પોર્ટલ પર જ જનરેટ થાય છે જેનું નાગરિકે પોતે ચુકવણું કરવાનું હોય છે.</li>\n<li>આ દાવો લોકોને ડરાવવા માટે વધારી-ચઢાવીને વાયરલ કરાયો છે.</li>\n</ul>\n<blockquote>"ચુકાદો: ⚠️ ભ્રામક દાવો. હેલ્મેટ દંડ ₹૫૦૦ છે, ખાતામાંથી સીધા પૈસા કપાતા નથી."</blockquote>', '<p><strong>दावा:</strong> बिना हेलमेट चालान कटने पर बैंक खाते से ₹5000 सीधे कट जाएंगे।</p>\n<h2>सच्चाई</h2>\n<p>गुजरात पुलिस के अनुसार जुर्माना ₹500 है और बैंक से ऑटोमैटिक पैसे कटने की कोई व्यवस्था नहीं है।</p>\n<blockquote>"फैसला: ⚠️ भ्रामक सूचना।"</blockquote>', 'https://images.unsplash.com/photo-1558981806-ec527fa84c39?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'b6423e89-dda8-489c-bd82-78e0fe179d65', NULL, 3, 84, 0, 0, 1, 3, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:51:55', '2026-08-17 10:01:11');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('d3b62465-bb16-43ec-b381-20bab3b28c42', 'new-health-guidelines-released-how-to-stay-fit-in-summer-74', 174, '#174 - New health guidelines released: how to stay fit in summer - Full Ground Coverage', '#174 - આરોગ્ય માટે નવી માર્ગદર્શિકા: ઉનાળામાં ફિટ રહેવા માટે શું કરવું', '#174 - स्वास्थ्य के लिए नए दिशा-निर्देश: गर्मियों में फिट रहने के लिए क्या करें', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '35257ba4-b50e-4557-a1d4-8d631725b5b1', NULL, 6, 47, 0, 0, 0, 2, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:30', '2026-08-17 10:00:47');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('d41800b7-b994-4d33-babe-97dc88884eaf', 'bhavnagar-athletes-win-big-at-national-championship-event-1786108905135-16', 85, '#85 - Bhavnagar Athletes Win Big at National Championship Event', '#85 - રાષ્ટ્રીય ચેમ્પિયનશિપ ઇવેન્ટમાં Bhavnagar ના ખેલાડીઓની ભવ્ય જીત', '#85 - राष्ट्रीय चैंपियनशिप प्रतियोगिता में Bhavnagar के एथलीटों ने बड़ी जीत हासिल की', 'Latest updates on sports excellence and youth empowerment in Bhavnagar. Read complete report inside.', 'Bhavnagar માં Sports Excellence and Youth Empowerment અંગેના વાયરલ અને તાજા સમાચાર.', 'Bhavnagar में Sports Excellence and Youth Empowerment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Athletes from <strong>Bhavnagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>2,650 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹8,400 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Bhavnagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>2,650 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹8,400 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Bhavnagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>2,650 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹8,400 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '8ab79b8f-0ccd-4354-82c7-3ad84b99807c', 'Bhavnagar, Gujarat', 6, 75, 0, 0, 0, 0, 'Bhavnagar Athletes Win Big at National Championship Event | Gujarat Post', 'Latest updates on sports excellence and youth empowerment in Bhavnagar. Read complete report inside.', 'Bhavnagar, Gujarat news, National, latest updates', NULL, NULL, '2026-08-06 05:21:45', '2026-08-14 11:11:58');
