INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('db0c504f-bc7a-4f7d-b907-c343871669a2', 'social-media-influencers-share-local-stories-from-gujarat-4', 104, '#104 - Social media influencers share local stories from Gujarat - Full Ground Coverage', '#104 - સોશિયલ મીડિયા ઇન્ફ્લુએન્સર્સે ગુજરાતની કથાઓ શેર કરી', '#104 - सोशल मीडिया इन्फ्लुएंसर्स ने गुजरात की कहानियां साझा की', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1514525253161-7a46d19cd819?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', 'e4f6985f-03b9-48b6-9ec1-8283410a92c4', NULL, 6, 117, 1, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:08', '2026-08-17 10:00:39');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('dc39d3e5-4a9c-48f5-aaf9-e7244c6eed77', 'ahmedabad-jaherman-8-jetla-humlakhoroe-ek-yuvanni-kri-ht-ya-tlvaro-ane-chhrina-gha-marine-antrdun-bhar-kadhi-nakh-yun', 276, 'અમદાવાદમાં જાહેરમાં 8 જેટલા હુમલાખોરોએ એક યુવાનની કરી હત્યા, તલવારો અને છરીના ઘા મારીને આંતરડું બહાર કાઢી નાખ્યું', 'અમદાવાદમાં જાહેરમાં 8 જેટલા હુમલાખોરોએ એક યુવાનની કરી હત્યા, તલવારો અને છરીના ઘા મારીને આંતરડું બહાર કાઢી નાખ્યું', 'અમદાવાદમાં જાહેરમાં 8 જેટલા હુમલાખોરોએ એક યુવાનની કરી હત્યા, તલવારો અને છરીના ઘા મારીને આંતરડું બહાર કાઢી નાખ્યું', 'Gujarat Post news flash.', 'Gujarat Post news flash.', 'Gujarat Post news flash.', '## 📌 AT A GLANCE (KEY HIGHLIGHTS)\n--------------------------------------------------\nઅમદાવાદમાં યુવકની જાહેરમાં હત્યા, 8 જેટલા શખ્સો ટેમ્પોમાં આવ્યાં અને કરી નાખી હત્યા\n--------------------------------------------------\n\nપોલીસે આરોપીઓની શોધખોળ શરૂ કરી, રાણીપની સનસનીખેજ ઘટના\n--------------------------------------------------\n\n<strong>અમદાવાદઃ </strong>રાણીપ વિસ્તારમાં રાત્રે બનેલી એક સનસનાટીભરી \nહત્યાએ શહેરની સુરક્ષા વ્યવસ્થા પર સવાલો ઉભા કર્યા છે. સેન્ટ્રલ જેલ તરફ \nજતા રસ્તા પર 7&nbsp;થી 8&nbsp;હુમલાખોરોએ 37 વર્ષીય રણછોડ ઉર્ફે અજય સાલ્વીને ઘેરીને\n તેના પર હુમલો કર્યો હતો. હુમલાખોરોએ છરીઓ, તલવારો અને લાકડીઓનો ઉપયોગ \nકર્યો હતો. હુમલામાં અજય ગંભીર રીતે ઘાયલ થયો હતો અને બાદમાં હોસ્પિટલમાં \nતેનું મોત થઇ ગયું હતુ.\n\n![Gallery Image 2](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786888675/gujarat-post/Logo_1786888673971_2461_mfvryj.png)\n\n![Gallery Image 3](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786888692/gujarat-post/ips_tr_1786888691227_1884_itowpa.jpg)\n\n> "અમદાવાદમાં સનસનીખેજ હત્યાથી હડકંપ મચી ગયો છે, તપાસ ચાલુ છે"\n> — રાણીપ પોલીસનો ખુલાસો', '## 📌 એક નજરમાં (KEY HIGHLIGHTS)\n--------------------------------------------------\nઅમદાવાદમાં યુવકની જાહેરમાં હત્યા, 8 જેટલા શખ્સો ટેમ્પોમાં આવ્યાં અને કરી નાખી હત્યા\n--------------------------------------------------\n\nપોલીસે આરોપીઓની શોધખોળ શરૂ કરી, રાણીપની સનસનીખેજ ઘટના\n--------------------------------------------------\n\n<strong>અમદાવાદઃ </strong>રાણીપ વિસ્તારમાં રાત્રે બનેલી એક સનસનાટીભરી \nહત્યાએ શહેરની સુરક્ષા વ્યવસ્થા પર સવાલો ઉભા કર્યા છે. સેન્ટ્રલ જેલ તરફ \nજતા રસ્તા પર 7&nbsp;થી 8&nbsp;હુમલાખોરોએ 37 વર્ષીય રણછોડ ઉર્ફે અજય સાલ્વીને ઘેરીને\n તેના પર હુમલો કર્યો હતો. હુમલાખોરોએ છરીઓ, તલવારો અને લાકડીઓનો ઉપયોગ \nકર્યો હતો. હુમલામાં અજય ગંભીર રીતે ઘાયલ થયો હતો અને બાદમાં હોસ્પિટલમાં \nતેનું મોત થઇ ગયું હતુ.\n\n![Gallery Image 2](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786888675/gujarat-post/Logo_1786888673971_2461_mfvryj.png)\n\n![Gallery Image 3](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786888692/gujarat-post/ips_tr_1786888691227_1884_itowpa.jpg)\n\n> "અમદાવાદમાં સનસનીખેજ હત્યાથી હડકંપ મચી ગયો છે, તપાસ ચાલુ છે"\n> — રાણીપ પોલીસનો ખુલાસો\n\n<p><strong>અમદાવાદઃ </strong>રાણીપ વિસ્તારમાં રાત્રે બનેલી એક સનસનાટીભરી\n હત્યાએ શહેરની સુરક્ષા વ્યવસ્થા પર સવાલો ઉભા કર્યા છે. સેન્ટ્રલ જેલ તરફ \nજતા રસ્તા પર 7&nbsp;થી 8&nbsp;હુમલાખોરોએ 37 વર્ષીય રણછોડ ઉર્ફે અજય સાલ્વીને ઘેરીને\n તેના પર હુમલો કર્યો હતો. હુમલાખોરોએ છરીઓ, તલવારો અને લાકડીઓનો ઉપયોગ \nકર્યો હતો. હુમલામાં અજય ગંભીર રીતે ઘાયલ થયો હતો અને બાદમાં હોસ્પિટલમાં \nતેનું મોત થઇ ગયું હતુ.<br type="_moz"></p><p><span style="background-color: rgb(255, 0, 0);">મૃતકના મામાના દીકરા ભરત \nસાલ્વીએ રાણીપ પોલીસ સ્ટેશનમાં FIR નોંધાવી છે. ભરતના જણાવ્યાં અનુસાર, તે \nઅને રણછોડ ઉર્ફે અજય મધ્ય જેલ તરફ જતા રસ્તા પર લગભગ 2 વાગ્યા હતા, ત્યારે \nસુભાષ બ્રિજ પરથી રાજસ્થાન નોંધણી નંબરવાળી મહિન્દ્રા પિકઅપ આવી. વિશાલ \nચૌહાણ અને અંકિત પરમાર સહિત લગભગ 7 થી 8 લોકો હથિયારોથી સજ્જ વાહનમાંથી \nબહાર નીકળ્યાં હતા.</span><br type="_moz"></p><p>હુમલાખોરોને જોઈને અજયે ભરતને \nભાગી જવા કહ્યું હતુ. એવો આરોપ છે કે વિશાલ ચૌહાણ અને તેના સાથીઓએ અજયને \nપકડી લીધો અને તેના પર બેરહેમીથી હુમલો કરવાનું શરૂ કર્યું. અજય મદદ માટે \nબૂમો પાડતો જમીન પર પડી ગયો. ગુનો કર્યા પછી, આરોપી ભાગી ગયો. અજયને લગભગ \n15 ગંભીર ઘા મારવાથી તેનું આંતરડું પણ બહાર આવી ગયું હતું.</p><p><font color="#00ff40">ભરતે રવિ \nસાલ્વીને ફોન પર ઘટનાની જાણ કરી હતી. ત્યાર બાદ ઘાયલ અજયને એમ્બ્યુલન્સ \nદ્વારા હોસ્પિટલમાં લઈ જવામાં આવ્યો હતો. જો કે, ત્યાંના ડોક્ટરોએ તપાસ બાદ\n તેને મૃત જાહેર કર્યો હતો. પોલીસ હવે ઘટના સ્થળ અને આસપાસના વિસ્તારોના \nસીસીટીવી ફૂટેજની તપાસ કરી રહી છે જેથી સંડોવાયેલા લોકોની ઓળખ કરી શકાય અને\n તેમની પ્રવૃત્તિઓ શોધી શકાય.</font></p><p>પરિવારે હત્યા પાછળ જૂની દુશ્મનાવટનો \nઉલ્લેખ કર્યો છે. ભરત સાલ્વીના જણાવ્યાં મુજબ, અજયનો લગભગ 10 દિવસ પહેલા \nભદ્રેશ શર્મા સાથે વિવાદ થયો હતો. આ વિવાદ બાદ, ભદ્રેશના સાળા, સાગર ઉર્ફે \nમાફિયા પરમાર અને અંકિત પરમારએ ફોન પર અજયને જાનથી મારી નાખવાની ધમકી આપી \nહતી. પરિવારનો આરોપ છે કે આ દુશ્મનાવટને કારણે અજયને નિશાન બનાવવામાં આવ્યો\n હતો.</p><p>પ્રાથમિક પોલીસ તપાસમાં અજય અને આરોપી વચ્ચે લાંબા સમયથી ચાલતો\n વિવાદ બહાર આવ્યો છે. પોલીસના જણાવ્યાં&nbsp;અનુસાર, ભદ્રેશ શર્મા સાથે થોડા \nસમય પહેલા મદ્રાસી ચાલીમાં ઝઘડો થયો હતો. અજયે દરમિયાનગીરી કરી અને \nભદ્રેશને થપ્પડ મારી દીધી હતી. ત્યાર બાદ, ભદ્રેશના સાળા, સાગર ઉર્ફે \nમાફિયાએ અજયને ધમકી આપી હતી.&nbsp;&nbsp;</p><p>રાણીપ પોલીસે ભારતીય દંડ સંહિતા (IPC)\n ની કલમ 103(1), 189(2), 189(4), 190, 191(2), 61(2), 54 અને 3(5) હેઠળ કેસ\n નોંધ્યો છે. સંડોવાયેલા તમામ આરોપીઓની શોધ ચાલી રહી છે. ઘટનાસ્થળ અને \nઆસપાસના વિસ્તારોના CCTV ફૂટેજની પણ તપાસ કરવામાં આવી રહી છે.</p><p>પરિવારે\n દાવો કર્યો છે કે વિશાલ ચૌહાણ સહિત સાતથી 8&nbsp;લોકોએ સાગર ઉર્ફે માફિયા પરમાર\n અને અંકિત પરમારના કહેવાથી અજયની હત્યા કરી હતી.&nbsp;હાલમાં, પોલીસ ફરાર \nઆરોપીઓને પકડવા માટે ચક્રો ગતિમાન કર્યા છે.</p><p>હત્યાની આ ઘટના બાદ \nરાણીપ વિસ્તારમાં આતંકનો માહોલ છવાઈ ગયો છે. ધોળા દિવસે થયેલી આ હત્યાએ ફરી\n એકવાર શહેરમાં કાયદો અને વ્યવસ્થા અને રાત્રિ સુરક્ષા પર ગંભીર પ્રશ્નો \nઉભા કર્યા છે.&nbsp;</p>', '## 📌 एक नजर में (KEY HIGHLIGHTS)\n--------------------------------------------------\nઅમદાવાદમાં યુવકની જાહેરમાં હત્યા, 8 જેટલા શખ્સો ટેમ્પોમાં આવ્યાં અને કરી નાખી હત્યા\n--------------------------------------------------\n\nપોલીસે આરોપીઓની શોધખોળ શરૂ કરી, રાણીપની સનસનીખેજ ઘટના\n--------------------------------------------------\n\n<strong>અમદાવાદઃ </strong>રાણીપ વિસ્તારમાં રાત્રે બનેલી એક સનસનાટીભરી \nહત્યાએ શહેરની સુરક્ષા વ્યવસ્થા પર સવાલો ઉભા કર્યા છે. સેન્ટ્રલ જેલ તરફ \nજતા રસ્તા પર 7&nbsp;થી 8&nbsp;હુમલાખોરોએ 37 વર્ષીય રણછોડ ઉર્ફે અજય સાલ્વીને ઘેરીને\n તેના પર હુમલો કર્યો હતો. હુમલાખોરોએ છરીઓ, તલવારો અને લાકડીઓનો ઉપયોગ \nકર્યો હતો. હુમલામાં અજય ગંભીર રીતે ઘાયલ થયો હતો અને બાદમાં હોસ્પિટલમાં \nતેનું મોત થઇ ગયું હતુ.\n\n![Gallery Image 2](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786888675/gujarat-post/Logo_1786888673971_2461_mfvryj.png)\n\n![Gallery Image 3](https://res.cloudinary.com/dvcffkyjz/image/upload/v1786888692/gujarat-post/ips_tr_1786888691227_1884_itowpa.jpg)\n\n> "અમદાવાદમાં સનસનીખેજ હત્યાથી હડકંપ મચી ગયો છે, તપાસ ચાલુ છે"\n> — રાણીપ પોલીસનો ખુલાસો', 'https://res.cloudinary.com/dvcffkyjz/image/upload/v1786888596/gujarat-post/Young_man_murdered_by_7_8_attackers_in_the_middle_of_the_street_in_Ahmedabad_gujaratpost_news_1786888595137_5430_gxmzxa.jpg', 'PUBLISHED', NULL, '56a17220-190a-4e17-b56e-7c06101f37f8', '9162cf30-4fba-40d8-a384-3583cdff56cf', 'Ahmedabad', 3, 0, 1, 1, 0, 9, 'Young man murdered by 7-8 attackers in the middle of the street in Ahmedabad gujaratpost news', 'Young man murdered by 7-8 attackers in the middle of the street in Ahmedabad gujaratpost news', 'Young man murdered,', '', 'index, follow', '2026-08-16 14:03:24', '2026-08-19 04:52:03');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('dc543a2b-f869-47da-8b70-6aa7d1c4b021', 'cm-holds-review-meeting-for-development-projects-56', 156, '#156 - CM holds review meeting for development projects - Full Ground Coverage', '#156 - CM એ વિકાસ પ્રોજેક્ટ માટે સમીક્ષા બેઠક યોજી', '#156 - CM ने विकास परियोजनाओं के लिए समीक्षा बैठक की', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1605649487212-47bdab064df7?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', '33c842e2-4efa-4b25-a12d-ac1a1fe1f561', NULL, 3, 65, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:24', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('dd65aad5-c942-4e6f-9a4d-e0cd86c8e2af', 'market-boom-business-investments-in-gujarat-reach-record-high-1786108905889-23', 78, '#78 - Market Boom: Business Investments in Gujarat Reach Record High', '#78 - માર્કેટ બૂમ: Gujarat માં વ્યાપારી રોકાણ રેકોર્ડ સપાટીએ પહોંચ્યું', '#78 - मार्केट बूम: Gujarat में व्यावसायिक निवेश रिकॉर्ड स्तर पर पहुंचा', 'Latest updates on business, finance and market trends in Gujarat. Read complete report inside.', 'Gujarat માં Business, Finance and Market Trends અંગેના વાયરલ અને તાજા સમાચાર.', 'Gujarat में Business, Finance and Market Trends से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Foreign and domestic investments in <strong>Gujarat</strong> surged to an all-time high of <strong>₹3,700 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 11,550 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Gujarat</strong> surged to an all-time high of <strong>₹3,700 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 11,550 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Gujarat</strong> surged to an all-time high of <strong>₹3,700 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 11,550 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', 'https://images.unsplash.com/photo-1444653614773-995cb1ef9efa?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', 'dd4e83fd-25c8-47fe-ae69-dc6f7123f6be', 'Gujarat, Gujarat', 4, 66, 0, 0, 0, 1, 'Market Boom: Business Investments in Gujarat Reach Record High | Gujarat Post', 'Latest updates on business, finance and market trends in Gujarat. Read complete report inside.', 'Gujarat, Gujarat news, Gujarat Election 2027, latest updates', NULL, NULL, '2026-08-05 15:21:45', '2026-08-17 10:00:50');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('de03b829-b056-4ce3-aee6-618bca745d27', 'green-energy-initiative-set-to-power-100-of-gandhinagar-public-grid-1786108913086-67', 34, '#34 - Green Energy Initiative Set to Power 100% of Gandhinagar Public Grid', '#34 - હરિત ઊર્જા પહેલ Gandhinagar પબ્લિક ગ્રીડના 100% ને પાવર આપવા માટે તૈયાર', '#34 - हरित ऊर्जा पहल Gandhinagar पब्लिक ग्रिड को 100% बिजली देने के लिए तैयार', 'Latest updates on renewable energy and environment in Gandhinagar. Read complete report inside.', 'Gandhinagar માં Renewable Energy and Environment અંગેના વાયરલ અને તાજા સમાચાર.', 'Gandhinagar में Renewable Energy and Environment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A breakthrough solar and wind hybrid power project in <strong>Gandhinagar</strong> has reached its target capacity of <strong>10,300 Megawatts</strong> this week.</p><p>With this achievement, <strong>Gandhinagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Gandhinagar</strong> has reached its target capacity of <strong>10,300 Megawatts</strong> this week.</p><p>With this achievement, <strong>Gandhinagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Gandhinagar</strong> has reached its target capacity of <strong>10,300 Megawatts</strong> this week.</p><p>With this achievement, <strong>Gandhinagar becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', 'https://images.unsplash.com/photo-1624365168968-f283d506c6b6?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', '6a24df1e-8b62-40d8-8dfb-ba8c12f60983', 'Gandhinagar, Gujarat', 6, 90, 0, 0, 0, 0, 'Green Energy Initiative Set to Power 100% of Gandhinagar Public Grid | Gujarat Post', 'Latest updates on renewable energy and environment in Gandhinagar. Read complete report inside.', 'Gandhinagar, Gujarat news, Web Stories, latest updates', NULL, NULL, '2026-08-01 23:21:53', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('de03d0b1-c0be-4f67-ad2a-45d2d8da27a6', 'major-smart-city-infrastructure-development-unveiled-in-kutch-1786108906504-24', 77, '#77 - Major Smart City Infrastructure Development Unveiled in Kutch', '#77 - Kutch માં મુખ્ય સ્માર્ટ સિટી ઈન્ફ્રાસ્ટ્રક્ચર વિકાસનું અનાવરણ', '#77 - Kutch में प्रमुख स्मार्ट सिटी इंफ्रास्ट्रक्चर विकास का अनावरण', 'Latest updates on smart infrastructure and city development in Kutch. Read complete report inside.', 'Kutch માં Smart Infrastructure and City Development અંગેના વાયરલ અને તાજા સમાચાર.', 'Kutch में Smart Infrastructure and City Development से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>The state government has announced a massive <strong>₹3,850 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Kutch</strong>.</p><p>Officials confirmed that <strong>over 12,000 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Kutch have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹3,850 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Kutch</strong>.</p><p>Officials confirmed that <strong>over 12,000 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Kutch have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', '<p>The state government has announced a massive <strong>₹3,850 crore development fund</strong> aimed at upgrading transit, smart water networks, and green parks across <strong>Kutch</strong>.</p><p>Officials confirmed that <strong>over 12,000 direct jobs</strong> will be created during the execution phase. Speaking at the ceremony, project leads highlighted that <strong>modern urban living relies on intelligent automation and sustainable design</strong>.</p><p>Citizens of Kutch have welcomed the move, noting that <strong>improved connectivity and public safety features</strong> will transform the urban landscape over the next two years.</p>', 'https://images.unsplash.com/photo-1520607162513-77705c0f0d4a?w=800&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'e4f6985f-03b9-48b6-9ec1-8283410a92c4', 'Kutch, Gujarat', 5, 69, 1, 0, 0, 0, 'Major Smart City Infrastructure Development Unveiled in Kutch | Gujarat Post', 'Latest updates on smart infrastructure and city development in Kutch. Read complete report inside.', 'Kutch, Gujarat news, Instagram, latest updates', NULL, NULL, '2026-08-05 13:21:46', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('e0441b36-280f-4645-be96-e2672193ca73', 'new-ai-tech-hub-opens-in-jamnagar-to-foster-startup-ecosystem-1786108911925-62', 39, '#39 - New AI & Tech Hub Opens in Jamnagar to Foster Startup Ecosystem', '#39 - Jamnagar માં સ્ટાર્ટઅપ ઇકોસિસ્ટમને વેગ આપવા નવું AI અને ટેક હબ ખુલ્યું', '#39 - Jamnagar में स्टार्टअप इकोसिस्टम को बढ़ावा देने के लिए नया AI और टेक हब खुला', 'Latest updates on tech & artificial intelligence revolution in Jamnagar. Read complete report inside.', 'Jamnagar માં Tech & Artificial Intelligence Revolution અંગેના વાયરલ અને તાજા સમાચાર.', 'Jamnagar में Tech & Artificial Intelligence Revolution से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>In a major boost for the digital economy, a new <strong>₹9,550 crore AI Innovation Center</strong> was inaugurated in <strong>Jamnagar</strong> today.</p><p>The hub features <strong>supercomputing facilities, cloud credits, and mentorship</strong> from global tech leaders. It is projected to incubate <strong>more than 29,100 tech startups</strong> by the end of 2027.</p><p>Industry experts stated that <strong>Gujarat\'s commitment to artificial intelligence and deep-tech innovation</strong> will position the state as a premier global technology destination.</p>', '<p>In a major boost for the digital economy, a new <strong>₹9,550 crore AI Innovation Center</strong> was inaugurated in <strong>Jamnagar</strong> today.</p><p>The hub features <strong>supercomputing facilities, cloud credits, and mentorship</strong> from global tech leaders. It is projected to incubate <strong>more than 29,100 tech startups</strong> by the end of 2027.</p><p>Industry experts stated that <strong>Gujarat\'s commitment to artificial intelligence and deep-tech innovation</strong> will position the state as a premier global technology destination.</p>', '<p>In a major boost for the digital economy, a new <strong>₹9,550 crore AI Innovation Center</strong> was inaugurated in <strong>Jamnagar</strong> today.</p><p>The hub features <strong>supercomputing facilities, cloud credits, and mentorship</strong> from global tech leaders. It is projected to incubate <strong>more than 29,100 tech startups</strong> by the end of 2027.</p><p>Industry experts stated that <strong>Gujarat\'s commitment to artificial intelligence and deep-tech innovation</strong> will position the state as a premier global technology destination.</p>', 'https://images.unsplash.com/photo-1504711434969-e33886168f5c?w=800&q=80', 'PUBLISHED', NULL, '56a17220-190a-4e17-b56e-7c06101f37f8', '35257ba4-b50e-4557-a1d4-8d631725b5b1', 'Jamnagar, Gujarat', 6, 50, 0, 0, 0, 0, 'New AI & Tech Hub Opens in Jamnagar to Foster Startup Ecosystem | Gujarat Post', 'Latest updates on tech & artificial intelligence revolution in Jamnagar. Read complete report inside.', 'Jamnagar, Gujarat news, Health, latest updates', NULL, NULL, '2026-08-02 09:21:51', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('e08f6948-081f-4433-a486-69a66825dec2', 'market-boom-business-investments-in-gujarat-reach-record-high-1786108908957-41', 60, '#60 - Market Boom: Business Investments in Gujarat Reach Record High', '#60 - માર્કેટ બૂમ: Gujarat માં વ્યાપારી રોકાણ રેકોર્ડ સપાટીએ પહોંચ્યું', '#60 - मार्केट बूम: Gujarat में व्यावसायिक निवेश रिकॉर्ड स्तर पर पहुंचा', 'Latest updates on business, finance and market trends in Gujarat. Read complete report inside.', 'Gujarat માં Business, Finance and Market Trends અંગેના વાયરલ અને તાજા સમાચાર.', 'Gujarat में Business, Finance and Market Trends से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Foreign and domestic investments in <strong>Gujarat</strong> surged to an all-time high of <strong>₹6,400 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 19,650 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Gujarat</strong> surged to an all-time high of <strong>₹6,400 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 19,650 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Gujarat</strong> surged to an all-time high of <strong>₹6,400 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 19,650 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', 'https://images.unsplash.com/photo-1508739773434-c26b3d09e071?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', '6f23d06f-50b3-4d6b-9834-42d7133b08a8', 'Gujarat, Gujarat', 3, 91, 0, 0, 0, 0, 'Market Boom: Business Investments in Gujarat Reach Record High | Gujarat Post', 'Latest updates on business, finance and market trends in Gujarat. Read complete report inside.', 'Gujarat, Gujarat news, Vadodara, latest updates', NULL, NULL, '2026-08-04 03:21:48', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('e109d368-26ee-4448-9ade-a68a66de1a61', 'fact-check-5-year-education-loan-moratorium-forged-circular', 245, 'Fact Check: Ministry of Education Clarifies Forged Circular on 5-Year Student Loan Moratorium', 'ફેક્ટ ચેક: એજ્યુકેશન લોન પર ૫ વર્ષ સુધી વ્યાજ માફી અને ઇએમઆઈ વિલંબ અંગેનો વાયરલ પરિપત્ર નકલી', 'फैक्ट चेक: एजुकेशन लोन पर 5 साल के लिए ईएमआई छूट का वायरल सर्कुलर फर्जी है', 'PIB Fact Check confirms circular promising 5-year repayment moratorium and complete interest waiver for student loans is forged.', 'પીઆઈબી ફેક્ટ ચેકે પુષ્ટિ કરી છે કે શિક્ષણ મંત્રાલયના નામે વાયરલ થયેલો એજ્યુકેશન લોન વ્યાજ માફીનો પત્ર બોગસ છે.', 'पीआईबी फैक्ट चेक ने पुष्टि की है कि शिक्षा मंत्रालय के नाम से वायरल स्टूडेंट लोन माफी का पत्र फर्जी है।', '<p><strong>Claim:</strong> A circular carrying Union Ministry of Education letterhead states that all student education loans will receive an automatic 5-year repayment moratorium with 100% interest waiver.</p>\n<h2>Fact Check Analysis</h2>\n<p>PIB Fact Check and Higher Education Ministry officials confirmed the letterhead is counterfeit. Existing education loan subsidy schemes (like CSIS) continue under standard guidelines without broad 5-year blanket waivers.</p>\n<ul>\n<li>Students should verify educational financial aid only via official portals like <strong>vidyalakshmi.co.in</strong>.</li>\n<li>Forged documents are frequently used by fraudulent agents offering false loan settlement promises.</li>\n</ul>\n<blockquote>"Verdict: 📄 FORGED DOCUMENT. No 5-year universal loan waiver issued."</blockquote>', '<p><strong>દાવો:</strong> શિક્ષણ મંત્રાલયના બોગસ સહી-સિક્કા વાળો એક પરિપત્ર વાયરલ થયો છે જેમાં લખ્યું છે કે તમામ વિદ્યાર્થીઓની એજ્યુકેશન લોનના હપ્તા ૫ વર્ષ માટે સ્થગિત કરી વ્યાજ ૧૦૦% માફ કરવામાં આવ્યું છે.</p>\n<h2>તપાસ અને તથ્ય</h2>\n<p>પીઆઈબી ફેક્ટ ચેક અને શિક્ષણ મંત્રાલયે આ પત્રને બનાવટી અને નકલી જાહેર કર્યો છે. સરકારી યોજનાઓ હેઠળ મળતી સામાન્ય વ્યાજ સબસીડી સિવાય આવી કોઈ ૫ વર્ષની સામૂહિક માફી જાહેર કરાઈ નથી.</p>\n<ul>\n<li>વિદ્યાર્થીઓએ શૈક્ષણિક લોન અંગેની માહિતી માત્ર સત્તાવાર <strong>vidyalakshmi.co.in</strong> પોર્ટલ પરથી લેવી.</li>\n<li>આવા બોગસ પરિપત્રો બનાવીને એજન્ટો વિદ્યાર્થીઓ પાસે પૈસા પડાવવાનો પ્રયાસ કરે છે.</li>\n</ul>\n<blockquote>"ચુકાદો: 📄 બનાવટી અને નકલી પરિપત્ર."</blockquote>', '<p><strong>दावा:</strong> एजुकेशन लोन का भुगतान 5 साल तक टाल दिया गया है और ब्याज माफ हो गया है।</p>\n<h2>सच्चाई</h2>\n<p>शिक्षा मंत्रालय ने इस पत्र को पूरी तरह से फर्जी करार दिया है।</p>\n<blockquote>"फैसला: 📄 जाली दस्तावेज।"</blockquote>', 'https://images.unsplash.com/photo-1523240795612-9a054b0db644?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'b6423e89-dda8-489c-bd82-78e0fe179d65', NULL, 3, 87, 0, 0, 1, 1, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:51:53', '2026-08-16 13:52:50');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('e2ee820a-8ce9-4b3b-8fc8-c1f41865e2cf', 'gandhinagar-athletes-win-big-at-national-championship-event-1786108903243-4', 97, '#97 - Gandhinagar Athletes Win Big at National Championship Event', '#97 - રાષ્ટ્રીય ચેમ્પિયનશિપ ઇવેન્ટમાં Gandhinagar ના ખેલાડીઓની ભવ્ય જીત', '#97 - राष्ट्रीय चैंपियनशिप प्रतियोगिता में Gandhinagar के एथलीटों ने बड़ी जीत हासिल की', 'Latest updates on sports excellence and youth empowerment in Gandhinagar. Read complete report inside.', 'Gandhinagar માં Sports Excellence and Youth Empowerment અંગેના વાયરલ અને તાજા સમાચાર.', 'Gandhinagar में Sports Excellence and Youth Empowerment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Athletes from <strong>Gandhinagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>850 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹3,000 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Gandhinagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>850 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹3,000 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Gandhinagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>850 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹3,000 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', 'https://images.unsplash.com/photo-1568602471122-7832951cc4c5?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '2eba9c99-c05d-4f46-97ef-3944abd73d7d', 'Gandhinagar, Gujarat', 6, 58, 0, 0, 0, 0, 'Gandhinagar Athletes Win Big at National Championship Event | Gujarat Post', 'Latest updates on sports excellence and youth empowerment in Gandhinagar. Read complete report inside.', 'Gandhinagar, Gujarat news, Sports, latest updates', NULL, NULL, '2026-08-07 05:21:43', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('e4c48ced-16d2-4ef5-972e-87ec02fff268', 'suratlatestarticle', 273, 'Top news', 'Top news', 'Top news', 'top news of <b>surat</b>', 'top news of <b>surat</b>', 'top news of <b>surat</b>', '## 📌 AT A GLANCE (KEY HIGHLIGHTS)\n--------------------------------------------------\nTop news\n--------------------------------------------------\n\n<p style="-webkit-font-smoothing: antialiased; font-family: Roboto, sans-serif; text-rendering: optimizelegibility; line-height: 24px; font-size: 16px; color: rgb(0, 0, 0);">The decision overrules Tower Hamlets Council, the local mayor and the Save Brick Lane campaign, a coalition of nine resident groups who opposed the scheme.</p><p style="-webkit-font-smoothing: antialiased; font-family: Roboto, sans-serif; text-rendering: optimizelegibility; line-height: 24px; font-size: 16px; color: rgb(0, 0, 0); margin-top: 16px !important;">The approval came through ministerial recovery of planning appeals, meaning the Secretary of State took the final decision rather than leaving it with the local authority. The masterplan from developers Truman Estates Ltd and Zeloof LLP includes five new office buildings, a 5,200 sq ft data centre on Grey Eagle Street, a cinema, a supermarket, market space and 44 residential units. Of those homes, six are earmarked for social rent.</p><p style="-webkit-font-smoothing: antialiased; font-family: Roboto, sans-serif; text-rendering: optimizelegibility; line-height: 24px; font-size: 16px; color: rgb(0, 0, 0); margin-top: 16px !important;">Tower Hamlets wanted a housing-led scheme instead. The borough has more than 30,000 households on its social housing waiting list, and the council argued the site should prioritise homes over commercial development. According to reporting on the decision letter, the government gave that housing case no more than limited weight, while giving the data centre significant weight for meeting what it called the need for data centre capacity, without specifying how many jobs the facility would create.</p>\n\n![Gallery Image 2](https://res.cloudinary.com/t6pf4kyu/image/upload/v1786532117/gujarat-post/yuzspnhhufg16j4wnxvc.png)\n\n![Gallery Image 3](https://res.cloudinary.com/t6pf4kyu/image/upload/v1786532122/gujarat-post/qprhpa5pgvrfbaxivhtc.png)\n\n![Gallery Image 4](https://res.cloudinary.com/t6pf4kyu/image/upload/v1786532129/gujarat-post/xvhsas3yetgkpe4zrfxl.png)\n\n![Gallery Image 5](https://res.cloudinary.com/t6pf4kyu/image/upload/v1786532140/gujarat-post/ogyh00exeejxl5tgm1ed.png)\n\n> "Top news"\n> — Top news\n\nTop news', '## 📌 એક નજરમાં (KEY HIGHLIGHTS)\n--------------------------------------------------\nTop news\n--------------------------------------------------\n\n<p style="-webkit-font-smoothing: antialiased; font-family: Roboto, sans-serif; text-rendering: optimizelegibility; line-height: 24px; font-size: 16px; color: rgb(0, 0, 0);">The decision overrules Tower Hamlets Council, the local mayor and the Save Brick Lane campaign, a coalition of nine resident groups who opposed the scheme.</p><p style="-webkit-font-smoothing: antialiased; font-family: Roboto, sans-serif; text-rendering: optimizelegibility; line-height: 24px; font-size: 16px; color: rgb(0, 0, 0); margin-top: 16px !important;">The approval came through ministerial recovery of planning appeals, meaning the Secretary of State took the final decision rather than leaving it with the local authority. The masterplan from developers Truman Estates Ltd and Zeloof LLP includes five new office buildings, a 5,200 sq ft data centre on Grey Eagle Street, a cinema, a supermarket, market space and 44 residential units. Of those homes, six are earmarked for social rent.</p><p style="-webkit-font-smoothing: antialiased; font-family: Roboto, sans-serif; text-rendering: optimizelegibility; line-height: 24px; font-size: 16px; color: rgb(0, 0, 0); margin-top: 16px !important;">Tower Hamlets wanted a housing-led scheme instead. The borough has more than 30,000 households on its social housing waiting list, and the council argued the site should prioritise homes over commercial development. According to reporting on the decision letter, the government gave that housing case no more than limited weight, while giving the data centre significant weight for meeting what it called the need for data centre capacity, without specifying how many jobs the facility would create.</p>\n\n![Gallery Image 2](https://res.cloudinary.com/t6pf4kyu/image/upload/v1786532117/gujarat-post/yuzspnhhufg16j4wnxvc.png)\n\n![Gallery Image 3](https://res.cloudinary.com/t6pf4kyu/image/upload/v1786532122/gujarat-post/qprhpa5pgvrfbaxivhtc.png)\n\n![Gallery Image 4](https://res.cloudinary.com/t6pf4kyu/image/upload/v1786532129/gujarat-post/xvhsas3yetgkpe4zrfxl.png)\n\n![Gallery Image 5](https://res.cloudinary.com/t6pf4kyu/image/upload/v1786532140/gujarat-post/ogyh00exeejxl5tgm1ed.png)\n\n> "Top news"\n> — Top news\n\nTop news', '## 📌 एक नजर में (KEY HIGHLIGHTS)\n--------------------------------------------------\nTop news\n--------------------------------------------------\n\n<p style="-webkit-font-smoothing: antialiased; font-family: Roboto, sans-serif; text-rendering: optimizelegibility; line-height: 24px; font-size: 16px; color: rgb(0, 0, 0);">The decision overrules Tower Hamlets Council, the local mayor and the Save Brick Lane campaign, a coalition of nine resident groups who opposed the scheme.</p><p style="-webkit-font-smoothing: antialiased; font-family: Roboto, sans-serif; text-rendering: optimizelegibility; line-height: 24px; font-size: 16px; color: rgb(0, 0, 0); margin-top: 16px !important;">The approval came through ministerial recovery of planning appeals, meaning the Secretary of State took the final decision rather than leaving it with the local authority. The masterplan from developers Truman Estates Ltd and Zeloof LLP includes five new office buildings, a 5,200 sq ft data centre on Grey Eagle Street, a cinema, a supermarket, market space and 44 residential units. Of those homes, six are earmarked for social rent.</p><p style="-webkit-font-smoothing: antialiased; font-family: Roboto, sans-serif; text-rendering: optimizelegibility; line-height: 24px; font-size: 16px; color: rgb(0, 0, 0); margin-top: 16px !important;">Tower Hamlets wanted a housing-led scheme instead. The borough has more than 30,000 households on its social housing waiting list, and the council argued the site should prioritise homes over commercial development. According to reporting on the decision letter, the government gave that housing case no more than limited weight, while giving the data centre significant weight for meeting what it called the need for data centre capacity, without specifying how many jobs the facility would create.</p>\n\n![Gallery Image 2](https://res.cloudinary.com/t6pf4kyu/image/upload/v1786532117/gujarat-post/yuzspnhhufg16j4wnxvc.png)\n\n![Gallery Image 3](https://res.cloudinary.com/t6pf4kyu/image/upload/v1786532122/gujarat-post/qprhpa5pgvrfbaxivhtc.png)\n\n![Gallery Image 4](https://res.cloudinary.com/t6pf4kyu/image/upload/v1786532129/gujarat-post/xvhsas3yetgkpe4zrfxl.png)\n\n![Gallery Image 5](https://res.cloudinary.com/t6pf4kyu/image/upload/v1786532140/gujarat-post/ogyh00exeejxl5tgm1ed.png)\n\n> "Top news"\n> — Top news\n\nTop news', 'https://res.cloudinary.com/dvcffkyjz/video/upload/v1786602194/gujarat-post/uv4woivbzmymvw5wxj6v.mp4', 'PUBLISHED', NULL, '56a17220-190a-4e17-b56e-7c06101f37f8', '65035c12-8c98-4acf-bddd-e061b2fc81dd', 'Surat', 3, 0, 0, 0, 1, 22, 'Top news', 'Top news', 'Top news', '', 'index, follow', '2026-08-12 10:56:08', '2026-08-19 04:50:50');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('e7ab6b9d-9d0a-4a60-8b4d-53eb9b6783b1', 'big-gift-for-gujarat-new-semiconductor-policy-announced-thousands-of-jobs-to-be-created-8', 108, '#108 - Big gift for Gujarat: New semiconductor policy announced, thousands of jobs to be created - Full Ground Coverage', '#108 - ગુજરાતને મોટી ભેટ! નવી સેમિકન્ડક્ટર પોલિસી જાહેર, હજારો નોકરીઓ મળશે', '#108 - गुजरात को बड़ी सौगात! नई सेमीकंडक्टर नीति घोषित, हजारों नौकरियां मिलेंगी', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1599930113854-d6d7fd521f10?w=800&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '9162cf30-4fba-40d8-a384-3583cdff56cf', NULL, 5, 113, 1, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:10', '2026-08-14 11:11:58');
