INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('e9570440-fa71-4b81-b5b2-c8191dd9e8b5', 'bhavnagar-athletes-win-big-at-national-championship-event-1786108910696-52', 49, '#49 - Bhavnagar Athletes Win Big at National Championship Event', '#49 - રાષ્ટ્રીય ચેમ્પિયનશિપ ઇવેન્ટમાં Bhavnagar ના ખેલાડીઓની ભવ્ય જીત', '#49 - राष्ट्रीय चैंपियनशिप प्रतियोगिता में Bhavnagar के एथलीटों ने बड़ी जीत हासिल की', 'Latest updates on sports excellence and youth empowerment in Bhavnagar. Read complete report inside.', 'Bhavnagar માં Sports Excellence and Youth Empowerment અંગેના વાયરલ અને તાજા સમાચાર.', 'Bhavnagar में Sports Excellence and Youth Empowerment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Athletes from <strong>Bhavnagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>8,050 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹24,600 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Bhavnagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>8,050 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹24,600 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Bhavnagar</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>8,050 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹24,600 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', 'https://images.unsplash.com/photo-1564507592333-c60657eea523?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', 'e4f6985f-03b9-48b6-9ec1-8283410a92c4', 'Bhavnagar, Gujarat', 5, 71, 0, 0, 0, 0, 'Bhavnagar Athletes Win Big at National Championship Event | Gujarat Post', 'Latest updates on sports excellence and youth empowerment in Bhavnagar. Read complete report inside.', 'Bhavnagar, Gujarat news, Instagram, latest updates', NULL, NULL, '2026-08-03 05:21:50', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('eb4ce11d-368f-4f7e-9446-dfb1cab072d0', 'stock-market-rally-gujarat-based-stocks-outperform-index-54', 154, '#154 - Stock market rally: Gujarat-based stocks outperform index - Full Ground Coverage', '#154 - શેરબજાર રેલી: ગુજરાત આધારિત શેરો ઇન્ડેક્સ કરતા આગળ', '#154 - शेयर बाजार रैली: गुजरात आधारित शेयर सूचकांक से आगे', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1486406146926-c627a92ad1ab?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '6df0d11b-0d54-4980-b581-1e4185a04584', NULL, 6, 67, 0, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:23', '2026-08-17 10:00:44');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('ec50f278-8455-41d8-abfb-96cebd4a9fb3', 'surendranagar-cotton-ginning-solar-park-greenfield-project', 264, 'Surendranagar Cotton Ginning and Solar Park Greenfield Power Project', 'સુરેન્દ્રનગર ઝાલાવાડ કાપડ જીનિંગ હબ અને ગ્રીન સોલાર પાર્ક પ્રોજેક્ટ શરૂ', 'सुरेंद्रनगर जालावाड़ कपड़ा जीनिंग हब और ग्रीन सोलर पार्क परियोजना शुरू', 'Surendranagar Jhalawad installs 500 MW solar plant powering Asia largest cotton processing units.', 'સુરેન્દ્રનગરમાં ૫૦૦ મેગાવોટનો નવો સોલાર એનર્જી પાર્ક કાર્યરત, કોટન જીનિંગ મિલને સસ્તી વીજળી મળશે.', 'सुरेंद्रनगर में 500 मेगावाट का नया सौर ऊर्जा पार्क चालू, कॉटन जीनिंग मिलों को सस्ती बिजली मिलेगी।', '<p>ઝાલાવાડની ભૂમિ સુરેન્દ્રનગર જિલ્લામાં કોટન પ્રોસેસિંગ અને પુનઃપ્રાપ્ય ઉર્જા ક્ષેત્રે ક્રાંતિકારી ફેરફારો આવ્યા છે. 500 મેગાવોટ ક્ષમતાના સોલાર પાર્કથી વિસ્તારના કપાસ ઉત્પાદકો અને જીનિંગ મિલ માલિકોને પાવર ખર્ચમાં મોટો રાહત મળશે.</p>', '<p>ઝાલાવાડની ભૂમિ સુરેન્દ્રનગર જિલ્લામાં કોટન પ્રોસેસિંગ અને સોલાર ક્ષેત્રે ક્રાંતિ આવી છે.</p>', '<p>झालावाड़ की भूमि सुरेंद्रनगर जिले में कपास प्रसंस्करण और सौर ऊर्जा क्षेत्र में क्रांति आई है।</p>', 'https://images.unsplash.com/photo-1509391365360-2e959784a276?w=1200&q=90', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '968c7b79-e486-4a36-8720-99f33c015339', 'Surendranagar', 0, 0, 1, 0, 1, 14, NULL, NULL, NULL, NULL, NULL, '2026-08-12 06:12:34', '2026-08-19 04:51:07');
