INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('f33e52cf-7550-49fa-9d69-984bb4f28b7b', 'surat-athletes-win-big-at-national-championship-event-1786108912706-64', 37, '#37 - Surat Athletes Win Big at National Championship Event', '#37 - રાષ્ટ્રીય ચેમ્પિયનશિપ ઇવેન્ટમાં Surat ના ખેલાડીઓની ભવ્ય જીત', '#37 - राष्ट्रीय चैंपियनशिप प्रतियोगिता में Surat के एथलीटों ने बड़ी जीत हासिल की', 'Latest updates on sports excellence and youth empowerment in Surat. Read complete report inside.', 'Surat માં Sports Excellence and Youth Empowerment અંગેના વાયરલ અને તાજા સમાચાર.', 'Surat में Sports Excellence and Youth Empowerment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Athletes from <strong>Surat</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>9,850 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹30,000 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Surat</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>9,850 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹30,000 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', '<p>Athletes from <strong>Surat</strong> delivered an outstanding performance at the National Games, bagging a total of <strong>9,850 Gold medals</strong> across multiple sports disciplines.</p><p>The team\'s captain dedicated the victory to their coaches and supporters, stating that <strong>rigorous discipline and state-backed sports academies</strong> played a vital role in their success.</p><p>Sports officials announced a <strong>₹30,000 lakh incentive award</strong> for all winning athletes to support their training for upcoming international tournaments.</p>', 'https://images.unsplash.com/photo-1494172961521-33799ddd43a5?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '65035c12-8c98-4acf-bddd-e061b2fc81dd', 'Surat, Gujarat', 6, 51, 0, 0, 0, 0, 'Surat Athletes Win Big at National Championship Event | Gujarat Post', 'Latest updates on sports excellence and youth empowerment in Surat. Read complete report inside.', 'Surat, Gujarat news, Surat, latest updates', NULL, NULL, '2026-08-02 05:21:52', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('f3a002bd-920c-4f93-9fde-ec92a8059ec0', 'sanand-emerges-as-major-electronics-and-smartphone-assembly-hub', 231, 'Sanand Emerges as Major Electronics & Smartphone Assembly Hub with Global Tech Giants', 'સાણંદ બનશે ગ્લોબલ ટેક હબ: સ્માર્ટફોન અને લેપટોપ મેન્યુફેક્ચરિંગ યુનિટ્સનો ધમધમાટ શરૂ', 'साणंद बनेगा ग्लोबल टेक हब: स्मार्टफोन और लैपटॉप मैन्युफैक्चरिंग यूनिट्स की शुरुआत', 'Global electronics hardware giants open high-capacity laptop & smartphone manufacturing units in Sanand industrial park, boosting Make in India exports.', 'વિશ્વની અગ્રણી ઇલેક્ટ્રોનિક્સ કંપનીઓએ સાણંદ અને દહેજ ઇન્ડસ્ટ્રિયલ ઝોનમાં નવા એસેમ્બલી યુનિટ્સ સ્થાપ્યા છે, જેનાથી મેક ઇન ઇન્ડિયાને વેગ મળશે.', 'वैश्विक इलेक्ट्रॉनिक्स कंपनियों ने साणंद औद्योगिक पार्क में लैपटॉप और स्मार्टफोन निर्माण इकाइयां स्थापित की हैं, जिससे मेक इन इंडिया को बढ़ावा मिलेगा।', '<p>Sanand, already well-known as an automotive powerhouse, has expanded into a major electronics assembly destination as leading global smartphone and laptop manufacturers commence large-scale operations.</p>\n<h2>Robotic Automation & Surface Mount Technology</h2>\n<p>The state-of-the-art facilities leverage robotic SMT lines to assemble printed circuit boards (PCBs), camera modules, and display assemblies locally.</p>\n<h2>Direct Export Out of Mundra & Kandla Ports</h2>\n<p>Hardware produced in the Sanand tech ecosystem will supply both the growing domestic market and international markets across Europe and the Middle East via Gujarat\'s deep-water ports.</p>\n<ul>\n<li>Production capacity exceeding 15 million devices annually</li>\n<li>Dedicated industrial training centers established for local polytechnic graduates</li>\n<li>Supply chain incentives attracting component suppliers and glass fabricators</li>\n</ul>\n<p>This industrial boom highlights Gujarat\'s pivotal role in global consumer electronics manufacturing.</p>', '<p>ઓટોમોબાઇલ હબ તરીકે ઓળખાતું સાણંદ હવે ગ્લોબલ ઇલેક્ટ્રોનિક્સ અને સ્માર્ટફોન મેન્યુફેક્ચરિંગ સેન્ટર તરીકે ઊભરી આવ્યું છે. વિશ્વની ટોચની ટેકનોલોજી કંપનીઓએ અહીં પોતાના હાઇ-ટેક પ્લાન્ટ્સ કાર્યરત કર્યા છે.</p>\n<h2>રોબોટિક એસેમ્બલી અને SMT ટેકનોલોજી</h2>\n<p>નવા સ્થપાયેલા પ્લાન્ટ્સમાં ઓટોમેટેડ રોબોટિક SMT પ્રક્રિયા દ્વારા પ્રિન્ટેડ સર્કિટ બોર્ડ (PCB), કેમેરા મોડ્યુલ્સ અને ઓર્ગેનિક LED ડિસ્પ્લેનું સ્થાનિક સ્તરે એસેમ્બલિંગ શરૂ થયું છે.</p>\n<h2>મુન્દ્રા અને કંડલા પોર્ટ મારફતે નિકાસ</h2>\n<p>સાણંદ ખાતે ઉત્પાદિત સ્માર્ટફોન, ટેબલેટ અને લેપટોપ ભારતીય બજાર ઉપરાંત ગુજરાતના મુન્દ્રા અને કંડલા પોર્ટ મારફતે યુરોપ અને મધ્ય પૂર્વના દેશોમાં નિકાસ કરવામાં આવશે.</p>\n<ul>\n<li>વાર્ષિક ૧.૫ કરોડથી વધુ સ્માર્ટ ઉપકરણોનું ઉત્પાદન ક્ષમતા</li>\n<li>સ્થાનિક આઇટીઆઇ અને ડિપ્લોમા એન્જિનિયરો માટે વિશેષ તાલીમ સેન્ટર</li>\n<li>કોમ્પોનન્ટ મેન્યુફેક્ચરિંગ સપ્લાય ચેઇનમાં ૨૫૦થી વધુ નાની ફેક્ટરીઓને ઓર્ડર</li>\n</ul>\n<blockquote>"સાણંદનું ઈલેક્ટ્રોનિક્સ ક્લસ્ટર ભારતને મેન્યુફેક્ચરિંગ ક્ષેત્રે વિશ્વમાં અગ્રેસર બનાવશે." — ઉદ્યોગ મંત્રી</blockquote>\n<p>સ્થાનિક યુવાનો માટે નોકરીઓની નવી તકો ઉભી થતાં સમગ્ર વિસ્તારના આર્થિક વિકાસને વેગ મળ્યો છે.</p>', '<p>ऑटोमोबाइल केंद्र के रूप में प्रसिद्ध साणंद अब इलेक्ट्रॉनिक्स और स्मार्टफोन विनिर्माण का बड़ा केंद्र बन गया है। वैश्विक टेक दिग्गज कंपनियों ने यहां अपने बड़े असेंबली प्लांट शुरू किए हैं।</p>\n<h2>रोबोटिक असेंबली तकनीक</h2>\n<p>कारखानों में स्वचालित रोबोटिक लाइनों द्वारा सर्किट बोर्ड, कैमरा मॉड्यूल और डिस्प्ले असेंबल किए जा रहे हैं।</p>\n<h2>मुंद्रा और कांडला बंदरगाह से निर्यात</h2>\n<p>साणंद में निर्मित इलेक्ट्रॉनिक्स उत्पाद भारतीय बाजार के साथ-साथ मुंद्रा और कांडला बंदरगाहों से विदेशों में निर्यात किए जाएंगे।</p>\n<ul>\n<li>वार्षिक 1.5 करोड़ से अधिक उपकरणों का उत्पादन</li>\n<li>तकनीकी युवाओं के लिए कौशल प्रशिक्षण केंद्र</li>\n<li>सहायक उद्योगों का तेजी से विस्तार</li>\n</ul>\n<p>गुजरात वैश्विक इलेक्ट्रॉनिक्स निर्माण में अपनी मजबूत छाप छोड़ रहा है।</p>', 'https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'a16e896a-139e-48c1-bd75-cb15309a4622', NULL, 3, 82, 0, 0, 1, 1, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:47:43', '2026-08-17 10:00:43');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('f3a8ff54-5b85-455e-828c-7ee8035e9ed9', 'green-energy-initiative-set-to-power-100-of-surat-public-grid-1786108902690-1', 100, '#100 - Green Energy Initiative Set to Power 100% of Surat Public Grid', '#100 - હરિત ઊર્જા પહેલ Surat પબ્લિક ગ્રીડના 100% ને પાવર આપવા માટે તૈયાર', '#100 - हरित ऊर्जा पहल Surat पब्लिक ग्रिड को 100% बिजली देने के लिए तैयार', 'Latest updates on renewable energy and environment in Surat. Read complete report inside.', 'Surat માં Renewable Energy and Environment અંગેના વાયરલ અને તાજા સમાચાર.', 'Surat में Renewable Energy and Environment से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A breakthrough solar and wind hybrid power project in <strong>Surat</strong> has reached its target capacity of <strong>400 Megawatts</strong> this week.</p><p>With this achievement, <strong>Surat becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Surat</strong> has reached its target capacity of <strong>400 Megawatts</strong> this week.</p><p>With this achievement, <strong>Surat becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', '<p>A breakthrough solar and wind hybrid power project in <strong>Surat</strong> has reached its target capacity of <strong>400 Megawatts</strong> this week.</p><p>With this achievement, <strong>Surat becomes one of India\'s leading green energy hubs</strong>. Experts note that <strong>carbon emissions will drop by over 45%</strong> within the next 12 months.</p><p>Local authorities emphasized that <strong>clean energy guarantees a healthier environment for future generations</strong> while driving down electricity tariffs for industries and households.</p>', 'https://images.unsplash.com/photo-1558618666-fcd25c85cd64?w=800&q=80', 'PUBLISHED', NULL, '160fa9ec-b312-4b87-9341-1508f63b8298', '05402fdd-3719-4fe7-abbc-9e80725cd389', 'Surat, Gujarat', 5, 74, 0, 0, 0, 1, 'Green Energy Initiative Set to Power 100% of Surat Public Grid | Gujarat Post', 'Latest updates on renewable energy and environment in Surat. Read complete report inside.', 'Surat, Gujarat news, Ahmedabad, latest updates', NULL, NULL, '2026-08-07 11:21:42', '2026-08-16 14:07:28');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('f3ed0302-7a8c-4993-9fd7-0989bf3206a0', 'state-of-the-art-multi-specialty-hospital-inaugurated-in-ahmedabad-1786108906862-27', 74, '#74 - State-of-the-Art Multi-Specialty Hospital Inaugurated in Ahmedabad', '#74 - Ahmedabad માં અત્યાધુનિક મલ્ટી-સ્પેશિયાલિટી હોસ્પિટલનું ઉદ્ઘાટન', '#74 - Ahmedabad में अत्याधुनिक मल्टी-स्पेशलिटी अस्पताल का उद्घाटन', 'Latest updates on healthcare and medical breakthroughs in Ahmedabad. Read complete report inside.', 'Ahmedabad માં Healthcare and Medical Breakthroughs અંગેના વાયરલ અને તાજા સમાચાર.', 'Ahmedabad में Healthcare and Medical Breakthroughs से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A new <strong>4,300-bed advanced hospital facility</strong> was officially opened to the public in <strong>Ahmedabad</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 13,350 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>4,300-bed advanced hospital facility</strong> was officially opened to the public in <strong>Ahmedabad</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 13,350 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>4,300-bed advanced hospital facility</strong> was officially opened to the public in <strong>Ahmedabad</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 13,350 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', 'https://images.unsplash.com/photo-1491336440196-6d4fee45a05c?w=800&q=80', 'PUBLISHED', NULL, '6e329fea-cd2d-4295-a98e-64bddfe20da6', 'f8cde491-4b92-40b5-a8ec-9171b5fc3252', 'Ahmedabad, Gujarat', 6, 54, 1, 0, 0, 1, 'State-of-the-Art Multi-Specialty Hospital Inaugurated in Ahmedabad | Gujarat Post', 'Latest updates on healthcare and medical breakthroughs in Ahmedabad. Read complete report inside.', 'Ahmedabad, Gujarat news, Videos, latest updates', NULL, NULL, '2026-08-05 07:21:46', '2026-08-19 01:11:36');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('f42fdd6b-d568-4421-ac71-19c7b6f66e1f', 'state-of-the-art-multi-specialty-hospital-inaugurated-in-kutch-1786108907521-33', 68, '#68 - State-of-the-Art Multi-Specialty Hospital Inaugurated in Kutch', '#68 - Kutch માં અત્યાધુનિક મલ્ટી-સ્પેશિયાલિટી હોસ્પિટલનું ઉદ્ઘાટન', '#68 - Kutch में अत्याधुनिक मल्टी-स्पेशलिटी अस्पताल का उद्घाटन', 'Latest updates on healthcare and medical breakthroughs in Kutch. Read complete report inside.', 'Kutch માં Healthcare and Medical Breakthroughs અંગેના વાયરલ અને તાજા સમાચાર.', 'Kutch में Healthcare and Medical Breakthroughs से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A new <strong>5,200-bed advanced hospital facility</strong> was officially opened to the public in <strong>Kutch</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 16,050 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>5,200-bed advanced hospital facility</strong> was officially opened to the public in <strong>Kutch</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 16,050 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>5,200-bed advanced hospital facility</strong> was officially opened to the public in <strong>Kutch</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 16,050 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', 'https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=800&q=80', 'PUBLISHED', NULL, '6e329fea-cd2d-4295-a98e-64bddfe20da6', '33c842e2-4efa-4b25-a12d-ac1a1fe1f561', 'Kutch, Gujarat', 3, 64, 1, 0, 0, 0, 'State-of-the-Art Multi-Specialty Hospital Inaugurated in Kutch | Gujarat Post', 'Latest updates on healthcare and medical breakthroughs in Kutch. Read complete report inside.', 'Kutch, Gujarat news, Politics, latest updates', NULL, NULL, '2026-08-04 19:21:47', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('f46633d3-da87-45cf-b1b0-a1db498389ca', 'next-gen-solid-state-ev-battery-plant-announced-in-gujarat', 230, 'Breakthrough in EV Tech: Next-Gen Solid-State EV Battery Plant Announced in Gujarat', 'ઇલેક્ટ્રિક વાહનો ક્ષેત્રે મોટો ધડાકો: 1000 KM રેન્જ આપતી નવી બેટરી ટેકનોલોજીનો પ્લાન્ટ લોન્ચ', 'इलेक्ट्रिक वाहनों के क्षेत्र में क्रांति: 1000 KM रेंज देने वाली नई बैटरी तकनीक का प्लांट लॉन्च', 'State-of-the-art solid-state battery gigafactory set up in Mandal-Becharaji SIR promises 1000km single-charge range and ultra-fast charging capability.', 'સૂર્ય ઊર્જા અને સોલિડ-સ્ટેટ બેટરી ટેકનોલોજીમાં ગુજરાતે નવો ઇતિહાસ રચ્યો છે. નવો ગ્રીન એનર્જી પ્લાન્ટ બેટરી ઉત્પાદનમાં મોટી ક્રાંતિ લાવશે.', 'गुजरात में सॉलिड-स्टेट बैटरी गीगाफैक्ट्री की स्थापना से इलेक्ट्रिक वाहनों को एक चार्ज में 1000 किमी की रेंज और अल्ट्रा-फास्ट चार्जिंग मिलेगी।', '<p>Clean technology innovators in partnership with green energy developers have initiated construction on India\'s first solid-state lithium EV battery gigafactory in Gujarat\'s Mandal-Becharaji Special Investment Region (SIR).</p>\n<h2>1000 KM Single-Charge Range</h2>\n<p>Solid-state electrolyte technology eliminates liquid flammability risks while delivering nearly double the energy density of traditional lithium-ion packs, enabling passenger electric vehicles to surpass 1000 kilometers per charge.</p>\n<h2>10-Minute Ultra-Fast Charging Grid</h2>\n<p>The manufacturing hub will also produce specialized high-powered energy storage units compatible with 350kW solar-powered charging stations across highway corridors.</p>\n<ul>\n<li>Solid-state cell fabrication with high thermal stability and fire resistance</li>\n<li>10-minute fast charging capability up to 80% capacity</li>\n<li>Comprehensive battery recycling plant built within the gigafactory campus</li>\n</ul>\n<p>This initiative significantly positions Gujarat as a global exporter of sustainable e-mobility components.</p>', '<p>ક્લીન ટેકનોલોજી અને ગ્રીન એનર્જી ક્ષેત્રે ગુજરાતે મોટો રેકોર્ડ બનાવ્યો છે. રાજ્યના મંડલ-બેચરાજી સ્પેશિયલ ઇન્વેસ્ટમેન્ટ રીજન (SIR) ખાતે દેશની પ્રથમ સોલિડ-સ્ટેટ લિથિયમ EV બેટરી ગીગાફેક્ટ્રીનું નિર્માણ કાર્ય શરૂ થયું છે.</p>\n<h2>એક ચાર્જમાં 1000 KM ની રેન્જ</h2>\n<p>નવી સોલિડ-સ્ટેટ બેટરી ટેકનોલોજીમાં પરંપરાગત લિક્વિડ લિથિયમ-આયન બેટરી કરતા બમણી ઊર્જા ઘનતા છે, જેનાથી ઇલેક્ટ્રિક કાર એક જ ચાર્જમાં ૧૦૦૦ કિલોમીટરથી વધુ અંતર કાપી શકશે.</p>\n<h2>માત્ર 10 મિનિટમાં 80% ચાર્જિંગ</h2>\n<p>આ પ્લાન્ટ ખાતે અત્યાધુનિક અલ્ટ્રા-ફાસ્ટ ચાર્જિંગ બેટરી પેક તૈયાર કરવામાં આવશે જે સૂર્ય ઊર્જા સંચાલિત ૩૫૦kW ચાર્જિંગ સ્ટેશન સાથે કામ કરશે.</p>\n<ul>\n<li>ઉચ્ચ થર્મલ સલામતી અને આગ-પ્રતિરોધક સોલિડ ઇલેક્ટ્રોલાઇટ ટેકનોલોજી</li>\n<li>હાઇવે કોરિડોર પર ૧૦ મિનિટમાં ૮૦% બેટરી ચાર્જ કરવાની ક્ષમતા</li>\n<li>પર્યાવરણ પૂરક બેટરી રિસાઇક્લિંગ પ્લાન્ટનો પણ સમાવેશ</li>\n</ul>\n<blockquote>"સોલિડ-સ્ટેટ બેટરી ઉત્પાદનથી ભારત ઈલેક્ટ્રિક વ્હીકલ ક્ષેત્રે આત્મનિર્ભર બનશે." — ગ્રીન એનર્જી કમિશનર</blockquote>\n<p>આગામી બે વર્ષમાં અહીંથી વ્યાપારી ધોરણે બેટરી પેકનું સપ્લાય શરૂ થશે.</p>', '<p>ग्रीन एनर्जी क्षेत्र में गुजरात ने बड़ा मुकाम हासिल किया है। मंडल-बेचराजी स्पेशल इन्वेस्टमेंट रीजन में भारत की पहली सॉलिड-स्टेट ईवी बैटरी गीगाफैक्ट्री का काम शुरू हो गया है।</p>\n<h2>एक चार्ज में 1000 किमी की रेंज</h2>\n<p>यह नई सॉलिड-स्टेट तकनीक पारंपरिक बैटरियों की तुलना में दोगुनी ऊर्जा क्षमता प्रदान करेगी, जिससे ईवी 1000 किमी तक चल सकेंगे।</p>\n<h2>10 मिनट में फास्ट चार्जिंग</h2>\n<p>प्लांट में ऐसी बैटरियां बनेंगी जो मात्र 10 मिनट में 80% तक चार्ज हो सकेंगी।</p>\n<ul>\n<li>उच्च सुरक्षा और आग-प्रतिरोधी तकनीक</li>\n<li>अल्ट्रा-फास्ट चार्जिंग इंफ्रास्ट्रक्चर</li>\n<li>पर्यावरण के अनुकूल रीसाइक्लिंग यूनिट</li>\n</ul>\n<p>इससे भारत का इलेक्ट्रिक वाहन उद्योग तेजी से आगे बढ़ेगा।</p>', 'https://images.unsplash.com/photo-1558441719-67450807e990?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'a16e896a-139e-48c1-bd75-cb15309a4622', NULL, 4, 85, 1, 0, 1, 4, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:47:43', '2026-08-17 10:13:33');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('f5f0f6c3-a634-4deb-ac8c-196cac0b54c8', 'market-boom-business-investments-in-jamnagar-reach-record-high-1786108910811-53', 48, '#48 - Market Boom: Business Investments in Jamnagar Reach Record High', '#48 - માર્કેટ બૂમ: Jamnagar માં વ્યાપારી રોકાણ રેકોર્ડ સપાટીએ પહોંચ્યું', '#48 - मार्केट बूम: Jamnagar में व्यावसायिक निवेश रिकॉर्ड स्तर पर पहुंचा', 'Latest updates on business, finance and market trends in Jamnagar. Read complete report inside.', 'Jamnagar માં Business, Finance and Market Trends અંગેના વાયરલ અને તાજા સમાચાર.', 'Jamnagar में Business, Finance and Market Trends से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>Foreign and domestic investments in <strong>Jamnagar</strong> surged to an all-time high of <strong>₹8,200 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 25,050 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Jamnagar</strong> surged to an all-time high of <strong>₹8,200 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 25,050 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', '<p>Foreign and domestic investments in <strong>Jamnagar</strong> surged to an all-time high of <strong>₹8,200 crore</strong> during the current quarter.</p><p>The surge is attributed to <strong>favorable industrial policies, streamlined single-window clearances, and robust logistics networks</strong>.</p><p>Financial analysts project that <strong>continued economic expansion will create over 25,050 job opportunities</strong> across manufacturing, services, and trade sectors in Gujarat.</p>', 'https://images.unsplash.com/photo-1524492412937-b28074a47d70?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', 'f6650f9f-c367-4712-8ad1-18f599f12a53', 'Jamnagar, Gujarat', 3, 88, 0, 0, 0, 0, 'Market Boom: Business Investments in Jamnagar Reach Record High | Gujarat Post', 'Latest updates on business, finance and market trends in Jamnagar. Read complete report inside.', 'Jamnagar, Gujarat news, Gold - Silver, latest updates', NULL, NULL, '2026-08-03 03:21:50', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('f6acf48e-e4b7-4ad0-8f34-62ced7151792', 'new-cabinet-reshuffle-expected-in-gujarat-government-59', 159, '#159 - New cabinet reshuffle expected in Gujarat government - Full Ground Coverage', '#159 - ગુજરાત સરકારમાં નવો કેબિનેટ ફેરફાર અપેક્ષિત', '#159 - गुजरात सरकार में नया कैबिनेट फेरबदल अपेक्षित', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1541872703-74c5e44368f9?w=800&q=80', 'PUBLISHED', NULL, '76e09d20-adf1-4d6c-8e4a-ef3ed2dacdc3', '33c842e2-4efa-4b25-a12d-ac1a1fe1f561', NULL, 6, 62, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:25', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('f6f93143-58ee-4217-8f72-63f5ce8c79e6', 'gandhinagar-ai-data-center-and-semiconductor-plant-launched', 227, 'India\'s Tech Shift: Gandhinagar AI Data Center and Semiconductor Manufacturing Plant Launched', 'સિલિકોન વેલી હબ બનવા તરફ ગુજરાત: ગાંધીનગરમાં નવો AI ડેટા સેન્ટર અને સેમિકન્ડક્ટર પ્લાન્ટ શરૂ', 'सिलिकॉन वैली हब बनने की ओर गुजरात: गांधीनगर में नया एआई डेटा सेंटर और सेमीकंडक्टर प्लांट शुरू', 'GIFT City Gandhinagar launches state-of-the-art AI data center and semiconductor fab unit, creating over 20,000 high-tech jobs in Gujarat.', 'ગાંધીનગરના ગિફ્ટ સિટીમાં સેમિકન્ડક્ટર અને આર્ટિફિશિયલ ઇન્ટેલિજન્સ (AI) રિસર્ચ હબ કાર્યરત થયું છે, જેનાથી રાજ્યમાં ૨૦,૦૦૦થી વધુ નવી ટેક નોકરીઓનું સર્જન થશે.', 'गांधीनगर के गिफ्ट सिटी में सेमीकंडक्टर और आर्टिफीशियल इंटेलिजेंस रिसर्च हब शुरू, 20,000 से अधिक टेक नौकरियों का होगा सृजन।', '<p>Gujarat has taken a major leap toward becoming India\'s leading technology and semiconductor hub. State authorities alongside global tech leaders unveiled a multi-billion-dollar semiconductor manufacturing plant and AI computing facility near Gandhinagar.</p>\n<h2>State-of-the-Art Semiconductor Fabrication</h2>\n<p>The newly established facility will manufacture microchips utilized in smart automotive systems, consumer electronics, and artificial intelligence processors. This move significantly reduces reliance on international chip supply chains.</p>\n<h2>Creating Over 20,000 High-Tech Careers</h2>\n<p>Industry analysts project massive job creation across software engineering, hardware design, VLSI chip architecture, and data center operations.</p>\n<ul>\n<li>Advanced AI Computing Cluster operational at GIFT City</li>\n<li>Partnerships signed with top global semiconductor corporations</li>\n<li>Skill development programs initiated across premier technical universities in Gujarat</li>\n</ul>\n<blockquote>"Gujarat is leading the charge in building India\'s native semiconductor and artificial intelligence backbone." — Senior Technology Advisor</blockquote>\n<p>Commercial chip output is slated to begin within the next 18 months, attracting secondary supply chain vendors across the state.</p>', '<p>ગુજરાત સરકારે રાજ્યને દેશનું અગ્રણી ટેકનોલોજી અને સેમિકન્ડક્ટર ઉત્પાદન હબ બનાવવા માટે મહત્વપૂર્ણ પગલું ભર્યું છે. ગાંધીનગર અને સાણંદ નજીક આકાર લઈ રહેલા વિશાળ સેમિકન્ડક્ટર પાર્કમાં વૈશ્વિક ટેક કંપનીઓએ અબજો રૂપિયાના રોકાણ સાથે હાઇ-ટેક પ્લાન્ટનો પ્રારંભ કર્યો છે.</p>\n<h2>ગાંધીનગરમાં અત્યાધુનિક સેમિકન્ડક્ટર પ્લાન્ટનો પ્રારંભ</h2>\n<p>આ સુવિધાથી માત્ર સ્થાનિક સ્તરે ચિપ મેન્યુફેક્ચરિંગ ક્ષમતા જ નહીં વધે પરંતુ ઓટોમોબાઇલ, સ્માર્ટફોન, મેડિકલ ઇક્વિપમેન્ટ અને એઆઇ ડિવાઇસ ઉત્પાદન ક્ષેત્રે પણ મોટી ક્રાંતિ આવશે.</p>\n<h2>૨૦,૦૦૦થી વધુ નવી ટેક નોકરીઓનું સર્જન</h2>\n<p>વિશેષજ્ઞોના મતે આ પ્રોજેક્ટથી IT એન્જિનિયરો, સોફ્ટવેર ડેવલપર્સ, VLSI ચિપ ડિઝાઇનર્સ અને રિસર્ચ સ્કોલર્સ માટે રોજગારીની વિશાળ તકો ઉભી થશે.</p>\n<ul>\n<li>ગિફ્ટ સિટી ખાતે અત્યાધુનિક AI ડેટા સેન્ટર સ્થાપવામાં આવ્યું</li>\n<li>ચિપ ડિઝાઇનિંગ અને ફેબ્રિકેશન ક્ષેત્રે વૈશ્વિક પાર્ટનરશિપ પર હસ્તાક્ષર</li>\n<li>સ્થાનિક એન્જિનિયરિંગ કોલેજો સાથે સ્કીલ ડેવલપમેન્ટ કરાર લાગુ</li>\n</ul>\n<blockquote>"ગુજરાત સેમિકન્ડક્ટર અને આર્ટિફિશિયલ ઇન્ટેલિજન્સ ક્ષેત્રે ભારતના ભવિષ્યની આગેવાની કરી રહ્યું છે." — સિનિયર ટેક વિશ્લેષક</blockquote>\n<p>આગામી ૧૮ મહિનામાં અહીંથી સેમિકન્ડક્ટર ચિપનું ઉત્પાદન પૂર્ણ ક્ષમતાથી શરૂ થશે તેવી અપેક્ષા રાખવામાં આવી રહી છે.</p>', '<p>गुजरात सरकार ने राज्य को देश का अग्रणी प्रौद्योगिकी और सेमीकंडक्टर विनिर्माण हब बनाने की दिशा में एक ऐतिहासिक कदम उठाया है। गांधीनगर में हाई-टेक सेमीकंडक्टर प्लांट और एआई डेटा सेंटर की शुरुआत की गई है।</p>\n<h2>अत्याधुनिक सेमीकंडक्टर फैब्रिकेशन</h2>\n<p>इस सुविधा से चिप निर्माण क्षमता बढ़ेगी जिससे ऑटोमोबाइल, स्मार्टफोन और एआई उपकरणों के निर्माण को नई दिशा मिलेगी।</p>\n<h2>20,000 से अधिक नौकरियों का अवसर</h2>\n<p>आईटी इंजीनियरों, सॉफ्टवेयर डेवलपर्स और चिप डिजाइनरों के लिए व्यापक रोजगार के अवसर पैदा होंगे।</p>\n<ul>\n<li>गिफ्ट सिटी में उन्नत एआई कंप्यूटिंग सेंटर चालू</li>\n<li>वैश्विक सेमीकंडक्टर कंपनियों के साथ समझौते</li>\n<li>तकनीकी संस्थानों में विशेष प्रशिक्षण कार्यक्रम</li>\n</ul>\n<p>अगले 18 महीनों में बड़े पैमाने पर उत्पादन शुरू होने की उम्मीद है।</p>', 'https://images.unsplash.com/photo-1518770660439-4636190af475?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'a16e896a-139e-48c1-bd75-cb15309a4622', NULL, 4, 95, 1, 1, 1, 2, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:47:40', '2026-08-17 10:13:36');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('f7206040-babe-43a5-9c5b-34a58846a8fb', 'state-of-the-art-multi-specialty-hospital-inaugurated-in-rajkot-1786108903132-3', 98, '#98 - State-of-the-Art Multi-Specialty Hospital Inaugurated in Rajkot', '#98 - Rajkot માં અત્યાધુનિક મલ્ટી-સ્પેશિયાલિટી હોસ્પિટલનું ઉદ્ઘાટન', '#98 - Rajkot में अत्याधुनिक मल्टी-स्पेशलिटी अस्पताल का उद्घाटन', 'Latest updates on healthcare and medical breakthroughs in Rajkot. Read complete report inside.', 'Rajkot માં Healthcare and Medical Breakthroughs અંગેના વાયરલ અને તાજા સમાચાર.', 'Rajkot में Healthcare and Medical Breakthroughs से जुड़ी सभी नई अपडेट्स और विस्तृत रिपोर्ट।', '<p>A new <strong>700-bed advanced hospital facility</strong> was officially opened to the public in <strong>Rajkot</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 2,550 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>700-bed advanced hospital facility</strong> was officially opened to the public in <strong>Rajkot</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 2,550 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', '<p>A new <strong>700-bed advanced hospital facility</strong> was officially opened to the public in <strong>Rajkot</strong> today, offering free emergency care and subsidized treatment.</p><p>Equipped with <strong>robotic surgery suites and AI diagnostic systems</strong>, the hospital aims to provide <strong>world-class medical care to over 2,550 families</strong> in the region.</p><p>Health department officials emphasized that <strong>preventative healthcare and accessible medicine remain top priorities</strong> for the state administration.</p>', 'https://images.unsplash.com/photo-1575936123452-b67c3203c357?w=800&q=80', 'PUBLISHED', NULL, '6e329fea-cd2d-4295-a98e-64bddfe20da6', '0ff7c7f6-b114-4f1e-a8ce-e929b9604d31', 'Rajkot, Gujarat', 5, 61, 1, 0, 0, 0, 'State-of-the-Art Multi-Specialty Hospital Inaugurated in Rajkot | Gujarat Post', 'Latest updates on healthcare and medical breakthroughs in Rajkot. Read complete report inside.', 'Rajkot, Gujarat news, Podcasts, latest updates', NULL, NULL, '2026-08-07 07:21:43', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('f886c275-199f-40b5-baef-b91bb485420c', 'gir-somnath-temple-promenade-veraval-fisheries-modernization', 271, 'Gir Somnath Temple Promenade and Veraval Fisheries Modernization', 'ગીર સોમનાથ પ્રથમ જ્યોતિર્લિંગ સમુદ્ર દર્શન પથ અને વેરાવળ ફિશરીઝ હબ', 'गिर सोमनाथ प्रथम ज्योतिर्लिंग समुद्र दर्शन पथ और वेरावल मत्स्य हब', 'Somnath Jyotirlinga Promenade and Veraval Fish Harbor boost spiritual tourism and exports.', 'સોમનાથ મહાદેવ મંદિરના રમણીય વારાણસી તર્જ પર બનેલા સમુદ્ર દર્શન પથ પર ભક્તોનો આનંદ.', 'सोमनाथ महादेव मंदिर के सुरम्य समुद्र दर्शन पथ पर श्रद्धालुओं का उत्साह।', '<p>પ્રથમ જ્યોતિર્લિંગ ગીર સોમનાથ મંદિર પરિસરમાં દરિયાકિનારે ૧.૫ કિલોમીટર લાંબો વોકવે \'સમુદ્ર દર્શન પથ\' પ્રવાસીઓ માટે આકર્ષણ બન્યો છે. નજીકમાં આવેલા વેરાવળ ફિશિંગ પોર્ટના આધુનિકીકરણથી સાગર ખેડૂતોને પ્રોત્સાહન મળ્યું છે.</p>', '<p>પ્રથમ જ્યોતિર્લિંગ ગીર સોમનાથ મંદિર પરિસરમાં દરિયાકિનારે \'સમુદ્ર દર્શન પથ\' આકર્ષણ બન્યો છે.</p>', '<p>प्रथम ज्योतिर्लिंग गिर सोमनाथ मंदिर परिसर में समुद्र दर्शन पथ आकर्षण बना हुआ है।</p>', 'https://images.unsplash.com/photo-1509316975850-ff9c5deb0cd9?w=1200&q=90', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '968c7b79-e486-4a36-8720-99f33c015339', 'Gir Somnath', 0, 0, 1, 0, 1, 14, NULL, NULL, NULL, NULL, NULL, '2026-08-12 06:12:35', '2026-08-19 04:51:16');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('f8a32bfd-2d4b-49c8-ad57-2c0e493f6178', 'fact-check-gujarat-board-ssc-hsc-exam-paper-leak-fake-letter', 235, 'Fact Check: Viral Circular Claiming GSEB Board Question Paper Leak is Fabricated', 'ફેક્ટ ચેક: ગુજરાત માધ્યમિક બોર્ડ (GSEB) ની ધોરણ ૧૦ અને ૧૨ની પરીક્ષાના પેપર લીક અંગેનો પરિપત્ર નકલી', 'फैक्ट चेक: गुजरात बोर्ड (GSEB) 10वीं और 12वीं की परीक्षा के पेपर लीक होने का परिपत्र फर्जी है', 'GSEB officially clarifies that viral Telegram circulars claiming board exam question paper leaks are completely fake and forged.', 'ગુજરાત માધ્યમિક અને ઉચ્ચતર માધ્યમિક શિક્ષણ બોર્ડે સ્પષ્ટ કર્યું છે કે પેપર લીકના નામે વાયરલ થયેલો લેટર પેડ પત્ર તદ્દન બોગસ છે.', 'गुजरात माध्यमिक और उच्चतर माध्यमिक शिक्षा बोर्ड ने स्पष्ट किया है कि पेपर लीक के नाम से वायरल हुआ पत्र पूरी तरह से फर्जी है।', '<p><strong>Claim:</strong> A letter carrying GSEB logo on Telegram claims Board Exam SSC & HSC question papers were leaked and exams will be rescheduled.</p>\n<h2>Fact Check Analysis</h2>\n<p>GSEB Board Chairman and examination controllers confirmed no paper leak has occurred. Cyber crime branch has registered an FIR against unauthorized Telegram channels circulating fake letters to extort students.</p>\n<ul>\n<li>Official exam schedules remain fully unchanged.</li>\n<li>Students are advised to trust only official notifications on <em>gseb.org</em>.</li>\n</ul>\n<blockquote>"Verdict: ❌ FABRICATED & FORGED LETTER. Cyber police taking legal action against scammers."</blockquote>', '<p><strong>દાવો:</strong> ટેલિગ્રામ અને વોટ્સએપ પર GSEBના લોગો વાળો એક પરિપત્ર વાયરલ થયો છે જેમાં દાવો કરાયો છે કે ધોરણ ૧૦ અને ૧૨ના પેપર લીક થઈ ગયા છે અને પરીક્ષાઓ રદ કરવામાં આવી છે.</p>\n<h2>તપાસ અને સાચું તથ્ય</h2>\n<p>શિક્ષણ બોર્ડના અધ્યક્ષ અને પરીક્ષા સચિવે સ્પષ્ટતા કરી છે કે કોઈપણ પેપર લીક થયું નથી અને પરીક્ષાઓ નિર્ધારિત ટાઇમટેબલ મુજબ જ યોજાશે. વાયરલ પરિપત્ર તદ્દન બોગસ અને એડિટ કરેલો છે.</p>\n<ul>\n<li>વિદ્યાર્થીઓ અને વાલીઓને માત્ર <strong>gseb.org</strong> સત્તાવાર પોર્ટલ પર વિશ્વાસ રાખવા અપીલ કરાઈ છે.</li>\n<li>અફવા ફેલાવનાર બોગસ ટેલિગ્રામ ચેનલો સામે સાયબર ક્રાઇમમાં ગુનો નોંધવામાં આવ્યો છે.</li>\n</ul>\n<blockquote>"ચુકાદો: ❌ તદ્દન નકલી અને બોગસ પત્ર."</blockquote>', '<p><strong>दावा:</strong> बोर्ड परीक्षाएं रद्द होने और पेपर लीक होने का पत्र वायरल हो रहा है।</p>\n<h2>सच्चाई</h2>\n<p>गुजरात बोर्ड ने इस पत्र को फर्जी घोषित किया है और परीक्षाएं अपने निर्धारित समय पर ही होंगी।</p>\n<blockquote>"फैसला: ❌ फर्जी अफवाह।"</blockquote>', 'https://images.unsplash.com/photo-1434030216411-0b793f4b4173?w=1200&q=80', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', 'b6423e89-dda8-489c-bd82-78e0fe179d65', NULL, 3, 91, 0, 1, 1, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-12 04:51:41', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('f97a2915-59d9-4af5-9b47-712a5c821294', 'gold-and-silver-rates-fluctuate-check-latest-prices-in-gujarat-115', 215, '#215 - Gold and silver rates fluctuate: Check latest prices in Gujarat - Full Ground Coverage', '#215 - સોના-ચાંદીના ભાવમાં ઉતાર-ચઢાવ: ગુજરાતમાં આજના ભાવ', '#215 - सोने-चांदी की कीमतों में उतार-चढ़ाव: गुजरात में आज के भाव', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1541872703-74c5e44368f9?w=800&q=80', 'PUBLISHED', NULL, 'aabdf17b-1604-4701-b21f-38ad111c027f', 'f6650f9f-c367-4712-8ad1-18f599f12a53', NULL, 7, 6, 0, 0, 0, 2, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:46', '2026-08-17 10:01:09');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('fa46c998-2881-4f86-90c5-b1606b9c9b2c', 'amreli-gir-forest-sanctuary-asiatic-lion-population-surge', 256, 'Amreli Gir Forest Sanctuary reports healthy surge in Lion population', 'અમરેલી ગીર પૂર્વ અને ધારી વિસ્તારમાં એશિયાટિક સિંહોની સંખ્યામાં નોંધપાત્ર વધારો', 'अमरेली गिर वन क्षेत्र में एशियाई शेरों की आबादी में महत्वपूर्ण वृद्धि', 'Forest department confirms safe wildlife corridors and successful conservation in Amreli Gir region.', 'અમરેલી અને ધારી રેન્જમાં એશિયાટિક બબ્બર શેર અને બાળ સિંહોની સુરક્ષિત અવરજવર વધી.', 'अमरेली और धारी रेंज में एशियाई शेरों और शावकों की सुरक्षित आवाजाही बढ़ी।', 'અમરેલી જિલ્લામાં ગીર પૂર્વ વિસ્તાર અને ધારી રેન્જમાં એશિયાટિક સિંહોના પરિવારો ખુશહાલ વાતાવરણમાં વિચરતા જોવા મળ્યા છે. વન વિભાગના અસરકારક સંરક્ષણ અને સ્થાનિક ગ્રામજનોના સહયોગથી સિંહોની વસ્તીમાં સરાહનીય વધારો થયો છે.', 'અમરેલી જિલ્લામાં ગીર પૂર્વ વિસ્તાર અને ધારી રેન્જમાં એશિયાટિક સિંહોના પરિવારો ખુશહાલ વાતાવરણમાં વિચરતા જોવા મળ્યા છે.', 'अमरेली जिले के गिर पूर्व क्षेत्र और धारी रेंज में एशियाई शेरों के परिवार स्वच्छंद रूप से घूमते देखे गए हैं।', 'https://images.unsplash.com/photo-1534188753412-3e26d0d618d6?auto=format&fit=crop&w=1200&q=90', 'PUBLISHED', NULL, '142f3099-7bcb-4e0d-9d9a-d469066dce12', '968c7b79-e486-4a36-8720-99f33c015339', 'Amreli', 0, 0, 1, 0, 1, 0, NULL, NULL, NULL, NULL, NULL, '2026-08-12 05:32:08', '2026-08-14 11:11:58');
INSERT INTO `posts` (`id`, `slug`, `articleNumber`, `title`, `titleGu`, `titleHi`, `excerpt`, `excerptGu`, `excerptHi`, `content`, `contentGu`, `contentHi`, `featuredImage`, `status`, `scheduledAt`, `authorId`, `categoryId`, `location`, `readingTime`, `priority`, `isTrending`, `isBreaking`, `isFeatured`, `views`, `seoTitle`, `seoDescription`, `seoKeywords`, `canonicalUrl`, `metaRobots`, `createdAt`, `updatedAt`) VALUES ('fc5dfa8e-b5d8-4210-ac73-081a5c8b9874', 'monsoon-update-gujarat-weather-forecast-for-next-week-42', 142, '#142 - Monsoon update: Gujarat weather forecast for next week - Full Ground Coverage', '#142 - ચોમાસું અપડેટ: ગુજરાતમાં આગામી સપ્તાહનું હવામાન', '#142 - मानसून अपडेट: गुजरात में अगले सप्ताह का मौसम', 'A Gujarat Post special report explains how the development could affect residents, businesses and public administration.', 'ગુજરાત પોસ્ટની ખાસ રિપોર્ટ પ્રમાણે આ નિર્ણયથી સ્થાનિક લોકો, વેપાર અને વહીવટી વ્યવસ્થામાં સીધી અસર પડશે.', 'गुजरात पोस्ट की विशेष रिपोर्ट के अनुसार इस फैसले से स्थानीय लोगों, कारोबार और प्रशासन पर सीधा असर पड़ेगा.', 'Officials said detailed planning began soon after the latest decision. Dedicated teams are working to ensure timely public updates and smooth coordination between departments.', 'સ્થાનિક અધિકારીઓએ જણાવ્યું કે તાજેતરના નિર્ણય બાદ વિસ્તૃત આયોજન શરૂ કરી દેવામાં આવ્યું છે. લોકો સુધી જરૂરી માહિતી ઝડપથી પહોંચે તે માટે અલગ ટીમો કાર્યરત છે.', 'स्थानीय अधिकारियों ने बताया कि ताजा फैसले के बाद विस्तृत योजना पर काम शुरू कर दिया गया है. लोगों तक जरूरी जानकारी तेजी से पहुंचाने के लिए अलग टीमें सक्रिय हैं.', 'https://images.unsplash.com/photo-1605649487212-47bdab064df7?w=800&q=80', 'PUBLISHED', NULL, '6e329fea-cd2d-4295-a98e-64bddfe20da6', '66d1efc9-15ca-49af-b951-cff8c138d92b', NULL, 4, 79, 0, 0, 0, 1, NULL, NULL, NULL, NULL, NULL, '2026-08-07 12:23:19', '2026-08-17 10:00:49');
